window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-1/eaif","titre":"EAIF I","sources":[{"t":"EAIF I — Corps et conscience","q":"qcm/corps-conscience-01.html","f":"fiches/corps-conscience-01.html"},{"t":"EAIF I — Cadre anatomique et physiologique","q":"qcm/massage-01-anatomie.html","f":"fiches/massage-01-anatomie.html"},{"t":"EAIF I — Le toucher et la peau","q":"qcm/massage-02-toucher-peau.html","f":"fiches/massage-02-toucher-peau.html"},{"t":"EAIF I — Modèle physiologique de la thérapie manuelle","q":"qcm/massage-03-therapie-manuelle.html","f":"fiches/massage-03-therapie-manuelle.html"},{"t":"EAIF I — Introduction au massage","q":"qcm/massage-04-introduction.html","f":"fiches/massage-04-introduction.html"},{"t":"EAIF I — Effleurage","q":"qcm/massage-05-effleurage.html","f":"fiches/massage-05-effleurage.html"},{"t":"EAIF I — Pétrissage","q":"qcm/massage-06-petrissage.html","f":"fiches/massage-06-petrissage.html"},{"t":"EAIF I — Tapotement","q":"qcm/massage-07-tapotement.html","f":"fiches/massage-07-tapotement.html"},{"t":"EAIF I — Friction","q":"qcm/massage-08-friction.html","f":"fiches/massage-08-friction.html"},{"t":"EAIF I — Mobilisation articulaire — concepts","q":"qcm/mobart-01-concepts.html","f":"fiches/mobart-01-concepts.html"},{"t":"EAIF I — Mouvements des membres (MS + MI)","q":"qcm/mobart-02-mouvements-membres.html","f":"fiches/mobart-02-mouvements-membres.html"},{"t":"EAIF I — Programme de l'UC","q":"qcm/programme-uc.html","f":"fiches/programme-uc.html"},{"t":"EAIF I — Positionnements et mobilité précoce","q":"qcm/ptam-01-positionnements.html","f":"fiches/ptam-01-positionnements.html"},{"t":"EAIF I — Transferts et biomécanique","q":"qcm/ptam-02-transferts.html","f":"fiches/ptam-02-transferts.html"},{"t":"EAIF I — Aides à la marche et types de marche","q":"qcm/ptam-03-aides-marche.html","f":"fiches/ptam-03-aides-marche.html"},{"t":"EAIF I — Cahier Positions / Mobilité / Transferts","q":"qcm/ptam-04-support-positions.html","f":"fiches/ptam-04-support-positions.html"},{"t":"EAIF I — Manuel des aides à la marche","q":"qcm/ptam-05-support-aides-marche.html","f":"fiches/ptam-05-support-aides-marche.html"}],"questions":[{"q":"Le kinésithérapeute est défini comme :","o":["Spécialiste des médicaments","Spécialiste en techniques corporelles et professionnel du contact","Chirurgien","Psychologue"],"r":1,"e":"Le kinésithérapeute est un SPÉCIALISTE en techniques corporelles ET un professionnel du CONTACT.","s":0},{"q":"À quelle semaine de grossesse les premières sensations tactiles apparaissent-elles ?","o":["3e semaine","5e semaine","7e semaine","12e semaine"],"r":2,"e":"À la 7e semaine de grossesse : sensations dans la bouche, mains et pieds (le sommet du crâne reste insensible).","s":0},{"q":"Le toucher INSTRUMENTAL se caractérise par :","o":["Force faible, contact large, communicatif","Local, bref, force élevée, mécanique, non impliqué","Empathie et compréhension","Toujours douloureux"],"r":1,"e":"Instrumental = LOCAL, BREF, force ÉLEVÉE, mécanique, NON impliqué, correctif.","s":0},{"q":"Le toucher EXPRESSIF se caractérise par :","o":["Mécanique et bref","Large, maintien du contact, force faible/moyenne, empathique","Force maximale","Sans contact"],"r":1,"e":"Expressif = LARGE, MAINTIEN du contact, force FAIBLE/moyenne, empathique, communicatif, touche TOUTE la personne.","s":0},{"q":"Quelle structure cérébrale est responsable de l'analyse des risques et expériences (origine des émotions) ?","o":["Hippocampe","Amygdale","Hypothalamus","Cervelet"],"r":1,"e":"L'AMYGDALE analyse les risques et expériences — de là naissent les réactions émotionnelles.","s":0},{"q":"L'hippocampe est responsable de :","o":["Faim et soif","Mémoire et orientation","Émotions","Réflexes"],"r":1,"e":"L'HIPPOCAMPE = mémoire et orientation. Les maladies de la mémoire (Alzheimer) l'affectent directement.","s":0},{"q":"Le cortex insulaire est important pour :","o":["L'audition uniquement","L'empathie et la transformation des sensations en émotions","Le mouvement","La digestion"],"r":1,"e":"L'INSULA + cortex somatosensoriel droit = EMPATHIE (Caselli, 1997). Module aussi la douleur.","s":0},{"q":"Le modèle des 4 homoncules sensoriels a été proposé par :","o":["Penfield","Damásio","John Kaas (1987)","Merleau-Ponty"],"r":2,"e":"John Kaas (1987) : 4 homoncules sensoriels (longueur musculaire, récepteurs cutanés lents/rapides, sensations articulaires/pression).","s":0},{"q":"Le nouveau modèle somatosensoriel de Damásio (1999) intègre :","o":["Uniquement S1","Tronc cérébral, hypothalamus, insula, S2 et S1 (homoncule)","Cervelet seul","Aucune structure"],"r":1,"e":"Damásio : 'Soi neural' = noyaux réticulaires du tronc cérébral + hypothalamus + insula + S2 + S1.","s":0},{"q":"La privation de contact chez l'enfant peut entraîner :","o":["Aucun effet","Retard du développement intellectuel et physique, infections récurrentes","Surdéveloppement","Augmentation des défenses immunitaires"],"r":1,"e":"Privation = retard de développement, infections/accidents plus fréquents, comportements autorégulateurs (privation de berceau).","s":0},{"q":"La somatognosie est :","o":["Une maladie","La capacité à reconnaître les parties du corps","Une technique de relaxation","Un type de toucher"],"r":1,"e":"Somatognosie = capacité à RECONNAÎTRE les parties du corps, essentielle à la stabilité émotionnelle.","s":0},{"q":"Les 3 objectifs de la relaxation selon Titlebaum (1988) sont :","o":["Sport, alimentation, sommeil","Préventif, traitement, gestion du stress","Médicaments, repos, activité","Aucun"],"r":1,"e":"Titlebaum (1988) : préventif (protéger les organes), traitement (HTA, insomnie, asthme...), compétence de gestion du stress.","s":0},{"q":"Ryman (1995) définit la relaxation comme :","o":["Un sommeil profond","Un état de conscience caractérisé par paix et soulagement de tension/anxiété/peur","Une absence d'activité","Une méditation"],"r":1,"e":"Ryman (1995) : état de CONSCIENCE caractérisé par paix et soulagement de la tension, anxiété, peur.","s":0},{"q":"La relaxation cherche :","o":["Le sommeil","L'homéostasie physique et mentale","L'inactivité","La fatigue"],"r":1,"e":"Recherche de l'HOMÉOSTASIE physique et mentale, rétablissement de l'équilibre.","s":0},{"q":"La relaxation musculaire progressive a été développée par :","o":["Schultz","Jacobson (1938)","Benson","Mitchell"],"r":1,"e":"Jacobson (1938) : relaxation musculaire progressive — alterner contraction/relâchement musculaire.","s":0},{"q":"Le training autogène a été développé par :","o":["Jacobson","Schultz & Luthe (1969)","Mitchell","Alexander"],"r":1,"e":"Schultz & Luthe (1969) : training autogène, méthode psychologique.","s":0},{"q":"L'eutonie est une méthode développée par :","o":["Mitchell","Gerda Alexander","Benson","Jacobson"],"r":1,"e":"EUTONIE de Gerda Alexander = méthode de rééducation GLOBALE.","s":0},{"q":"L'effet du toucher thérapeutique sur l'axe HPA est :","o":["↑ libération de cortisol","↓ libération de cortisol","Aucun effet","Augmentation du stress"],"r":1,"e":"Le toucher DIMINUE la libération de cortisol via l'axe hypothalamo-hypophyso-surrénalien.","s":0},{"q":"Le système vestibulaire :","o":["Détecte les goûts","Cartographie les coordonnées du corps dans l'espace (posture de la tête)","Voit les couleurs","Contrôle la digestion"],"r":1,"e":"Système vestibulaire = coordonnées corporelles dans l'espace, particulièrement la POSTURE DE LA TÊTE.","s":0},{"q":"La peau, en tant qu'organe :","o":["Est le plus petit organe","Est le PLUS GRAND organe du corps, transforme stimuli physiques en états chimiques/psychologiques","N'a pas de récepteurs","Ne participe pas au toucher"],"r":1,"e":"La peau = PLUS GRAND organe du corps, transforme stimuli physiques en communicateurs chimiques et états psychologiques.","s":0},{"q":"Les expériences négatives de toucher (abus) nécessitent souvent :","o":["Plus de contact direct","Utilisation d'objets médiateurs dans la relation","Aucune adaptation","Arrêt de la thérapie"],"r":1,"e":"Aversion au toucher → utiliser des OBJETS qui médiatisent la relation pour préserver le travail thérapeutique.","s":0},{"q":"« Là où le corps et l'esprit se rencontrent » décrit :","o":["L'hippocampe","L'insula (cortex insulaire)","Le cervelet","L'amygdale"],"r":1,"e":"L'INSULA est décrite comme « là où le corps et l'esprit se rencontrent ».","s":0},{"q":"Selon Merleau-Ponty (1999), être une conscience c'est :","o":["Penser sans le corps","Communiquer intérieurement avec le monde, le corps et les autres","Être seul","Refuser le toucher"],"r":1,"e":"Merleau-Ponty : être conscience = COMMUNIQUER intérieurement avec le monde, le corps et les autres (être AVEC eux).","s":0},{"q":"L'effet anxiolytique du toucher thérapeutique passe par :","o":["Le cervelet","Activation hypothalamique antérieure réduisant tension musculaire et anxiété","Le muscle","L'os"],"r":1,"e":"Activation de la région HYPOTHALAMIQUE ANTÉRIEURE → réduction de la tension musculaire et de l'anxiété.","s":0},{"q":"Une bonne respiration pour amorcer la relaxation est :","o":["Rapide et superficielle","Profonde et régulière, sans tension musculaire ou de la bouche","Bloquée","Très lente uniquement"],"r":1,"e":"Respirations PROFONDES et RÉGULIÈRES, SANS tension. Relaxer le corps relaxe automatiquement l'esprit.","s":0},{"q":"L'insula est impliquée dans :","o":["La motricité fine","L'intéroception (conscience des sensations corporelles internes)","La vision","L'audition"],"r":1,"e":"Insula = aire clé de l'intéroception (rythme cardiaque, faim, douleur, émotions corporelles).","s":0},{"q":"La théorie des marqueurs somatiques de Damasio explique que :","o":["Les décisions sont purement rationnelles","Les états corporels (émotions) guident les décisions","Les émotions n'existent pas","Aucun lien corps-cerveau"],"r":1,"e":"Marqueurs somatiques : associations corps-émotion-mémoire qui orientent rapidement nos choix.","s":0},{"q":"Le système limbique est principalement :","o":["Moteur","Émotionnel et mnésique","Sensoriel pur","Endocrinien"],"r":1,"e":"Système limbique (hippocampe, amygdale, cortex cingulaire) = émotions, mémoire émotionnelle, motivation.","s":0},{"q":"La relaxation active (PNF de Jacobson) procède par :","o":["Étirement passif seul","Contraction puis relâchement progressif des groupes musculaires","Massage","Hypnose"],"r":1,"e":"Jacobson : contracter-relâcher chaque groupe musculaire successivement pour apprendre à reconnaître et lâcher la tension.","s":0},{"q":"Le toucher thérapeutique conscient (pleine présence) :","o":["N'a aucun effet","Active le parasympathique, ↓ cortisol, ↑ bien-être","Augmente le stress","Provoque la douleur"],"r":1,"e":"Toucher attentif → activation parasympathique (vague), ↓ cortisol, libération d'ocytocine, sécurité affective.","s":0},{"q":"Le kinésithérapeute est décrit comme :","o":["Un spécialiste des techniques corporelles et un professionnel du contact","Un technicien du mouvement","Un rééducateur fonctionnel","Un soignant polyvalent"],"r":0,"e":"Ses techniques impliquent de toucher et d'être touché, parfois médiatisé par des objets en début de relation.","s":0},{"q":"Parmi les stratégies pour parler de soi, le cours cite :","o":["Le souvenir d'enfance, « qui suis-je ? » et « qui est-ce que je veux être ? »","Le seul récit de vie","Le seul bilan fonctionnel","L'entretien directif"],"r":0,"e":"Elles s'adaptent à l'âge et à l'état clinique.","s":0},{"q":"La notion de « corps-sujet » signifie que :","o":["La propriété et la capacité d'action sont liées à un corps dans un espace et un temps donnés, et que je suis le seul à pouvoir agir depuis mon corps","Le corps est un objet","Le corps est indépendant de l'esprit","Le corps est interchangeable"],"r":0,"e":"Merleau-Ponty (1999) exprime ce lien : être une conscience, c'est communiquer intérieurement avec le monde, le corps et les autres.","s":0},{"q":"La voie de signalisation somatosensorielle suit l'ordre :","o":["Moelle, tronc cérébral, cortex cérébral","Cortex, tronc, moelle","Tronc, moelle, cortex","Moelle, cortex, tronc"],"r":0,"e":"Elle aboutit à une carte des dimensions de l'état corporel.","s":0},{"q":"Le système de l'environnement interne et viscéral implique :","o":["Le tronc cérébral, l'hypothalamus, les signaux de douleur viscérale et le système nerveux autonome","Le système vestibulaire","La peau","Le cortex moteur"],"r":0,"e":"Les trois systèmes de signalisation sont l'interne et viscéral, le vestibulaire et musculo-squelettique, et le tactile.","s":0},{"q":"La perspective psychanalytique du corps étudie :","o":["Le soi corporel, les introjections et projections, le symbolisme corporel et l'émergence du Soi","Les relations entre sensations et actions","La corporéité et la spatialité","L'intelligence spatiale"],"r":0,"e":"Les perspectives neurologique, phénoménologique et psychologique complètent ce panorama.","s":0},{"q":"La perspective psychologique du corps étudie :","o":["Les préludes de la pensée, l'intelligence spatiale et le rôle intégrateur gnosique et praxique","Le symbolisme corporel","La corporéité","Les sensations et perceptions"],"r":0,"e":"La perspective phénoménologique porte sur la corporéité, la spatialité-temporalité et le positionnement subjectif.","s":0},{"q":"Parmi les stimuli prénataux du toucher, le cours cite :","o":["Le mouvement de la mère, les pulsations, le rythme respiratoire et diaphragmatique et le péristaltisme","La seule voix maternelle","La seule lumière","Les seuls sons"],"r":0,"e":"La sensation du toucher est la première à devenir fonctionnelle dans la vie embryonnaire.","s":0},{"q":"À la 7ᵉ semaine de grossesse, les sensations apparaissent :","o":["Dans la bouche, les mains et les pieds, le sommet du crâne restant insensible","Sur tout le corps","Au seul visage","Aux seules mains"],"r":0,"e":"Cette chronologie illustre l'antériorité du toucher sur les autres sens.","s":0},{"q":"La peau transforme :","o":["Les stimuli physiques en communicateurs chimiques et états psychologiques","Les émotions en mouvements","Les sons en sensations","La lumière en chaleur"],"r":0,"e":"Un contact grossier ou agressif suscite rejet, mépris, invalidation, réaction défensive et colère.","s":0},{"q":"Les effets proprioceptifs du toucher thérapeutique consistent à :","o":["Stimuler et réguler les émotions et aider à l'intégration somatognostique","Augmenter la force","Améliorer l'amplitude","Réduire l'œdème"],"r":0,"e":"Le toucher expressif touche toute la personne, avec empathie et compréhension.","s":0},{"q":"La privation de contact chez l'enfant entraîne :","o":["Un retard du développement intellectuel et physique et des infections, maladies et accidents plus fréquents","Une simple timidité","Un retard moteur isolé","Aucune conséquence"],"r":0,"e":"La privation de berceau induit des comportements autorégulateurs, et la privation peut conduire à une maladie mentale à l'âge adulte.","s":0},{"q":"Chez la personne âgée, la privation de contact entraîne :","o":["Une détérioration de l'image corporelle et un isolement aggravé par la réduction des autres modalités sensorielles","Une amélioration de l'autonomie","Une stimulation cognitive","Aucun effet"],"r":0,"e":"Le cours établit un lien entre manque de contact physique et social et mort prématurée.","s":0},{"q":"En cas de danger, de handicap, d'anxiété ou de maladie, le cours décrit :","o":["Une régression vers les besoins tactiles du début de la vie","Une aversion au toucher","Une indifférence","Une hypersensibilité"],"r":0,"e":"Le besoin de contact diminue par ailleurs avec l'âge.","s":0},{"q":"Devant une aversion au toucher liée à des expériences d'abus, il faut :","o":["Utiliser des objets médiateurs","Insister progressivement","Renoncer à toute technique","Augmenter la pression"],"r":0,"e":"Les origines de l'interprétation du toucher tiennent aux expériences antérieures, aux croyances, à la culture et à l'éducation.","s":0},{"q":"La stabilité émotionnelle suppose :","o":["Une somatognosie organisée et une stabilité sensorielle, proprioceptive, tactile et vestibulaire","La seule somatognosie","La seule stabilité tactile","Le seul contrôle cognitif"],"r":0,"e":"Toutes les émotions utilisent le « théâtre du corps » pour se manifester.","s":0},{"q":"Les cinq voies de stimulation sensorielle citées sont :","o":["Tactile, auditive, visuelle, olfactive et gustative","Tactile, proprioceptive et vestibulaire","Visuelle et auditive","Tactile et thermique"],"r":0,"e":"Le toucher thérapeutique constitue la voie tactile.","s":0},{"q":"Le modèle des 4 homoncules sensoriels de John Kaas (1987) distingue :","o":["La longueur musculaire, les récepteurs cutanés lents et rapides et les sensations articulaires et de pression","Quatre régions corticales","Quatre modalités émotionnelles","Quatre voies ascendantes"],"r":0,"e":"Il succède au modèle de l'homoncule unique de Wilder Penfield.","s":0},{"q":"Le « Soi neural » de Damásio (1999) inclut :","o":["Les noyaux réticulaires du tronc cérébral, l'hypothalamus, le cortex insulaire, S2 et S1","Le seul cortex insulaire","Le seul système limbique","Le seul homoncule"],"r":0,"e":"Il associe le corps et l'émotion dans un nouveau modèle somatosensoriel.","s":0},{"q":"Le système vestibulaire fournit :","o":["Les coordonnées du corps dans l'espace","La sensibilité tactile","La douleur viscérale","La température"],"r":0,"e":"Il appartient au système vestibulaire et musculo-squelettique, celui de la proprioception.","s":0},{"q":"Quels systèmes sont touchés indirectement lorsqu'on touche la peau ?","o":["Aucun","Lymphatique, circulatoire, nerveux","Digestif uniquement","Squelettique uniquement"],"r":1,"e":"Toucher la peau implique d'agir sur les systèmes lymphatique, circulatoire et nerveux qui traversent toutes les couches.","s":1},{"q":"Sur la face antérieure, sous le muscle dans la moitié supérieure du tronc, on trouve :","o":["Organes abdominaux","Cage thoracique, poumons et cœur","Vertèbres lombaires","Reins"],"r":1,"e":"Moitié supérieure antérieure : cage thoracique, poumons, cœur.","s":1},{"q":"À l'arrière du cou, sous la couche musculaire, se trouve :","o":["Trachée","Colonne vertébrale et moelle épinière","Larynx","Thyroïde"],"r":1,"e":"À l'arrière du cou : colonne vertébrale + moelle épinière + racines nerveuses cervicales postéro-latérales.","s":1},{"q":"À l'avant du cou, sous la couche musculaire, on trouve :","o":["Cerveau","Thyroïde, larynx, trachée","Moelle épinière","Cage thoracique"],"r":1,"e":"Avant du cou : parties supérieures des systèmes digestif et respiratoire (thyroïde, larynx, trachée).","s":1},{"q":"Le visage est une région :","o":["Peu innervée","Hautement innervée","Sans vaisseaux","Sans ganglions"],"r":1,"e":"Région hautement innervée + vaisseaux et ganglions palpables.","s":1},{"q":"Le membre supérieur contient :","o":["Fémur, tibia, péroné","Omoplate, clavicule, humérus, radius, ulna, os du carpe, phalanges","Rotule","Os du tarse"],"r":1,"e":"Membre supérieur : omoplate, clavicule, humérus, radius, ulna, os du carpe, phalanges.","s":1},{"q":"Le membre inférieur contient :","o":["Humérus, radius","Fémur, rotule, tibia, péroné, tarse, phalanges","Clavicule","Carpe"],"r":1,"e":"Membre inférieur : fémur, rotule, tibia, péroné, tarse, phalanges.","s":1},{"q":"L'ordre des couches anatomiques superficielles → profondes est :","o":["Os → muscle → peau","Peau → muscle → os/organes","Muscle → peau → os","Indifférent"],"r":1,"e":"Peau (système tégumentaire) → muscles → os et organes profonds.","s":1},{"q":"Les racines nerveuses cervicales postéro-latérales se prolongent vers :","o":["Les MI","Les membres supérieurs","Le visage","Les reins"],"r":1,"e":"Les racines nerveuses postéro-latérales de la colonne cervicale se prolongent vers les MEMBRES SUPÉRIEURS.","s":1},{"q":"Sur la face postérieure du tronc, la ligne médiane contient :","o":["Le cœur","La colonne vertébrale","Les poumons","Le foie"],"r":1,"e":"Ligne médiane postérieure du tronc = colonne vertébrale.","s":1},{"q":"Sous les muscles de la tête, en suivant la couche, on trouve :","o":["L'estomac","Os du crâne, cerveau, tronc cérébral","La trachée","Le cœur"],"r":1,"e":"Tête : sous les muscles/aponévroses → os du crâne, cerveau, tronc cérébral.","s":1},{"q":"Quel système n'a PAS de couche dédiée mais traverse toutes les autres ?","o":["Squelettique","Circulatoire (et lymphatique, nerveux)","Tégumentaire","Musculaire"],"r":1,"e":"Les systèmes circulatoire, lymphatique et nerveux traversent toutes les couches anatomiques.","s":1},{"q":"L'omoplate fait partie :","o":["Du membre inférieur","Du membre supérieur","Du crâne","Du tronc"],"r":1,"e":"L'omoplate (scapula) fait partie du membre supérieur.","s":1},{"q":"Quel os est unique au membre inférieur dans la liste ?","o":["Humérus","Rotule","Radius","Clavicule"],"r":1,"e":"Rotule = patella, unique au membre inférieur.","s":1},{"q":"L'ulna se trouve :","o":["Au pied","À l'avant-bras (membre supérieur)","Au crâne","Au bassin"],"r":1,"e":"L'ulna (cubitus) fait partie de l'avant-bras.","s":1},{"q":"Le tarse appartient à :","o":["L'avant-bras","Le poignet","Le pied (membre inférieur)","La main"],"r":2,"e":"Os du tarse = arrière-pied (membre inférieur). Le carpe est au poignet.","s":1},{"q":"Connaître les couches anatomiques sert au kiné à :","o":["Faire joli","Adapter le massage et anticiper les structures touchées","Rien","Refuser les patients"],"r":1,"e":"Connaître les couches permet d'anticiper quelles structures sont touchées par chaque type de pression.","s":1},{"q":"Quelle structure traverse la colonne vertébrale ?","o":["L'œsophage","La moelle épinière","La trachée","Le larynx"],"r":1,"e":"La moelle épinière traverse le canal rachidien à l'intérieur de la colonne vertébrale.","s":1},{"q":"Les ganglions lymphatiques sont palpables :","o":["Uniquement aux pieds","Au niveau du visage (et d'autres régions superficielles)","Jamais","Uniquement à la naissance"],"r":1,"e":"Au visage et dans d'autres régions superficielles, les ganglions et vaisseaux sont palpables.","s":1},{"q":"La cage thoracique contient :","o":["Reins et estomac","Poumons et cœur","Foie et pancréas","Intestins"],"r":1,"e":"Cage thoracique = poumons et cœur (organes vitaux protégés).","s":1},{"q":"L'humérus est l'os :","o":["De la cuisse","Du bras","Du tibia","De la main"],"r":1,"e":"Humérus = os unique du bras (entre épaule et coude).","s":1},{"q":"L'omoplate (scapula) s'articule avec :","o":["Le sternum directement","La clavicule (acromion) et l'humérus","Les côtes","Le radius"],"r":1,"e":"Scapula : acromio-claviculaire (clavicule) + gléno-humérale (humérus). Elle glisse sur le gril costal.","s":1},{"q":"Le triangle des Petit (lombaire) est délimité par :","o":["Trapèze, deltoïde, biceps","Latissimus dorsi, oblique externe, crête iliaque","Pectoral, deltoïde, biceps","Quadriceps, iliopsoas"],"r":1,"e":"Triangle des Petit (zone de faiblesse pariétale lombaire) = grand dorsal + oblique externe + crête iliaque.","s":1},{"q":"La région poplitée correspond à :","o":["Face antérieure du genou","Creux derrière le genou","Pli du coude","Aine"],"r":1,"e":"Région poplitée = creux postérieur du genou, contient l'artère poplitée, les nerfs tibial et fibulaire.","s":1},{"q":"Le creux axillaire contient principalement :","o":["Vaisseaux et nerfs du membre supérieur (plexus brachial, artère axillaire)","Que des muscles","Le sternum","Aucune structure"],"r":1,"e":"Creux axillaire (aisselle) : plexus brachial, artère et veine axillaires, ganglions lymphatiques importants.","s":1},{"q":"Le ligament inguinal sépare :","o":["Le thorax de l'abdomen","L'abdomen de la cuisse","La tête du cou","Le bras de l'avant-bras"],"r":1,"e":"Ligament inguinal = limite entre paroi abdominale antérieure et région inguino-fémorale (passage des vaisseaux fémoraux).","s":1},{"q":"Le diaphragme :","o":["Est un muscle accessoire","Est le principal muscle de l'inspiration et sépare thorax/abdomen","Est un os","N'a pas de rôle ventilatoire"],"r":1,"e":"Diaphragme : muscle inspiratoire principal, dôme musculo-tendineux séparant thorax et abdomen.","s":1},{"q":"Sur la face postérieure du tronc, on palpe d'abord :","o":["Le foie","Les apophyses épineuses des vertèbres","Les poumons","Le rectum"],"r":1,"e":"Apophyses épineuses = repères médians palpables, base de la palpation rachidienne.","s":1},{"q":"Quelle artère palper au pli du coude ?","o":["Carotide","Brachiale (humérale)","Fémorale","Tibiale postérieure"],"r":1,"e":"Artère brachiale (humérale) palpable au pli du coude, utilisée pour la pression artérielle.","s":1},{"q":"L'artère radiale se palpe :","o":["Au genou","À la face antérieure du poignet, côté pouce","Dans l'aisselle","Au cou"],"r":1,"e":"Pouls radial = face antérieure du poignet, côté radial (pouce), repère anatomique de référence.","s":1},{"q":"Connaître les couches anatomiques permet au kiné de :","o":["Faire de l'esthétique","Adapter la profondeur, la pression et la direction de la technique","Faire des incisions","Prescrire des médicaments"],"r":1,"e":"Cette connaissance guide le choix de la TECHNIQUE et de la PROFONDEUR pour atteindre la structure cible en toute sécurité.","s":1},{"q":"La couche squelettique et des organes est traversée par :","o":["Les systèmes circulatoire, lymphatique et nerveux","Le seul système circulatoire","Le seul système nerveux","Aucun autre système"],"r":0,"e":"Les trois couches sont, de la surface vers la profondeur, tégumentaire, musculaire, puis squelettique et organes.","s":1},{"q":"Toucher la peau revient à agir indirectement sur :","o":["Les systèmes lymphatique, circulatoire et nerveux, qui traversent toutes les couches","La seule peau","Le seul muscle","Le seul système nerveux"],"r":0,"e":"C'est le principe anatomique qui fonde l'effet systémique du toucher.","s":1},{"q":"Sous la couche musculaire, la moitié inférieure de la face antérieure correspond :","o":["Aux organes internes et abdominaux","À la cage thoracique","Aux poumons et au cœur","À la colonne vertébrale"],"r":0,"e":"La moitié supérieure correspond à la cage thoracique, aux poumons et au cœur, en face antérieure comme postérieure.","s":1},{"q":"La ligne médiane postérieure correspond, sous les muscles :","o":["À la colonne vertébrale","Aux organes abdominaux","Aux poumons","Au diaphragme"],"r":0,"e":"En arrière du cou, on trouve la colonne, la moelle épinière et les racines nerveuses cervicales postéro-latérales destinées aux membres supérieurs.","s":1},{"q":"Sous les muscles de la partie antérieure du cou se trouvent :","o":["La thyroïde, le larynx et la trachée","La colonne cervicale","Les racines nerveuses","L'œsophage seul"],"r":0,"e":"Ce sont les parties supérieures des systèmes digestif et respiratoire.","s":1},{"q":"Le visage se caractérise, sous la couche musculaire, par :","o":["Une région hautement innervée, avec vaisseaux circulatoires et ganglions lymphatiques palpables","Une faible innervation","Une absence de vaisseaux","Des os épais"],"r":0,"e":"Les os du crâne et du visage en constituent le plan profond.","s":1},{"q":"Sous les muscles et aponévroses de la tête se trouvent :","o":["Les os du crâne, le cerveau et le tronc cérébral","Le seul crâne","Le seul cerveau","Les seules méninges"],"r":0,"e":"Cette connaissance des plans conditionne la prudence des techniques appliquées à la tête.","s":1},{"q":"Parmi les os du membre supérieur cités figurent :","o":["L'omoplate et la clavicule","Le fémur","Le tibia","Le tarse"],"r":0,"e":"Humérus, radius, ulna, os du carpe et phalanges complètent la liste.","s":1},{"q":"Parmi les os du membre inférieur cités figurent :","o":["Le fémur, la rotule, le tibia, le péroné, les os du tarse et les phalanges","L'humérus","Le radius","La clavicule"],"r":0,"e":"Chaque massage traverse mécaniquement peau, muscle puis os ou organe.","s":1},{"q":"La couche tégumentaire comprend :","o":["L'épiderme, le derme et l'hypoderme","L'épiderme seul","Le derme seul","La peau et le muscle"],"r":0,"e":"C'est la couche la plus superficielle des trois plans tissulaires et organiques.","s":1},{"q":"La couche musculaire est constituée de :","o":["Muscles striés squelettiques","Muscles lisses","Muscle cardiaque","Tissu conjonctif"],"r":0,"e":"Elle occupe la position intermédiaire entre le tégument et le plan osseux et viscéral.","s":1},{"q":"Le principe à retenir du cadre anatomique du massage est que :","o":["Chaque massage traverse mécaniquement peau, muscle et os ou organe, mais affecte simultanément vaisseaux et nerfs qui traversent toutes les couches","Seul le plan touché est concerné","L'effet reste superficiel","Le massage n'atteint que la peau"],"r":0,"e":"C'est ce qui explique les effets à distance et globaux de la thérapie manuelle.","s":1},{"q":"Le toucher est-il essentiel en physiothérapie ?","o":["Non, optionnel","Oui, c'est essentiel","Parfois","Seulement en sport"],"r":1,"e":"Le toucher est essentiel en physiothérapie — il met en contact direct avec le patient (espace personnel).","s":2},{"q":"La peau et le SNC partagent :","o":["Aucune origine commune","La même origine embryonnaire (ectoderme)","Le même nom","La même fonction"],"r":1,"e":"Peau et SNC = MÊME ORIGINE EMBRYONNAIRE (ectoderme).","s":2},{"q":"3 cm de diamètre de peau contiennent environ :","o":["100 cellules","3 millions de cellules, 100-340 glandes, 50 terminaisons nerveuses, 90 cm de vaisseaux","Aucune structure","Que des poils"],"r":1,"e":"Densité exceptionnelle : >3M cellules, 100-340 glandes sudoripares, 50 terminaisons nerveuses, 90 cm vaisseaux.","s":2},{"q":"La couche cornée de l'épiderme :","o":["Est la plus profonde","Est superficielle, contient 20-30 couches de kératine, 1ère ligne de défense immunitaire","Est invisible","Produit la mélanine"],"r":1,"e":"Couche CORNÉE : superficielle, 20-30 couches, kératine, défensines = 1ère défense immunitaire.","s":2},{"q":"La couche basale de l'épiderme :","o":["Ne se divise pas","Contient des cellules mitotiquement actives + mélanocytes ; se connecte au derme","Est cornée","Est sans noyau"],"r":1,"e":"Couche basale = cellules mitotiquement actives (produisent les kératinocytes), contient les mélanocytes.","s":2},{"q":"La couche LUCIDE est :","o":["Présente partout","Présente uniquement sur paumes et plantes (peau épaisse)","Sur le visage","Inexistante"],"r":1,"e":"Couche lucide = uniquement sur peau ÉPAISSE (paumes, plantes), fine et transparente.","s":2},{"q":"Le derme PAPILLAIRE :","o":["Est profond","Est superficiel, en contact avec l'épiderme, tissu conjonctif lâche","Sans vaisseaux","Sans cellules"],"r":1,"e":"Papillaire = couche dermique SUPERFICIELLE, en contact avec l'épiderme, conjonctif LÂCHE.","s":2},{"q":"Le derme RÉTICULAIRE :","o":["Plus fin","Plus épais, moins cellulaire, conjonctif DENSE riche en collagène","Sans collagène","Superficiel"],"r":1,"e":"Réticulaire = couche dermique PROFONDE, dense, riche en collagène.","s":2},{"q":"L'hypoderme est aussi appelé :","o":["Épiderme","Fascia sous-cutané","Derme superficiel","Membrane basale"],"r":1,"e":"Hypoderme = FASCIA SOUS-CUTANÉ, couche la plus profonde de la peau, contient lobules adipeux.","s":2},{"q":"L'homéostasie est :","o":["Une maladie","Le processus qui maintient l'équilibre physiologique du corps","Une opération","Un récepteur"],"r":1,"e":"Homéostasie = équilibre et conservation des éléments physiologiques grâce à des mécanismes de régulation.","s":2},{"q":"Les mécanorécepteurs détectent :","o":["Température","Toucher et pression","Douleur","Goût"],"r":1,"e":"Mécanorécepteurs = toucher + pression.","s":2},{"q":"Les nocicepteurs détectent :","o":["Les couleurs","La douleur (mécanique, thermique, chimique)","Les sons","Les saveurs"],"r":1,"e":"Nocicepteurs = récepteurs de la DOULEUR (mécanique = pression excessive, thermique = T°C extrêmes, chimique = substances).","s":2},{"q":"Les corpuscules de PACINI détectent :","o":["La chaleur lente","Stimuli HAUTE fréquence (vibration, étirement, pression)","Aucun stimulus","La douleur"],"r":1,"e":"Pacini = HAUTE fréquence (vibration, étirement, pression). Meissner = vibration basse fréquence rapide.","s":2},{"q":"Les corpuscules de RUFFINI :","o":["Sont thermorécepteurs officiels","Action LENTE, étirement et pression profonde, peuvent percevoir chaleur","Vibrations rapides","Inexistants"],"r":1,"e":"Ruffini = action LENTE, étirement et pression PROFONDE, perception de chaleur (sans être classés thermorécepteurs).","s":2},{"q":"Les disques de MERKEL ont pour fonction :","o":["Nociception","Sensibilité tactile et pression SUPERFICIELLE","Vibration haute fréquence","Étirement"],"r":1,"e":"Disques de Merkel = sensibilité tactile + pression SUPERFICIELLE.","s":2},{"q":"Les corpuscules de MEISSNER :","o":["Pression profonde","Toucher discriminatif et vibration RAPIDE basse fréquence (papilles dermiques)","Douleur","Chaleur"],"r":1,"e":"Meissner = toucher DISCRIMINATIF + vibration rapide basse fréquence dans les papilles dermiques.","s":2},{"q":"Les terminaisons nerveuses LIBRES transmettent :","o":["Toucher discriminatif","Informations nociceptives et thermiques","Vibrations","Pression profonde"],"r":1,"e":"Terminaisons libres = NOCICEPTION + THERMIQUE.","s":2},{"q":"Une fonction immunitaire de la peau :","o":["Aucune","Surface contient kératine imperméabilisante + substances anti-microbiennes","Refroidit le sang","Produit l'insuline"],"r":1,"e":"Kératine imperméabilise + substances inhibant la croissance microbienne.","s":2},{"q":"La peau participe à la synthèse :","o":["De vitamine B12","De vitamine D","Du calcium","De l'oxygène"],"r":1,"e":"La peau participe à la synthèse de la VITAMINE D (sous l'effet du soleil).","s":2},{"q":"Le toucher dans l'enfance a une dimension :","o":["Uniquement physique","Physique, psychologique ET émotionnelle","Inutile","Dangereuse"],"r":1,"e":"Toucher dès le berceau = physique (limites du corps), psychologique (image interne), émotionnel (sentiments).","s":2},{"q":"Les informations transmises par les récepteurs incluent :","o":["Seulement l'intensité","Intensité, durée, position, direction","Aucune","Couleur"],"r":1,"e":"Récepteurs transmettent : INTENSITÉ, DURÉE, POSITION, DIRECTION du stimulus.","s":2},{"q":"Le kinésithérapeute évalue, planifie, intervient par :","o":["L'olfaction","L'observation et le TOUCHER","Le goût","La radiologie seule"],"r":1,"e":"Le kiné évalue, planifie et intervient par l'OBSERVATION et le TOUCHER.","s":2},{"q":"Quelle couche dermique est plus riche en collagène ?","o":["Papillaire","Réticulaire","Aucune","Cornée"],"r":1,"e":"Réticulaire = couche profonde, plus épaisse, DENSE, riche en fibres de collagène.","s":2},{"q":"Le toucher du kiné doit être :","o":["Brutal","Respectueux, agréable, rassurant, inspirer confiance","Hésitant","Distrait"],"r":1,"e":"Le toucher doit démontrer RESPECT, INSPIRER CONFIANCE, être AGRÉABLE et RASSURANT.","s":2},{"q":"L'épiderme se renouvelle environ tous les :","o":["3 jours","7 jours","28 jours","6 mois"],"r":2,"e":"Cycle de renouvellement de l'épiderme : ≈ 28 jours (de la couche basale à la desquamation cornée).","s":2},{"q":"Les corpuscules de Pacini répondent surtout à :","o":["Tact léger","Vibrations et pression profonde","Étirement","Chaleur"],"r":1,"e":"Pacini = mécanorécepteur profond (hypoderme), sensible aux vibrations et à la pression brève.","s":2},{"q":"Les corpuscules de Ruffini détectent :","o":["La douleur thermique","L'étirement cutané continu","Vibrations rapides","Le chatouillement"],"r":1,"e":"Ruffini = étirement cutané et adaptation lente (info posturale).","s":2},{"q":"Les terminaisons libres dans l'épiderme codent :","o":["La pression seule","La douleur, le chaud et le froid","Les vibrations","La position articulaire"],"r":1,"e":"Terminaisons nerveuses libres = douleur (nociception), thermoception (chaud/froid).","s":2},{"q":"La discrimination tactile (deux points) est meilleure :","o":["Au dos","Sur la pulpe des doigts et la langue","Sur la cuisse","Sur le mollet"],"r":1,"e":"Densité maximale de récepteurs = pulpe digitale + langue → discrimination très fine (1-2 mm).","s":2},{"q":"La sudation eccrine sert principalement à :","o":["L'odeur","La thermorégulation (évaporation)","La protection mécanique","La pigmentation"],"r":1,"e":"Glandes eccrines = sueur aqueuse, étalée sur tout le corps, rôle de thermorégulation par évaporation.","s":2},{"q":"Les glandes sébacées produisent :","o":["De la sueur","Du sébum (lubrifie peau et poils)","Du mucus","Du collagène"],"r":1,"e":"Glandes sébacées → sébum (mélange de lipides) qui imperméabilise et assouplit la peau.","s":2},{"q":"Le toucher affectif (caresse lente) est véhiculé par :","o":["Fibres Aβ rapides","Fibres C tactiles (CT) à conduction lente","Fibres Aα","Fibres Aδ thermiques"],"r":1,"e":"CT-afferents : fibres C non-myélinisées spécialisées dans le toucher affectif/social agréable.","s":2},{"q":"L'hyposensibilité cutanée :","o":["↑ le risque de blessures (escarres, brûlures non perçues)","Protège la peau","N'a aucune conséquence","Améliore la cicatrisation"],"r":0,"e":"Baisse de sensibilité = absence d'alarme → escarres, brûlures, plaies non détectées (diabète, neuropathies).","s":2},{"q":"Pour un toucher thérapeutique efficace, le kiné doit :","o":["Aller toujours très vite","Adapter pression, rythme et intention selon la zone et l'objectif","Toujours appuyer fort","Ne pas regarder le patient"],"r":1,"e":"Toucher de qualité = pression adaptée + rythme cohérent + intention claire + communication verbale et non-verbale.","s":2},{"q":"En touchant, le kinésithérapeute doit savoir :","o":["Comment toucher, ce qu'il touche et les effets de son toucher","Comment toucher uniquement","Ce qu'il touche uniquement","La durée du contact"],"r":0,"e":"Il entre dans l'espace personnel du patient : le toucher doit démontrer respect, inspirer confiance et être agréable et rassurant.","s":2},{"q":"La peau et le système nerveux central partagent :","o":["La même origine embryonnaire, l'ectoderme","Une origine mésodermique","Une origine endodermique","Aucune origine commune"],"r":0,"e":"Toucher la peau revient donc à toucher l'extension du cerveau.","s":2},{"q":"Trois centimètres de diamètre de peau contiennent :","o":["Plus de 3 millions de cellules, 100 à 340 glandes sudoripares, 50 terminaisons nerveuses et 90 cm de vaisseaux","1 million de cellules","10 terminaisons nerveuses","10 cm de vaisseaux"],"r":0,"e":"La peau est le plus grand organe du corps et permet l'homéostasie entre milieu interne et externe.","s":2},{"q":"La couche cornée comprend :","o":["20 à 30 couches de cellules squameuses anucléées riches en kératine","3 à 5 couches","8 à 10 couches","2 à 3 couches"],"r":0,"e":"Elle constitue la première ligne de défense immunitaire, par les défensines.","s":2},{"q":"La couche lucide comprend :","o":["2 à 3 couches fines et transparentes, présentes sur les paumes et les plantes","20 à 30 couches","8 à 10 couches","5 couches"],"r":0,"e":"Elle constitue un mécanisme de défense supplémentaire dans la peau épaisse.","s":2},{"q":"La couche granuleuse assure :","o":["La cohésion cellulaire et une barrière imperméable par les phospholipides","La production de kératinocytes","La défense immunitaire","La connexion au derme"],"r":0,"e":"Elle comprend 3 à 5 couches, riches en kératohyaline et granules lamellaires.","s":2},{"q":"La couche épineuse comprend :","o":["8 à 10 couches de cellules polyédriques et des cellules dendritiques","2 à 3 couches","20 couches","Une seule couche"],"r":0,"e":"Elle assure la production de kératine et une fonction immunologique.","s":2},{"q":"La couche basale se caractérise par :","o":["Des cellules cubiques ou cylindriques mitotiquement actives et des mélanocytes","Des cellules anucléées","Des cellules squameuses","L'absence de mitose"],"r":0,"e":"Elle produit les kératinocytes et assure la connexion au derme par les hémidesmosomes.","s":2},{"q":"Le derme est relié à l'épiderme par :","o":["La membrane basale","Les hémidesmosomes seuls","Le tissu conjonctif lâche","Les follicules pileux"],"r":0,"e":"Il comprend glandes sudoripares, follicules pileux, muscles, neurones sensoriels et vaisseaux.","s":2},{"q":"Le derme réticulaire se caractérise par :","o":["Un tissu conjonctif dense riche en collagène, plus épais et moins cellulaire","Un tissu conjonctif lâche","Une finesse","Une richesse cellulaire"],"r":0,"e":"Le derme papillaire, superficiel, est plus fin et fait de tissu conjonctif lâche.","s":2},{"q":"L'hypoderme, ou fascia sous-cutané, contient :","o":["Des lobules adipeux, des neurones sensoriels, des vaisseaux et de rares follicules pileux","Uniquement de la graisse","Uniquement des vaisseaux","Des glandes sudoripares abondantes"],"r":0,"e":"C'est la couche la plus profonde de la peau.","s":2},{"q":"La fonction immunitaire de la peau repose sur :","o":["La kératine imperméabilisante et des substances anti-microbiennes","La seule kératine","La seule thermorégulation","Les seuls mélanocytes"],"r":0,"e":"Protection, thermorégulation et excrétion des déchets métaboliques complètent ses fonctions.","s":2},{"q":"La protection cutanée s'exerce contre des agents :","o":["Physiques, chimiques, mécaniques et biologiques","Physiques seulement","Chimiques seulement","Biologiques seulement"],"r":0,"e":"C'est la première des fonctions de la peau citées.","s":2},{"q":"La densité fonctionnelle de la peau illustre :","o":["Qu'elle est le plus grand organe du corps et permet l'homéostasie entre milieu interne et externe","Sa fragilité","Son épaisseur","Sa vascularisation faible"],"r":0,"e":"Sa richesse en terminaisons nerveuses fonde l'efficacité du toucher thérapeutique.","s":2},{"q":"La thérapie manuelle agit :","o":["Uniquement sur le tissu local","Localement ET sur les systèmes neurologique, physiologique, psychologique","Uniquement sur le moral","Sans effet"],"r":1,"e":"La thérapie manuelle a des effets LOCAUX + NEUROLOGIQUES + PHYSIOLOGIQUES + PSYCHOLOGIQUES.","s":3},{"q":"Au niveau neurologique, le toucher peut :","o":["Augmenter la douleur","Stimuler ou désensibiliser, traiter la douleur, rééduquer posture/mouvement","Aucun effet","Provoquer des lésions"],"r":1,"e":"Le toucher : stimule/désensibilise, traite la douleur, rééduque posture/mouvement, fournit info sensorielle, intègre schéma corporel.","s":3},{"q":"Les émotions sont associées à des :","o":["Aucune réponse corporelle","Réponses somatiques (tonus musculaire, tolérance à la douleur)","Réponses uniquement mentales","Mouvements involontaires extrêmes"],"r":1,"e":"Les émotions provoquent des RÉPONSES SOMATIQUES : modifications du tonus musculaire, variations de la tolérance à la douleur.","s":3},{"q":"L'étirement (en thérapie manuelle) modifie le tissu en :","o":["Le compactant","Le rendant plus étroit et plus dense par agrégation du collagène","Augmentant le flux des fluides","Le détruisant"],"r":1,"e":"Étirement = remodelage par agrégation du collagène dans le sens des forces → tissu plus étroit et plus dense (peu d'effet sur les fluides).","s":3},{"q":"La compression a pour effet principal :","o":["Étirer les tissus","Raccourcir les fibres, augmenter la pression interne, FACILITER la circulation des fluides","Couper le sang","Détendre"],"r":1,"e":"Compression = raccourcissement fibres + ↑ pression interne → FACILITE la circulation des fluides.","s":3},{"q":"La rotation s'applique surtout aux :","o":["Muscles superficiels","Structures articulaires","Os","Peau"],"r":1,"e":"La rotation combine compression + étirement progressif → généralement appliquée aux structures ARTICULAIRES.","s":3},{"q":"La viscoplasticité est :","o":["Une seule technique","Une caractéristique de TOUS les tissus mous, dépend de la synthèse protéique et des liaisons transversales","Inutile","Un muscle"],"r":1,"e":"Viscoplasticité = caractéristique de TOUS les tissus mous. Dépend de la synthèse protéique et du nombre de liaisons transversales (densité).","s":3},{"q":"Une force IDENTIQUE sur une zone PETITE produit :","o":["Moins de pression","Une pression tissulaire PLUS IMPORTANTE (force concentrée)","La même pression","Aucun effet"],"r":1,"e":"Force concentrée sur petite zone = pression plus IMPORTANTE. Force dispersée sur grande zone = pression MOINDRE.","s":3},{"q":"Pourquoi les vertèbres lombaires sont-elles plus grandes que les cervicales ?","o":["Hasard","Pour supporter plus de poids (adaptation à la charge)","Pour la beauté","Pour le mouvement"],"r":1,"e":"Les structures s'adaptent aux CHARGES qu'elles supportent — les lombaires sont plus larges pour supporter plus de poids.","s":3},{"q":"La thérapie manuelle modifie les propriétés tissulaires :","o":["Aucune","Flexibilité, viscoplasticité, force, structurelles, physiologiques, et dynamique des fluides","Couleur","Forme uniquement"],"r":1,"e":"Modifications : flexibilité, viscoplasticité, force + structurelles/physiologiques + dynamique des fluides → réparation tissulaire.","s":3},{"q":"L'étirement a-t-il un grand effet sur le flux des fluides ?","o":["Oui beaucoup","Peu d'influence sur le flux des fluides","C'est son seul effet","Ne se sait pas"],"r":1,"e":"Étirement = remodelage du collagène mais PEU d'effet sur le flux des fluides. C'est la compression qui le facilite.","s":3},{"q":"La flexibilité est :","o":["Un seul exercice","Un travail GLOBAL sur la longueur des fibres incluant différentes techniques","Une caractéristique tissulaire","Une douleur"],"r":1,"e":"FLEXIBILITÉ = travail global. ÉTIREMENT = technique spécifique. VISCOPLASTICITÉ = caractéristique tissulaire.","s":3},{"q":"L'étirement est une technique :","o":["Globale","Spécifique visant un muscle/groupe précis avec timing précis","Aléatoire","Sans objectif"],"r":1,"e":"L'étirement est une technique CIBLÉE sur un groupe/muscle spécifique, avec timing précis.","s":3},{"q":"Les mains du kiné influencent des processus neurologiques :","o":["Uniquement locaux","Locaux, à distance ou globaux","Aucun","Seulement vasculaires"],"r":1,"e":"Les mains peuvent influencer des processus LOCAUX, À DISTANCE ou GLOBAUX (intégration corporelle).","s":3},{"q":"Le toucher fournit des informations :","o":["Visuelles","Sensorielles (proprioceptives + intégration du schéma corporel)","Auditives","Olfactives"],"r":1,"e":"Le toucher fournit des informations SENSORIELLES, contribue à la proprioception et à l'intégration du SCHÉMA CORPOREL.","s":3},{"q":"La compression facilite :","o":["L'étirement du collagène","La circulation des fluides","La sortie du sang","Rien"],"r":1,"e":"Compression = raccourcissement + ↑ pression interne tissulaire → FACILITE LA CIRCULATION DES FLUIDES.","s":3},{"q":"La torsion est un type de :","o":["Modification biomécanique combinée","Aucune force","Surface","Étirement pur"],"r":0,"e":"La torsion = mouvement combiné, souvent associé à la compression.","s":3},{"q":"En cas de lésion, la thérapie manuelle aide à :","o":["Aggraver","Rétablir les propriétés structurelles et fonctionnelles des tissus","Bloquer","Inhiber"],"r":1,"e":"Objectif clinique = rétablir les propriétés STRUCTURELLES et FONCTIONNELLES des tissus pour la réparation.","s":3},{"q":"Quelle technique combine compression et étirement progressif ?","o":["Étirement seul","Rotation","Friction","Tapotement"],"r":1,"e":"La ROTATION combine compression de la structure + étirement progressif dans l'axe de rotation.","s":3},{"q":"Les forces appliquées se propagent :","o":["De façon aléatoire","À travers les couches DANS LE SENS de l'application","À l'opposé","Sans se propager"],"r":1,"e":"Les forces se propagent à travers les couches DANS LE SENS de l'application de la force.","s":3},{"q":"Les effets antalgiques de la thérapie manuelle passent par :","o":["Le gate control (théorie du portillon) + libération d'endorphines","La paralysie nerveuse","Le saignement","La déshydratation"],"r":0,"e":"Antalgie par gate control (stimulation Aβ qui bloque les nociceptifs C/Aδ) + libération d'opioïdes endogènes.","s":3},{"q":"Sur le système circulatoire, le massage favorise :","o":["Une vasoconstriction généralisée","Une vasodilatation locale et un retour veino-lymphatique","Une chute brutale de PA","L'hémorragie"],"r":1,"e":"Massage = vasodilatation cutanée locale + drainage veineux et lymphatique.","s":3},{"q":"Sur le tonus musculaire, un massage profond et lent tend à :","o":["Augmenter le tonus","Diminuer le tonus (effet relaxant)","Provoquer des crampes","N'avoir aucun effet"],"r":1,"e":"Massage profond/lent → effet inhibiteur sur les motoneurones, ↓ tonus, ↑ extensibilité.","s":3},{"q":"L'effet psychologique principal du toucher thérapeutique est :","o":["L'agressivité","La détente, ↓ anxiété, ↑ bien-être","La confusion","Aucun"],"r":1,"e":"Toucher de qualité → activation parasympathique, libération d'ocytocine, ↓ anxiété, sentiment de soin.","s":3},{"q":"Une contre-indication majeure du massage est :","o":["Un patient au repos","Une thrombose veineuse profonde (TVP) ou phlébite","La fatigue passagère","Une cicatrice ancienne"],"r":1,"e":"CI absolues : TVP/phlébite (risque d'embolie), infections actives, plaies ouvertes, tumeurs malignes locales, fractures non consolidées.","s":3},{"q":"Avant tout massage, le kiné doit :","o":["Sauter l'anamnèse","Faire une anamnèse, évaluer la zone, identifier les CI","Masser immédiatement","Donner un médicament"],"r":1,"e":"Bilan préalable = sécurité + adaptation : anamnèse, observation, palpation, recherche de CI.","s":3},{"q":"La position du kiné pour masser doit :","o":["Forcer le dos","Être ergonomique : pieds écartés, dos droit, utiliser le poids du corps","Être assis au sol","Sur une jambe"],"r":1,"e":"Ergonomie kiné = prévention TMS : appui solide, dos neutre, utilisation du poids corporel plutôt que la force des bras.","s":3},{"q":"La durée standard d'une séance de massage thérapeutique est généralement de :","o":["3 minutes","20-30 minutes (variable selon zone)","3 heures","2 jours"],"r":1,"e":"Séances typiques : 20-30 min ciblées sur une région. Plus long = risque de fatigue tissulaire et du kiné.","s":3},{"q":"Le rythme du massage doit être :","o":["Aléatoire","Régulier et adapté à l'objectif (lent = relaxation, plus rapide = stimulation)","Toujours très rapide","Toujours saccadé"],"r":1,"e":"Lent et continu → relaxation, parasympathique. Rythmé/dynamique → stimulation, ↑ vigilance et trophicité.","s":3},{"q":"L'évaluation après séance comprend :","o":["Rien","Demander le ressenti, observer la mobilité, noter la douleur (EVA)","Faire un examen sanguin","Une biopsie"],"r":1,"e":"Réévaluation post-séance = subjectif (ressenti, EVA) + objectif (mobilité, palpation) pour ajuster les séances suivantes.","s":3},{"q":"La thérapie manuelle, bien que liée au contact manuel local, a aussi des effets :","o":["Tissulaires locaux, neurologiques, physiologiques et psychologiques","Uniquement tissulaires","Uniquement locaux","Uniquement mécaniques"],"r":0,"e":"C'est ce qui fonde son modèle physiologique.","s":3},{"q":"Parmi les effets de l'organisation neurologique, le cours cite :","o":["L'action proprioceptive et l'intégration du schéma corporel","La seule antalgie","La seule stimulation sensorielle","Le seul traitement postural"],"r":0,"e":"S'y ajoutent l'orientation sur les lésions nerveuses centrales, les déficits post-lésionnels, la rééducation de la posture et du mouvement et la désensibilisation.","s":3},{"q":"L'organisation psychophysiologique rappelle que :","o":["Les émotions sont associées à des réponses somatiques, comme des modifications du tonus ou de la tolérance à la douleur","Les émotions sont indépendantes du corps","Le toucher n'a pas d'effet émotionnel","La douleur est purement physique"],"r":0,"e":"Dans la plupart des cas cliniques, la stimulation par le toucher réduit ou annule les symptômes.","s":3},{"q":"L'organisation tissulaire concerne :","o":["Peau, muscles, tendons, capsule, ligaments, systèmes vasculaire et lymphatique et tous les tissus des différentes couches","La seule peau","Les seuls muscles","Les seules articulations"],"r":0,"e":"Les forces mécaniques y modifient propriétés physiques, structure et dynamique des fluides.","s":3},{"q":"Les transformations locales de la dynamique des fluides concernent :","o":["Le sang, la lymphe, les fluides extracellulaires et synoviaux","Le seul sang","La seule lymphe","Le seul liquide synovial"],"r":0,"e":"Elles participent aux processus de réparation tissulaire post-lésionnelle.","s":3},{"q":"La flexibilité se définit comme :","o":["Un travail global visant à manipuler la longueur des fibres musculaires, incluant diverses techniques","Une technique spécifique à un muscle","Une caractéristique des tissus mous","Une propriété du collagène"],"r":0,"e":"L'étirement est une technique spécifique, avec timing précis, qui travaille la flexibilité.","s":3},{"q":"La viscoplasticité :","o":["Est une caractéristique de tous les tissus mous, dépendant de la synthèse protéique et du nombre de liaisons transversales","Concerne les seuls muscles","Est une technique","Est propre au tendon"],"r":0,"e":"Elle définit la densité tissulaire.","s":3},{"q":"Parmi les types de contraintes biomécaniques, le cours cite :","o":["L'absence de charge, la tension longitudinale, la compression, la tension latérale, la contrainte bidirectionnelle simultanée, la torsion et la combinaison compression-torsion","La seule compression","La seule traction","La seule torsion"],"r":0,"e":"Chacune produit des modifications tissulaires spécifiques.","s":3},{"q":"L'objectif clinique des techniques manuelles est :","o":["De rétablir les propriétés structurelles et fonctionnelles des tissus","De soulager la douleur uniquement","De détendre le patient","D'augmenter la force"],"r":0,"e":"Les techniques se classent selon les modifications qu'elles provoquent.","s":3},{"q":"L'étirement, comme modification produite par les techniques, exerce une force :","o":["Dans le sens longitudinal","Dans le sens transversal","En compression","En rotation"],"r":0,"e":"Il est utilisé pour étirer des tissus raccourcis.","s":3},{"q":"Le remodelage des forces de tension lors de l'étirement entraîne :","o":["Une agrégation du collagène dans le sens de ces forces, rendant le tissu plus étroit et plus dense","Une dispersion du collagène","Un relâchement du tissu","Un épaississement désorganisé"],"r":0,"e":"L'étirement a par ailleurs peu d'influence sur le flux des fluides.","s":3},{"q":"La compression, parmi les modifications produites :","o":["Raccourchit ou rapproche les fibres, augmente la pression interne tissulaire et facilite la circulation des fluides","Allonge les fibres","Diminue la pression interne","Bloque la circulation"],"r":0,"e":"C'est ce qui la distingue de l'étirement, peu actif sur les fluides.","s":3},{"q":"La rotation est décrite comme produisant :","o":["Un effet mécanique complexe","Un effet purement longitudinal","Un effet purement compressif","Aucun effet"],"r":0,"e":"Elle figure parmi les cinq grandes modifications produites par les techniques manuelles.","s":3},{"q":"Les forces mécaniques modifient les propriétés physiques et mécaniques suivantes :","o":["Flexibilité, viscoplasticité et force","Température et pH","Densité osseuse","Conduction nerveuse"],"r":0,"e":"Elles entraînent aussi des modifications structurelles et physiologiques.","s":3},{"q":"Les mains du kinésithérapeute, bien que placées sur une zone précise, influencent des processus neurologiques :","o":["Locaux, à distance ou globaux","Uniquement locaux","Uniquement globaux","Uniquement réflexes"],"r":0,"e":"C'est le fondement de l'organisation neurologique de la thérapie manuelle.","s":3},{"q":"Parmi les applications neurologiques de la thérapie manuelle, le cours cite :","o":["Le traitement de la douleur et la stimulation ou désensibilisation sensorielle","La seule antalgie","La seule stimulation","La seule rééducation motrice"],"r":0,"e":"Elle fournit aussi des informations sensorielles par le toucher.","s":3},{"q":"L'étirement se distingue de la flexibilité par :","o":["Son caractère spécifique, ciblant un muscle ou un groupe, avec un timing précis","Son caractère global","Son absence de technique","Sa durée"],"r":0,"e":"L'étirement est donc un outil au service de la flexibilité.","s":3},{"q":"La densité tissulaire est définie par :","o":["La synthèse protéique et le nombre de liaisons transversales","La seule teneur en eau","La seule vascularisation","L'épaisseur"],"r":0,"e":"Ces deux paramètres déterminent la viscoplasticité, caractéristique de tous les tissus mous.","s":3},{"q":"L'état neutre, parmi les contraintes biomécaniques, correspond à :","o":["L'absence de charge","Une compression légère","Une tension minimale","Une torsion nulle avec compression"],"r":0,"e":"C'est le point de départ à partir duquel s'appliquent les autres contraintes.","s":3},{"q":"Le toucher, dans l'organisation psychophysiologique, provoque :","o":["Des stimuli puissants","Des effets négligeables","Des effets uniquement locaux","Des effets uniquement mécaniques"],"r":0,"e":"C'est ce qui explique la réduction ou l'annulation des symptômes dans la plupart des cas cliniques.","s":3},{"q":"Le massage est utilisé depuis :","o":["Le XIXe siècle","2698 av. J.-C. en Chine","1900","1950"],"r":1,"e":"Mention écrite la plus ancienne en Chine en 2698 av. J.-C.","s":4},{"q":"Pourquoi les termes effleurage, pétrissage, tapotement sont-ils français ?","o":["Inventés en France","Réintroduits en Europe au XIXe par les missionnaires français revenant de Chine","Erreur de traduction","Hasard"],"r":1,"e":"Beck (1999) : réintroduits en Europe au XIXe par les missionnaires FRANÇAIS revenus de Chine → terminologie française.","s":4},{"q":"Qui a prouvé scientifiquement les effets du massage dans les années 80-90 ?","o":["Hippocrate","Tiffany Field et son équipe","Penfield","Damásio"],"r":1,"e":"Tiffany Field (années 80-90) = études prouvant les effets du massage.","s":4},{"q":"Les principaux promoteurs européens du massage moderne sont :","o":["Les Français","Les Scandinaves (Danemark, Suède, Norvège...)","Les Italiens","Les Espagnols"],"r":1,"e":"Principaux promoteurs européens = SCANDINAVES.","s":4},{"q":"La direction recommandée du massage est :","o":["Proximal → distal","CENTRIPÈTE : distal → proximal (favorise retour veineux)","Aléatoire","Latérale"],"r":1,"e":"Direction CENTRIPÈTE (distal → proximal) pour favoriser le RETOUR VEINEUX.","s":4},{"q":"La durée d'une mobilisation tissulaire LOCALE thérapeutique est :","o":["1-2 min","5-15 min","30-60 min","2 heures"],"r":1,"e":"Mobilisation locale thérapeutique = 5 à 15 minutes.","s":4},{"q":"La durée d'une mobilisation de RELAXATION est :","o":["1 min","5 min","30-45/60 minutes","3 heures"],"r":2,"e":"Mobilisation de relaxation = 30 à 45/60 minutes.","s":4},{"q":"La pression à appliquer est :","o":["Maximale","Modérée (selon la littérature)","Nulle","Très faible toujours"],"r":1,"e":"La littérature recommande une PRESSION MODÉRÉE pour produire des effets.","s":4},{"q":"Concernant le kinésithérapeute, il doit :","o":["Avoir les ongles longs","Avoir les mains soignées, ongles propres et coupés, hygiène","Porter des bagues","Avoir les mains froides"],"r":1,"e":"Mains soignées, ongles PROPRES et COUPÉS, hygiène irréprochable.","s":4},{"q":"Les 3 types d'effets physiologiques du massage sont :","o":["Mécaniques uniquement","Mécaniques, réflexes/neuraux, psychologiques","Magiques","Physiques uniquement"],"r":1,"e":"3 effets : MÉCANIQUES, RÉFLEXES/NEURAUX, PSYCHOLOGIQUES.","s":4},{"q":"Le massage selon Holey & Cook (1999) est :","o":["Une chirurgie","Une manipulation des tissus mous par un professionnel qualifié dans le cadre d'une intervention holistique","Un sport","Une injection"],"r":1,"e":"Holey & Cook (1999) : manipulation des tissus mous par professionnel qualifié dans cadre holistique.","s":4},{"q":"Le massage peut s'utiliser :","o":["Seul uniquement","En combinaison avec d'autres techniques du plan d'intervention","Jamais","Sans plan"],"r":1,"e":"Andrade & Clifford (2008) : seul OU en association avec d'autres techniques du plan d'intervention.","s":4},{"q":"Quel cadre légal définit l'acte du kinésithérapeute ?","o":["Décret-loi n° 564/99 + Article 6","Loi du sport","Code civil","Aucun"],"r":0,"e":"Décret-loi 564/99 + Article 6 — Acte du kinésithérapeute.","s":4},{"q":"L'acte du kinésithérapeute concerne :","o":["Uniquement les os","Le système locomoteur et la fonctionnalité, dans ses dimensions physique, mentale et sociale","Uniquement la peau","Uniquement le cerveau"],"r":1,"e":"Système locomoteur + fonctionnalité, dimensions physique, mentale, sociale.","s":4},{"q":"Le processus de physiothérapie comprend :","o":["Une seule étape","Examen, diagnostic, pronostic/plan, intervention, évaluation des résultats, conclusion","Aucune étape","La seule prescription"],"r":1,"e":"6 étapes : examen → diagnostic → pronostic/plan → intervention → évaluation résultats → conclusion.","s":4},{"q":"La position du kiné doit être :","o":["Inconfortable","Confortable, avec rythme continu et mains ajustées","Tendue","Variable"],"r":1,"e":"Position CONFORTABLE, technique correcte, rythme CONTINU, mains AJUSTÉES à la surface.","s":4},{"q":"L'huile/crème sert à :","o":["Hydrater seulement","Aider à faire GLISSER les mains, selon objectifs et type de peau","Désinfecter","Refroidir"],"r":1,"e":"Huile/crème = favorise le glissement, choisie selon objectifs et type de peau.","s":4},{"q":"La fréquence d'une mobilisation tissulaire est déterminée par :","o":["Le hasard","Le raisonnement clinique","Le patient seul","Aucun critère"],"r":1,"e":"Fréquence = nombre de répétitions sur une période donnée, déterminée par le RAISONNEMENT CLINIQUE.","s":4},{"q":"Le kinésithérapeute peut intervenir dans :","o":["Aucun domaine","TOUS les domaines de la santé (musculo, neuro, cardio, respi, mental, etc.)","Seulement le sport","Seulement la pédiatrie"],"r":1,"e":"Tous les domaines : musculo-squelettique, neuro, cardio, respi, oncologie, tégumentaire, mental, femmes, bébés, sportifs, etc.","s":4},{"q":"L'acte du kinésithérapeute peut être réalisé :","o":["Uniquement en présentiel","En consultation en personne OU télésanté","Sans patient","Par téléphone uniquement"],"r":1,"e":"En présentiel mais aussi en télésanté.","s":4},{"q":"Le bilan kiné comporte 3 phases principales :","o":["Anamnèse, examen physique, plan de traitement","Diagnostic médical","Prescription","Chirurgie"],"r":0,"e":"3 phases : anamnèse (subjectif) → examen physique (objectif) → bilan-diagnostic kiné et plan d'intervention.","s":4},{"q":"L'anamnèse comprend :","o":["Uniquement la douleur","Antécédents, histoire de la maladie, douleur (EVA), retentissement fonctionnel","Seulement le poids","Aucune information"],"r":1,"e":"Anamnèse complète : ATCD, début/évolution, intensité douloureuse, contexte, retentissement quotidien.","s":4},{"q":"Le consentement éclairé du patient avant un massage est :","o":["Facultatif","Obligatoire (explication + accord)","Verbal uniquement","Réservé aux mineurs"],"r":1,"e":"Le patient doit recevoir une information claire (technique, bénéfices, risques, alternatives) et donner son accord.","s":4},{"q":"Le secret professionnel s'applique :","o":["Seulement avec les collègues","À toutes les informations recueillies sur le patient","Seulement aux mineurs","Aux salaires"],"r":1,"e":"Secret professionnel = obligation légale et déontologique pour TOUTES les informations sur le patient.","s":4},{"q":"L'hygiène avant chaque séance :","o":["N'est pas obligatoire","Lavage des mains, ongles courts, table propre, linge propre","Seulement si demandé","Une fois par jour"],"r":1,"e":"Hygiène = base de la sécurité patient : mains lavées entre chaque patient, ongles courts, matériel propre.","s":4},{"q":"L'huile de massage sert à :","o":["Augmenter la friction","Réduire la friction et faciliter le glissement (effleurage, pétrissage)","Soigner la peau","Aromatiser"],"r":1,"e":"Huile = lubrifiant qui réduit la friction cutanée et permet des manœuvres prolongées sans irritation.","s":4},{"q":"L'objectif principal d'un massage en récupération sportive est :","o":["Augmenter la fatigue","Favoriser la récupération (drainage, ↓ tension, ↓ douleurs)","Augmenter la performance instantanée","Échauffer"],"r":1,"e":"Massage de récup post-effort : drainage des métabolites, ↓ tension musculaire, ↓ DOMS, détente.","s":4},{"q":"Un massage pré-compétition est plutôt :","o":["Profond et long","Court, dynamique, stimulant","Sédatif","Inutile"],"r":1,"e":"Pré-compétition = stimulation : pétrissage rapide, percussions légères → ↑ vigilance, ↑ trophicité, sans fatiguer.","s":4},{"q":"Lors du massage, la communication avec le patient :","o":["Est inutile","Est essentielle pour adapter la pression et le rythme","Doit être permanente","Doit être absente"],"r":1,"e":"Échange régulier sur la pression, la douleur, le ressenti → ajustement de la technique en temps réel.","s":4},{"q":"Documenter la séance permet de :","o":["Rien","Tracer l'évolution, ajuster le plan, garantir la traçabilité","Facturer plus","Faire de la pub"],"r":1,"e":"Compte-rendu = traçabilité légale + suivi de l'évolution + ajustement de la prise en charge sur la durée.","s":4},{"q":"Selon le Décret-loi n° 564/99, le kinésithérapeute se concentre sur :","o":["L'analyse et l'évaluation du mouvement et de la posture, en se basant sur la structure et la fonction du corps","La seule rééducation","Le seul traitement de la douleur","La seule prévention"],"r":0,"e":"Il utilise des modalités éducatives et thérapeutiques spécifiques : mouvement, thérapies manipulatives, moyens physiques et naturels.","s":4},{"q":"L'acte du kinésithérapeute selon l'article 6 s'exerce :","o":["Dans les dimensions physique, mentale et sociale, à tous les âges","Dans la seule dimension physique","Chez l'adulte uniquement","En milieu hospitalier uniquement"],"r":0,"e":"Il porte sur les structures anatomiques et les fonctions physiologiques du système locomoteur.","s":4},{"q":"Parmi les systèmes sur lesquels intervient le kinésithérapeute, le cours cite :","o":["Cardiovasculaire, cognitif, immunitaire, métabolique, musculo-squelettique, neurologique, respiratoire, tégumentaire, urinaire et reproducteur","Le seul musculo-squelettique","Les seuls systèmes locomoteur et respiratoire","Le seul système nerveux"],"r":0,"e":"Son champ dépasse donc largement le système locomoteur.","s":4},{"q":"L'acte du kinésithérapeute se concrétise :","o":["Par le processus de physiothérapie, en consultation présentielle ou en télésanté","En présentiel uniquement","En télésanté uniquement","Par la seule prescription"],"r":0,"e":"Il intervient en kinésiopathologie et pathokinésiologie, prévention, optimisation et promotion du mouvement fonctionnel.","s":4},{"q":"Le diagnostic physiothérapeutique porte sur :","o":["Les altérations, les limitations d'activité et les restrictions de participation","La seule lésion","La seule douleur","Le seul bilan articulaire"],"r":0,"e":"Il suit l'examen et l'évaluation, première étape du processus.","s":4},{"q":"L'intervention du kinésithérapeute comprend :","o":["Éducation, thérapie par le mouvement, thérapie manuelle incluant la manipulation, thérapie physique et ressources technologiques","La seule thérapie manuelle","Le seul exercice","La seule éducation"],"r":0,"e":"Elle constitue la quatrième étape du processus de physiothérapie.","s":4},{"q":"Le pronostic et le plan d'intervention se définissent :","o":["Avec le patient et sa famille, à partir des besoins et objectifs","Par le seul kinésithérapeute","Par le médecin","Par l'établissement"],"r":0,"e":"L'évaluation des résultats suit, avec réévaluation pendant et après l'intervention.","s":4},{"q":"Parmi les domaines d'intervention, le cours cite :","o":["La santé au travail, communautaire, le bien-être et la santé animale","Les seuls domaines cliniques","Le seul musculo-squelettique","La seule rééducation neurologique"],"r":0,"e":"S'y ajoutent les domaines oncologique, tégumentaire, la fin de vie et la santé mentale.","s":4},{"q":"Parmi les populations citées dans les domaines d'intervention figurent :","o":["Les femmes, bébés, enfants, adolescents, personnes âgées et sportifs","Les seuls adultes","Les seuls sportifs","Les seules personnes âgées"],"r":0,"e":"Cette diversité traduit l'étendue du champ professionnel.","s":4},{"q":"Parmi les contextes de pratique, le cours cite :","o":["Les entreprises, institutions sportives et artistiques, centres de recherche et projets communautaires, sociaux et politiques","Les seuls hôpitaux","Les seules cliniques","Le seul exercice libéral"],"r":0,"e":"Établissements de santé, institutions locales, services d'aide et établissements d'enseignement complètent la liste.","s":4},{"q":"La définition de Holey & Cook (1999) situe le massage :","o":["Dans le cadre d'une intervention holistique, par un professionnel qualifié","Comme une technique isolée","Comme un soin de confort","Comme une pratique non thérapeutique"],"r":0,"e":"Kumar, Beaton & Hughes (2013) le définissent comme la manipulation de tissus mous à des fins thérapeutiques.","s":4},{"q":"Le massage s'inscrit dans :","o":["Les thérapies manipulatives, comme modalité sélectionnée à la suite du raisonnement clinique","Les thérapies physiques","Les moyens naturels","L'éducation thérapeutique"],"r":0,"e":"Il est utilisable dans tous les domaines et niveaux d'intervention.","s":4},{"q":"Les niveaux d'intervention où le massage est utilisable sont :","o":["Promotion, prévention, thérapie, habilitation et rééducation","La seule thérapie","La seule prévention","La seule rééducation"],"r":0,"e":"Cette polyvalence découle de son statut de modalité thérapeutique choisie par raisonnement clinique.","s":4},{"q":"La première mention écrite du massage remonte à :","o":["2698 av. J.-C., en Chine","Le XIXᵉ siècle","L'Antiquité grecque","Le Moyen Âge"],"r":0,"e":"Au fil des siècles, il a servi à promouvoir la santé et prévenir les maladies par toucher, frictions et pétrissage.","s":4},{"q":"Les auteurs cités pour l'histoire du massage sont :","o":["Field (1998) et Schneider (1996)","Holey & Cook","Kumar et Beaton","Sackett"],"r":0,"e":"Holey & Cook (1999) et Kumar, Beaton & Hughes (2013) sont cités pour les définitions.","s":4},{"q":"L'examen et l'évaluation, première étape du processus, comprennent :","o":["Observation, entretien, examen manuel, tests, mesures et examens complémentaires","Le seul entretien","Le seul examen manuel","Les seuls tests"],"r":0,"e":"Ils fondent ensuite le diagnostic physiothérapeutique.","s":4},{"q":"Parmi les finalités de l'acte du kinésithérapeute, le cours cite :","o":["Promotion de la santé, éducation, réduction des risques, prévention, maintien, récupération, réadaptation, rééducation et soins palliatifs","La seule rééducation","La seule prévention","Le seul traitement"],"r":0,"e":"Les soins palliatifs figurent explicitement dans ce champ.","s":4},{"q":"La kinésiopathologie et la pathokinésiologie désignent :","o":["Deux cadres d'intervention du kinésithérapeute","Deux pathologies","Deux techniques","Deux diagnostics"],"r":0,"e":"Ils encadrent l'intervention sur le mouvement fonctionnel et la douleur.","s":4},{"q":"Le processus de physiothérapie se conclut par :","o":["La conclusion du processus, après évaluation des résultats et modification éventuelle","L'intervention","Le diagnostic","Le pronostic"],"r":0,"e":"La réévaluation a lieu pendant et après l'intervention.","s":4},{"q":"Les modalités citées dans la définition du kinésithérapeute sont :","o":["Le mouvement, les thérapies manipulatives, les moyens physiques et naturels","Les seuls exercices","Les seuls moyens physiques","Les seules manipulations"],"r":0,"e":"Elles servent à promouvoir la santé, prévenir les maladies et handicaps, et traiter, habiliter ou réhabiliter.","s":4},{"q":"L'effleurage vient du mot français signifiant :","o":["Frapper","Glisser","Pétrir","Tourner"],"r":1,"e":"Effleurer = GLISSER en français. Technique de glissement lent et rythmique.","s":5},{"q":"L'effleurage se réalise généralement :","o":["Au milieu de la séance","Au début et à la fin, ou entre différentes techniques","Jamais","Uniquement seul"],"r":1,"e":"Utilisé au début, à la fin, ou entre différentes techniques de massage/thérapie manuelle.","s":5},{"q":"La pression de l'effleurage est :","o":["Maximale","Légère, sur les tissus superficiels","Profonde","Variable"],"r":1,"e":"Pression LÉGÈRE au niveau des tissus SUPERFICIELS.","s":5},{"q":"Le sens de progression de l'effleurage est :","o":["Proximal → distal","DISTAL → PROXIMAL","Aléatoire","Latéral"],"r":1,"e":"DISTAL → PROXIMAL (sens de la circulation lymphatique et sanguine, retour veineux).","s":5},{"q":"Un objectif thérapeutique de l'effleurage est :","o":["Renforcer le muscle","Favoriser retour veineux/lymphatique et élimination des irritants","Augmenter la douleur","Bloquer le sang"],"r":1,"e":"Effleurage : retour veineux/lymphatique, échanges tissulaires, ↑ apport sanguin, élimination irritants chimiques, relâche les fibres musculaires.","s":5},{"q":"L'effleurage est CONTRE-INDIQUÉ en cas de :","o":["Peau saine","Insuffisance cardiaque congestive avec œdème des MI","Membre détendu","Aucune raison"],"r":1,"e":"CI : solutions de continuité, varices, œdèmes importants, hyperesthésie, zones poilues, ICC avec œdème MI.","s":5},{"q":"Une indication de l'effleurage est :","o":["Fracture aiguë","Œdème veineux chronique","Plaie ouverte","Hémorragie active"],"r":1,"e":"Indication : troubles circulatoires comme l'œdème veineux chronique.","s":5},{"q":"Pendant l'effleurage, la pression :","o":["Augmente progressivement","Reste UNIFORME tout au long du mouvement","Diminue","Varie selon humeur"],"r":1,"e":"Pression MAINTENUE UNIFORME pendant tout le mouvement.","s":5},{"q":"Le rythme de l'effleurage est :","o":["Rapide et saccadé","Lent et rythmé","Aléatoire","Très lent uniquement"],"r":1,"e":"Mouvement LENT ET RYTHMÉ pour favoriser le retour des fluides.","s":5},{"q":"Quelle modalité d'effleurage utilise un mouvement circulaire ?","o":["Deux mains","Montre / Horloge","Pouces","Phalanges"],"r":1,"e":"Modalité MONTRE/HORLOGE = mouvements circulaires.","s":5},{"q":"L'effleurage 'main après main' signifie :","o":["Les deux mains ensemble","Les mains alternent en continu","Une seule main","Pas de mouvement"],"r":1,"e":"Main après main = alternance continue des mains.","s":5},{"q":"L'effleurage agit sur :","o":["Uniquement la peau","Peau, tissus sous-cutanés, muscles, aponévroses, vaisseaux, nerfs","Uniquement les os","Uniquement les nerfs"],"r":1,"e":"Agit sur tous les tissus : peau, sous-cutanés, muscles, aponévroses, vaisseaux, nerfs.","s":5},{"q":"Au membre supérieur, une zone particulière pour l'effleurage est :","o":["Le pubis","Le deltoïde et la région thénar","La rotule","Le tarse"],"r":1,"e":"Particularités du MS : deltoïde, région thénar.","s":5},{"q":"Au membre inférieur, une zone particulière pour l'effleurage est :","o":["L'omoplate","Le tenseur du fascia lata, les jumeaux, le fascia plantaire","La clavicule","Le crâne"],"r":1,"e":"MI : tenseur du fascia lata, jumeaux, fascia plantaire.","s":5},{"q":"Le mouvement de l'effleurage est :","o":["Discontinu","CONTINU, les mains reviennent toujours au point de départ","Saccadé","Aléatoire"],"r":1,"e":"Mouvement CONTINU, les mains reviennent toujours au point de départ.","s":5},{"q":"L'effleurage peut être combiné à une autre stratégie pour gagner en souplesse :","o":["Repos total","Résistance excentrique (Forman et al., 2014)","Étirement passif uniquement","Aucune"],"r":1,"e":"Massage profond + résistance EXCENTRIQUE = gain de souplesse plus important (Forman et al., 2014).","s":5},{"q":"Sur quelle phase d'une lésion l'effleurage est-il indiqué ?","o":["Aiguë avec inflammation maximale","Subaiguë (favorise absorption de l'exsudat)","Chronique uniquement","Toutes"],"r":1,"e":"Lésions tissus mous en phase SUBAIGUË : favorise l'absorption de l'exsudat inflammatoire.","s":5},{"q":"L'effleurage peut servir de :","o":["Transition entre techniques","Préparer et faire la continuité entre techniques","Les deux","Aucune"],"r":2,"e":"Effleurage = préparer + faire la continuité entre les différentes techniques.","s":5},{"q":"Les zones d'HYPERESTHÉSIE sont :","o":["Indiquées","Contre-indiquées","Recommandées","Sans effet"],"r":1,"e":"Zones d'hyperesthésie = CONTRE-INDIQUÉES (douleur amplifiée).","s":5},{"q":"Les zones très POILUES sont :","o":["Idéales","Contre-indiquées (irritation)","Sans contre-indication","Recommandées"],"r":1,"e":"Zones trop poilues = contre-indication relative (irritation du frottement).","s":5},{"q":"L'effleurage est habituellement la 1ʳᵉ technique d'une séance car :","o":["Il dure le plus longtemps","Il prépare la peau, évalue les tissus et installe le contact","Il est très intense","Il échauffe les os"],"r":1,"e":"Effleurage = mise en contact, prise de température et de tonus, préparation pour techniques plus profondes.","s":5},{"q":"L'effleurage profond favorise principalement :","o":["L'inflammation","Le retour veineux et lymphatique (sens distal → proximal)","La contraction musculaire","La sudation excessive"],"r":1,"e":"Pression profonde et lente du distal vers le proximal = drainage veineux/lymphatique.","s":5},{"q":"La main du kiné en effleurage doit :","o":["Être rigide","Épouser la forme de la zone, contact total","Glisser seulement sur les bouts des doigts","Décoller à chaque geste"],"r":1,"e":"Main moulée à la zone = contact maximal, distribution homogène de la pression.","s":5},{"q":"L'effleurage superficiel a un effet :","o":["Sympathique (stimulant)","Parasympathique (apaisant) et désensibilisant","Ostéogénique","Glycogénolytique"],"r":1,"e":"Manœuvres superficielles lentes → activation parasympathique, ↓ vigilance douloureuse, relaxation.","s":5},{"q":"Une contre-indication de l'effleurage est :","o":["Stress","Plaie ouverte, infection cutanée, brûlure récente","Fatigue","Insomnie"],"r":1,"e":"Pas d'effleurage sur lésion cutanée active : risque infectieux et douloureux.","s":5},{"q":"L'effleurage palmaire utilise :","o":["Le bout des doigts","La paume et le talon de la main","Le coude","Les ongles"],"r":1,"e":"Effleurage palmaire = paume complète + talon, ↑ surface de contact, pression douce et large.","s":5},{"q":"L'effleurage en \"peignant\" (digital) sert à :","o":["Travail global","Travail fin sur petites zones (visage, mains, espaces inter-osseux)","Échauffer","Drainer le rachis"],"r":1,"e":"Effleurage digital = précis, adapté aux petites zones (extrémités, espaces inter-tendineux).","s":5},{"q":"Le rythme idéal d'un effleurage de drainage est :","o":["Très rapide et saccadé","Lent, régulier, continu","Aléatoire","Sans pression"],"r":1,"e":"Drainage = lent, continu et régulier pour suivre le rythme veineux/lymphatique.","s":5},{"q":"Combien de répétitions par segment en moyenne ?","o":["1","5-10 répétitions","100","Aucune"],"r":1,"e":"≈ 5-10 passages par segment = suffisant pour induire l'effet recherché sans surcharge tissulaire.","s":5},{"q":"Après un effleurage, on enchaîne typiquement avec :","o":["Du tapotement direct","Un pétrissage ou des techniques plus profondes","Une percussion violente","Rien"],"r":1,"e":"Progression classique : effleurage (prépare) → pétrissage (mobilise) → friction ciblée → re-effleurage (récupération).","s":5},{"q":"L'effleurage s'utilise :","o":["Au début et à la fin d'une intervention, ou entre différentes techniques","Uniquement au début","Uniquement à la fin","Au milieu de la séance"],"r":0,"e":"Du français « effleurer », c'est-à-dire glisser.","s":5},{"q":"Parmi les objectifs thérapeutiques de l'effleurage figure :","o":["Rétablir la mobilité des interfaces tissulaires","Augmenter la force","Briser les adhérences","Stimuler le fuseau musculaire"],"r":0,"e":"S'y ajoutent les échanges tissulaires, le retour veineux et lymphatique, l'apport sanguin, l'élimination des irritants et le relâchement des fibres.","s":5},{"q":"L'effleurage est indiqué dans les lésions des tissus mous :","o":["En phase subaiguë, pour favoriser l'absorption de l'exsudat inflammatoire","En phase aiguë","En phase chronique seulement","À toutes les phases"],"r":0,"e":"Il sert aussi à préparer le patient et le kiné aux autres techniques et à assurer la continuité entre elles.","s":5},{"q":"Parmi les contre-indications de l'effleurage figure :","o":["L'insuffisance cardiaque congestive ou une affection cardiaque avec œdème des membres inférieurs","La fatigue","La douleur musculaire","Le stress"],"r":0,"e":"S'y ajoutent les plaies, les régions variqueuses, les œdèmes importants, l'hyperesthésie et les zones trop poilues.","s":5},{"q":"Les régions variqueuses contre-indiquent l'effleurage en raison :","o":["Du risque de destruction des parois veineuses","D'une douleur","D'un risque infectieux","D'une hyperesthésie"],"r":0,"e":"C'est l'une des six contre-indications citées.","s":5},{"q":"L'exécution de l'effleurage commence :","o":["Dans la zone distale à traiter, en allant vers le proximal","En proximal","Au centre","Indifféremment"],"r":0,"e":"Ce sens suit celui de la circulation lymphatique et sanguine.","s":5},{"q":"La pression durant l'effleurage doit être :","o":["Maintenue uniforme tout au long du mouvement","Croissante","Décroissante","Variable"],"r":0,"e":"Le mouvement est lent et rythmé, pour favoriser le retour des fluides.","s":5},{"q":"Le caractère continu de l'effleurage implique que :","o":["Les mains accompagnent le mouvement en revenant toujours au point de départ","Les mains se détachent","Le mouvement s'interrompt","Les mains changent de zone"],"r":0,"e":"Elles restent par ailleurs ajustées à la surface anatomique.","s":5},{"q":"La modalité « montre » ou « horloge » de l'effleurage correspond à :","o":["Des mouvements circulaires","Une alternance des mains","L'usage des pouces","L'usage du dos des doigts"],"r":0,"e":"Les cinq modalités sont deux mains, main après main, pouces, face dorsale des phalanges et horloge.","s":5},{"q":"La modalité aux pouces s'emploie :","o":["Sur les zones petites ou précises","Sur les grandes surfaces","Sur l'abdomen","Pour l'alternance"],"r":0,"e":"La modalité « main après main » assure, elle, une alternance continue.","s":5},{"q":"Au membre inférieur, les régions particulières de l'effleurage sont :","o":["Le tenseur du fascia lata, les jumeaux et le fascia plantaire","Le deltoïde et la région thénar","Le quadriceps","Les ischio-jambiers"],"r":0,"e":"Au membre supérieur, ce sont les deltoïdes et la région thénar.","s":5},{"q":"Selon Forman et al. (2014), le massage profond combiné à une résistance excentrique :","o":["Améliore les résultats par rapport à son usage isolé","N'a aucun effet supplémentaire","Est contre-indiqué","Remplace l'étirement"],"r":0,"e":"C'est la technique avancée citée en complément de l'effleurage.","s":5},{"q":"Le pétrissage vient du mot français signifiant :","o":["Glisser","Pétrir","Frapper","Tourner"],"r":1,"e":"Du français PÉTRIR = compression + relâchement des tissus.","s":6},{"q":"Le pétrissage est caractérisé par :","o":["Glissement léger","Compression suivie d'un relâchement","Sans pression","Vibration uniquement"],"r":1,"e":"COMPRESSION appliquée sur les tissus suivie d'un RELÂCHEMENT.","s":6},{"q":"Le pétrissage s'applique surtout sur :","o":["Os uniquement","Tissus superficiels, musculaires profonds et ligaments","Cartilage","Cheveux"],"r":1,"e":"S'applique aux tissus superficiels, tissus musculaires profonds et ligaments.","s":6},{"q":"Une contre-indication au pétrissage :","o":["Muscle sain","Thrombophlébite","Aucune","Repos"],"r":1,"e":"CI : rupture musculaire aiguë, inflammation aiguë, THROMBOPHLÉBITE, néoplasies, infections bactériennes, modifs du tonus.","s":6},{"q":"Le ROULEMENT s'effectue surtout sur :","o":["Gros muscles uniquement","Petits muscles ou tissus superficiels (doigts, pouces et index)","Tissu osseux","Aucun tissu"],"r":1,"e":"Roulement : petits muscles / tissus superficiels avec doigts (toute la main pour gros muscles).","s":6},{"q":"Le KNEADING (pétrissage classique) :","o":["Avec glissement","Sans glissement, étirement+compression, pli dans la peau","Sans contact","Vibrations seulement"],"r":1,"e":"Kneading = SANS glissement, étirement + compression des structures profondes, provoque un PLI dans la peau.","s":6},{"q":"Le sens du kneading est :","o":["Distal → proximal","PROXIMAL → DISTAL","Latéral","Aucune direction"],"r":1,"e":"Kneading commence dans la région PROXIMALE et descend vers le distal.","s":6},{"q":"Le WRINGING (essorage) se caractérise par :","o":["Mouvements vibratoires","Mouvements en forme de 8, rouleau de tissu entre les doigts","Compression seule","Glissement"],"r":1,"e":"Wringing : compression légère, ROULEAU de tissu/muscle entre les doigts, mouvements en forme de 8.","s":6},{"q":"Le SHAKING (vibration) se réalise avec :","o":["Muscle en étirement maximal","Muscle en RACCOURCISSEMENT","Muscle relâché complètement","Os"],"r":1,"e":"Shaking : muscle positionné en RACCOURCISSEMENT, mouvements vibratoires.","s":6},{"q":"Les points de pression (trigger) sont causés par :","o":["Hasard","Un désordre au niveau du fascia","Une fracture","Un nerf coupé"],"r":1,"e":"Trigger points : désordre du FASCIA, provoque raideur + sensibilité + douleur irradiée.","s":6},{"q":"La pression sur un point trigger doit être :","o":["Ferme pendant quelques secondes","Légère et brève","Forte et continue","Inutile"],"r":0,"e":"Pression FERME pendant quelques secondes, avec doigts ou paumes.","s":6},{"q":"Les points trigger peuvent provoquer :","o":["Aucune douleur","Raideur, sensibilité, douleur IRRADIÉE","Sourire","Force"],"r":1,"e":"Trigger : raideur musculaire + sensibilité + DOULEUR IRRADIÉE.","s":6},{"q":"Le pétrissage peut mobiliser :","o":["Aucune contracture","Les contractures musculaires, la peau et les tissus sous-cutanés","Les os","Uniquement le sang"],"r":1,"e":"Objectifs incluent la mobilisation des contractures musculaires, peau et tissus sous-cutanés.","s":6},{"q":"Le pétrissage favorise :","o":["Le retour veineux et lymphatique","La douleur","La paralysie","Rien"],"r":0,"e":"Favorise échanges tissulaires + retour veineux/lymphatique + élimination des irritants chimiques.","s":6},{"q":"Le pistolet de massage :","o":["A des méthodes bien définies","N'a pas de méthodes d'application définies, possibles conflits d'intérêts","Est interdit","Est universel"],"r":1,"e":"Pas de méthodes d'application définies. Possibles conflits d'intérêts dans la littérature.","s":6},{"q":"Le pétrissage peut augmenter :","o":["Rien","La résistance du tissu conjonctif et la longueur du tissu fibreux","La douleur permanente","La rigidité maximale"],"r":1,"e":"Augmente la RÉSISTANCE du tissu conjonctif et la LONGUEUR/élongation du tissu fibreux.","s":6},{"q":"Une inflammation ARTICULAIRE aiguë est :","o":["Indication","Contre-indication","Sans rapport","Indication forte"],"r":1,"e":"Inflammation articulaire aiguë = CONTRE-INDICATION au pétrissage.","s":6},{"q":"Le wringing peut se faire avec :","o":["Uniquement pouces","Pouces et paume des phalanges, ou toute la main pour gros muscles","Coude","Pieds"],"r":1,"e":"Wringing : pouces + paume des phalanges (toute la main pour gros muscles).","s":6},{"q":"Le shaking peut être réalisé avec :","o":["Une seule main strictement","1 main, 2 mains ou mains superposées selon zone","Doigts seuls","Pieds"],"r":1,"e":"Selon zone et objectifs : une main, deux mains, ou mains superposées.","s":6},{"q":"Les néoplasies sont :","o":["Indication","Contre-indication au pétrissage","Sans effet","Indication relative"],"r":1,"e":"Maladies néoplasiques = CONTRE-INDICATION au pétrissage (risque de propagation).","s":6},{"q":"Le pétrissage agit principalement sur :","o":["Les os","La peau, le tissu sous-cutané et les muscles","Les ligaments","Les nerfs centraux"],"r":1,"e":"Pétrissage = saisir, soulever, presser, mobiliser → cible peau, sous-cutané et masse musculaire.","s":6},{"q":"Le pétrissage roulement (rolling) consiste à :","o":["Frapper la peau","Saisir et faire rouler les tissus entre pouces et doigts","Étirer la peau au max","Aspirer"],"r":1,"e":"Rolling = rouler le pli cutané entre pouces (en arrière) et doigts (en avant), avancer progressivement.","s":6},{"q":"Le kneading consiste à :","o":["Petter la peau","Pétrir comme une pâte avec les deux mains alternativement","Frapper","Étirer un tendon"],"r":1,"e":"Kneading = pétrissage profond bi-manuel alterné, mobilise les masses musculaires importantes.","s":6},{"q":"Le wringing (essorage) consiste à :","o":["Frotter la peau","Essorer les tissus en torsion opposée des mains","Effleurer","Tapoter"],"r":1,"e":"Wringing = deux mains autour d'un segment, mouvement de torsion alternée comme pour essorer un linge.","s":6},{"q":"Le shaking (secouage) provoque :","o":["Une contraction réflexe","Une décontraction musculaire et un drainage","Une fracture","Aucun effet"],"r":1,"e":"Shaking = secousses rapides et fines → décontraction réflexe + facilite le drainage.","s":6},{"q":"Un point trigger se traite typiquement par :","o":["Mouvement bref","Compression ischémique soutenue (30-90 s) sur le point douloureux","Massage rapide","Étirement seul"],"r":1,"e":"Trigger point = pression maintenue jusqu'à atténuation de la douleur référée (compression ischémique).","s":6},{"q":"Une contre-indication du pétrissage profond est :","o":["Tension musculaire","Hématome récent / muscle déchiré / inflammation aiguë","Stress","Migraine"],"r":1,"e":"CI = pas de pétrissage profond sur lésion tissulaire fraîche (risque d'aggravation, saignement).","s":6},{"q":"Sur le plan circulatoire local, le pétrissage favorise :","o":["Le sommeil seul","La vasodilatation, l'oxygénation locale et l'élimination des déchets métaboliques","La paralysie","La fièvre"],"r":1,"e":"Effets : ↑ circulation locale, ↑ apport O₂/nutriments, ↑ élimination métabolites (lactate, etc.).","s":6},{"q":"Le rythme du pétrissage est typiquement :","o":["Très lent","Modéré à soutenu, régulier","Très rapide","Saccadé"],"r":1,"e":"Rythme soutenu et régulier permet d'entretenir l'effet mécanique et hémodynamique sans crisper le patient.","s":6},{"q":"Avant un pétrissage profond, il faut :","o":["Rien","Préparer les tissus avec un effleurage initial","Tapoter d'abord","Frictionner d'abord"],"r":1,"e":"Progression : effleurage (prépare, échauffe) → pétrissage (mobilise) → re-effleurage (récupération).","s":6},{"q":"Le petrissage s'applique généralement sur :","o":["Les tissus superficiels, les tissus musculaires profonds et les ligaments","La seule peau","Les seuls tendons","Les seules articulations"],"r":0,"e":"Du français « pétrir », il associe une pression à différents mouvements, avec compression suivie de relâchement.","s":6},{"q":"Parmi les objectifs du petrissage figure :","o":["Augmenter la résistance du tissu conjonctif","Stimuler le fuseau musculaire","Briser les cross-links","Réduire la température"],"r":0,"e":"S'y ajoutent la mobilité et la longueur du tissu fibreux, la mobilité sous-cutanée et la mobilisation des contractures.","s":6},{"q":"Le petrissage vise également :","o":["À faciliter la circulation profonde et superficielle","À immobiliser","À refroidir","À anesthésier"],"r":0,"e":"Il favorise aussi les échanges tissulaires, le retour veineux et lymphatique et l'élimination des irritants chimiques.","s":6},{"q":"Parmi les contre-indications du petrissage figurent :","o":["Les modifications du tonus musculaire et les maladies néoplasiques","La fatigue musculaire","La contracture","La douleur chronique"],"r":0,"e":"Rupture musculaire aiguë, inflammation articulaire aiguë, thrombophlébites et infections bactériennes complètent la liste.","s":6},{"q":"Le roulement s'applique essentiellement :","o":["Sur les petits muscles ou les tissus superficiels","Sur les gros muscles","Sur les ligaments","Sur les tendons"],"r":0,"e":"Il se pratique avec les doigts, ou toute la main pour les gros muscles, les pouces et index des deux mains rapprochant et roulant les structures.","s":6},{"q":"Le kneading commence :","o":["Dans la région proximale, avec un sens proximal vers distal","En distal","Au centre","Indifféremment"],"r":0,"e":"Il se fait sans glissement, par étirement et compression des structures profondes, et provoque un pli dans la peau.","s":6},{"q":"Le wringing se caractérise par :","o":["Une légère compression formant un rouleau de tissu entre les doigts, avec des mouvements en forme de 8","Une absence de compression","Un glissement","Des vibrations"],"r":0,"e":"Il s'applique sur la peau, les tissus sous-cutanés et les muscles, avec les pouces et la paume des phalanges.","s":6},{"q":"Lors du shaking, le muscle doit être positionné :","o":["En raccourcissement","En étirement","En position neutre","En contraction"],"r":0,"e":"Les mouvements vibratoires sont émis par la main du kiné, avec une, deux mains ou les mains superposées.","s":6},{"q":"Les trigger points sont causés par :","o":["Un désordre du fascia","Une lésion tendineuse","Une inflammation articulaire","Une compression nerveuse"],"r":0,"e":"Ils peuvent provoquer raideur musculaire, sensibilité et douleur irradiée.","s":6},{"q":"La pression sur un trigger point s'applique :","o":["Avec les doigts ou les paumes, fermement pendant quelques secondes","Avec un instrument","Par percussion","De façon prolongée sur plusieurs minutes"],"r":0,"e":"Cette technique complète les quatre modalités du petrissage.","s":6},{"q":"Le kneading se pratique :","o":["Avec une ou deux mains, selon la taille de la zone","Avec les pouces uniquement","Avec les poings","Avec l'avant-bras"],"r":0,"e":"Son absence de glissement le distingue nettement de l'effleurage.","s":6},{"q":"Le petrissage se caractérise fondamentalement par :","o":["Une compression suivie d'un relâchement","Un glissement continu","Une percussion","Une traction"],"r":0,"e":"C'est ce qui le distingue de l'effleurage, du tapotement et de la friction.","s":6},{"q":"Le tapotement vient du mot français signifiant :","o":["Glisser","Frapper","Pétrir","Tourner"],"r":1,"e":"TAPOTER = frapper. Technique de frappes rapides répétées.","s":7},{"q":"Le tapotement nécessite :","o":["Mouvements lents","Une répétition RAPIDE des mouvements","Aucun mouvement","Pression continue"],"r":1,"e":"Tapotement = répétition RAPIDE des mouvements.","s":7},{"q":"Le mécanisme du tapotement (mains en coupe) :","o":["Pression directe","L'air est comprimé, créant une onde de vibration qui pénètre les tissus","Compression musculaire","Aucun"],"r":1,"e":"L'air est comprimé entre la main et la peau → onde de vibration pénétrant les tissus.","s":7},{"q":"Un objectif du tapotement :","o":["Endormir","Stimulation tissulaire et activation du fuseau musculaire","Augmenter la fatigue","Bloquer la circulation"],"r":1,"e":"Objectifs : stimulation tissulaire, activation du fuseau musculaire, ↑ circulation locale, relaxation, réduction de la fatigue.","s":7},{"q":"Une contre-indication au tapotement :","o":["Muscle sain","Élévation de la température (fièvre)","Repos","Détente"],"r":1,"e":"CI : fièvre, altérations cutanées, thrombose/phlébite, tissus inflammatoires, fractures, protubérances osseuses.","s":7},{"q":"Concernant les fractures, le tapotement est :","o":["Indiqué","Contre-indiqué (et même les suspicions)","Sans effet","Recommandé"],"r":1,"e":"Fractures OU suspicions de fracture = CI absolue au tapotement.","s":7},{"q":"Le tapotement sur les PROTUBÉRANCES OSSEUSES est :","o":["Indiqué","Contre-indiqué","Sans risque","Recommandé"],"r":1,"e":"Protubérances osseuses = CONTRE-INDICATION (risque traumatique).","s":7},{"q":"Une modalité de tapotement :","o":["Mains en coupe","Glissement","Pression statique","Étirement"],"r":0,"e":"3 modalités : mains en coupe, bord cubital (doigts joints/écartés), bouts des doigts.","s":7},{"q":"Avec les mains en coupe, les bras sont :","o":["Tendus","En abduction, coudes fléchis","Le long du corps","Loin du patient"],"r":1,"e":"Mains en coupe : COUDES FLÉCHIS, bras en abduction.","s":7},{"q":"Le tapotement avec bord cubital se fait avec :","o":["Pouces uniquement","Bord cubital de la main, doigts joints OU écartés","Coude","Le poing fermé"],"r":1,"e":"Bord CUBITAL (côté petit doigt) de la main, doigts joints ou écartés.","s":7},{"q":"En position de tapotement bord cubital, le poignet est :","o":["En flexion","En EXTENSION","Verrouillé","Indifférent"],"r":1,"e":"Poignet en EXTENSION, doigts en flexion, MS en abduction, coudes fléchis.","s":7},{"q":"Le tapotement peut activer :","o":["Aucun récepteur","Le fuseau musculaire (mécaniquement)","La douleur","Le sommeil"],"r":1,"e":"ACTIVATION MÉCANIQUE du fuseau musculaire (récepteur de la longueur).","s":7},{"q":"Sur des tissus inflammatoires, le tapotement est :","o":["Recommandé","Contre-indiqué","Sans effet","Optionnel"],"r":1,"e":"Tissus inflammatoires = CI (risque d'aggraver l'inflammation).","s":7},{"q":"Le tapotement favorise paradoxalement :","o":["La douleur","La relaxation musculaire (et la réduction de la fatigue)","Le coma","La fatigue"],"r":1,"e":"Bien que stimulant, le tapotement favorise la RELAXATION musculaire et réduit la perception de la fatigue.","s":7},{"q":"Les mouvements du tapotement doivent être :","o":["Coordonnés avec le mouvement du poignet","Aléatoires","Sans coordination","Très lents"],"r":0,"e":"Mouvements RAPIDES et bien COORDONNÉS avec le mouvement du poignet.","s":7},{"q":"En cas de thrombose, le tapotement est :","o":["Indiqué","Contre-indiqué (risque embolique)","Sans effet","Recommandé"],"r":1,"e":"Thrombose et phlébite = CI absolues (risque embolique).","s":7},{"q":"Le tapotement augmente :","o":["La circulation locale","La douleur","La fatigue","Rien"],"r":0,"e":"Augmentation de la CIRCULATION LOCALE par stimulation tissulaire.","s":7},{"q":"Le tapotement bouts des doigts s'utilise pour :","o":["Grandes zones","Zones plus précises, plus délicates","Régions osseuses","Aucune zone"],"r":1,"e":"Bouts des doigts = zones plus précises et délicates.","s":7},{"q":"Le tapotement peut être :","o":["Uniquement 2 mains","À 1 ou 2 mains, avec différentes techniques, rythmes et durées","Sans variation","Toujours uniforme"],"r":1,"e":"À 1 ou 2 mains, avec différentes techniques, rythmes et durées.","s":7},{"q":"Sur la peau lésée (solutions de continuité), le tapotement est :","o":["Indiqué","Contre-indiqué","Sans effet","Recommandé"],"r":1,"e":"Altérations de la continuité ou de l'état de la peau = CONTRE-INDICATION.","s":7},{"q":"Le tapotement (percussion) a un effet :","o":["Sédatif","Stimulant (↑ tonus, ↑ vigilance)","Antalgique pur","Néant"],"r":1,"e":"Tapotement = percussions rythmées → réveil du fuseau musculaire, ↑ tonus, stimulation circulatoire.","s":7},{"q":"Le tapotement en mains creuses (cupping) est utilisé :","o":["Sur l'abdomen","Sur le thorax (kiné respiratoire) pour décoller le mucus","Sur les yeux","Sur le crâne"],"r":1,"e":"Cupping (clapping) en kiné respiratoire : mains creuses sur thorax pour mobiliser les sécrétions bronchiques.","s":7},{"q":"Le hacking utilise :","o":["La paume","Le bord cubital des mains, mains relâchées","Le pouce","Les ongles"],"r":1,"e":"Hacking = percussion avec le bord cubital, poignets souples, mains relâchées, rythme rapide alterné.","s":7},{"q":"Une contre-indication du tapotement est :","o":["Tension","Région du rein, fractures, ostéoporose sévère, tumeurs","Hypertension légère","Crampe"],"r":1,"e":"CI : régions fragiles (reins, sein, os ostéoporotique), trauma récent, néoplasie locale.","s":7},{"q":"Le tapotement augmente la trophicité par :","o":["Vasoconstriction","Vasodilatation locale réflexe + activation neuromusculaire","Refroidissement","Saignement"],"r":1,"e":"Percussions rythmées → vasodilatation cutanée et musculaire + stimulation des récepteurs musculaires.","s":7},{"q":"Le rythme typique du tapotement est :","o":["1 frappe/min","Rapide, régulier (≈ 2-4 Hz)","Irrégulier","Continu sans pause"],"r":1,"e":"Tapotement = fréquence rapide (≈ 2-4 Hz) et régulière, mains alternantes.","s":7},{"q":"La force du tapotement provient :","o":["Du dos","Du relâchement du poignet et du rebond","Du coude bloqué","Des doigts crispés"],"r":1,"e":"Force essentielle = poignet souple + utilisation du rebond, pas de force musculaire des bras.","s":7},{"q":"En sport, le tapotement est utile :","o":["Comme massage de récupération profond","En pré-effort pour stimuler","Comme étirement","Pour endormir"],"r":1,"e":"Pré-effort/échauffement sportif : tapotement bref pour ↑ vigilance et trophicité sans fatiguer.","s":7},{"q":"Tapotement en \"bout de doigts\" sert à :","o":["Régions épaisses","Régions sensibles, visage, cuir chevelu","Plante des pieds seulement","Région lombaire"],"r":1,"e":"Percussion digitale (bouts de doigts) = douce, adaptée aux zones sensibles : visage, cuir chevelu.","s":7},{"q":"Après un tapotement vigoureux, conclure par :","o":["Un autre tapotement","Un effleurage doux pour normaliser","Une compression forte","Rien"],"r":1,"e":"Effleurage final = transition douce, intégration de la stimulation, retour au calme.","s":7},{"q":"Le tapotement se réalise :","o":["À une ou deux mains, avec différentes techniques, rythmes et durées","À deux mains obligatoirement","À une seule main","Avec l'avant-bras"],"r":0,"e":"Du français « tapoter », c'est-à-dire frapper.","s":7},{"q":"Le mécanisme physique du tapotement repose sur :","o":["La compression de l'air, qui provoque une onde de vibration pénétrant les tissus","Un contact profond direct","Une traction","Un glissement"],"r":0,"e":"L'exécution se fait sur la surface cutanée, avec une répétition rapide des mouvements.","s":7},{"q":"Parmi les objectifs du tapotement figure :","o":["L'activation mécanique du fuseau musculaire","La rupture des adhérences","L'allongement du tissu fibreux","Le drainage lymphatique"],"r":0,"e":"S'y ajoutent la stimulation tissulaire, l'augmentation de la circulation locale, la relaxation musculaire et la réduction de la perception de fatigue.","s":7},{"q":"Parmi les contre-indications du tapotement figurent :","o":["Les protubérances osseuses et les fractures ou suspicions de fracture","La fatigue","L'hypotonie","La contracture"],"r":0,"e":"Fièvre, altérations cutanées, thrombose, phlébite et tissus inflammatoires complètent la liste.","s":7},{"q":"Pour la modalité mains en coupe, les bras sont :","o":["En abduction, coudes fléchis","En adduction","Le long du corps","Tendus"],"r":0,"e":"Les mouvements sont rapides et coordonnés avec le mouvement du poignet.","s":7},{"q":"Pour la modalité bord cubital, la configuration est :","o":["Membres supérieurs en abduction, coudes fléchis, poignet en extension et doigts en flexion","Poignet en flexion","Coudes tendus","Doigts en extension"],"r":0,"e":"Les doigts peuvent être joints ou écartés, le mouvement restant rapide.","s":7},{"q":"La modalité bouts des doigts s'emploie :","o":["Sur les zones plus précises et plus délicates","Sur les grandes surfaces","Sur les masses musculaires","Sur le dos"],"r":0,"e":"Il s'agit de petits coups avec l'extrémité des doigts.","s":7},{"q":"Le tapotement est décrit comme une technique :","o":["Stimulante, à privilégier en début de séance ou pour activer un muscle hypotonique","Relaxante uniquement","Profonde","Analgésique"],"r":0,"e":"Paradoxalement, il peut aussi favoriser la relaxation en fin de séance.","s":7},{"q":"L'exigence technique centrale du tapotement est :","o":["La répétition rapide des mouvements","La lenteur","La pression maximale","La durée prolongée"],"r":0,"e":"C'est cette rapidité qui engendre l'onde de vibration.","s":7},{"q":"L'élévation de la température contre-indique le tapotement car :","o":["Elle signe un état fébrile ou inflammatoire","Elle augmente la douleur","Elle réduit l'effet","Elle gêne la palpation"],"r":0,"e":"Les tissus inflammatoires constituent une contre-indication distincte.","s":7},{"q":"L'effet du tapotement sur la perception de la fatigue est :","o":["Une réduction","Une augmentation","Aucun effet","Une variation imprévisible"],"r":0,"e":"Cet objectif accompagne la relaxation musculaire, malgré le caractère stimulant de la technique.","s":7},{"q":"L'exécution du tapotement se fait :","o":["Sur la surface cutanée","En profondeur","Sur le tendon","Sur le périoste"],"r":0,"e":"C'est l'onde de vibration engendrée qui pénètre ensuite dans les tissus.","s":7},{"q":"La friction permet de mobiliser :","o":["Uniquement la peau","Les masses tissulaires PLUS PROFONDES","Les os","L'air"],"r":1,"e":"La friction agit sur les masses tissulaires PLUS PROFONDES (au-delà des techniques superficielles).","s":8},{"q":"Une structure cible de la friction :","o":["Surface de la peau","Tendons, ligaments, fibres musculaires profondes, gaines synoviales, capsule articulaire","Air","Os"],"r":1,"e":"Cibles : fibres musculaires profondes, tendons, ligaments, gaines synoviales, fragments de capsule articulaire.","s":8},{"q":"Un effet thérapeutique de la friction est :","o":["Aucun effet","Augmente la température locale et a un effet analgésique","Refroidit","Endort la peau"],"r":1,"e":"↑ température locale → effet ANALGÉSIQUE local.","s":8},{"q":"La friction provoque :","o":["La formation d'adhérences","La RUPTURE des liaisons croisées et des adhérences","Aucun effet structurel","La calcification"],"r":1,"e":"La friction rompt les CROSS-LINKS (liaisons croisées) et les ADHÉRENCES → libère le glissement tissulaire.","s":8},{"q":"La friction est une action :","o":["Indirecte","Mécanique DIRECTE sur les tissus et les vaisseaux","Énergétique","Mentale"],"r":1,"e":"Action MÉCANIQUE DIRECTE sur les tissus et les vaisseaux.","s":8},{"q":"La friction favorise :","o":["La rigidité","L'élasticité des structures contractiles","La fibrose","La nécrose"],"r":1,"e":"Favorise l'ÉLASTICITÉ des structures contractiles (muscles, tendons).","s":8},{"q":"La friction augmente :","o":["L'apport sanguin","La fatigue","La rigidité","Rien"],"r":0,"e":"Augmente l'apport sanguin par stimulation locale.","s":8},{"q":"La friction est utile pour :","o":["Aucune adhérence","Les cicatrices ADHÉRENTES et les tendinopathies","Les plaies ouvertes","Les fractures aiguës"],"r":1,"e":"Très utilisée dans les adhérences cicatricielles et les tendinopathies (friction transverse profonde de Cyriax).","s":8},{"q":"La friction est une technique :","o":["Très étendue","Très ciblée et locale","Sans précision","Universelle"],"r":1,"e":"Technique CIBLÉE, locale, sur une lésion ou adhérence précise.","s":8},{"q":"Pour briser les adhérences, le mouvement de friction doit être :","o":["Parallèle aux fibres","Perpendiculaire aux fibres (transverse)","Aucun mouvement","Latéral seulement"],"r":1,"e":"Mouvements PERPENDICULAIRES aux fibres pour briser efficacement les adhérences.","s":8},{"q":"La friction agit sur les structures :","o":["Superficielles uniquement","Profondes (au-delà des techniques superficielles)","Aucune","Mentale"],"r":1,"e":"Friction = structures PROFONDES (fibres musculaires, tendons, ligaments, gaines, capsule).","s":8},{"q":"Une gaine synoviale peut-elle être mobilisée par friction ?","o":["Non","Oui, c'est une structure cible","Inutile","Dangereux"],"r":1,"e":"Oui — les gaines synoviales font partie des structures cibles de la friction.","s":8},{"q":"L'effet de la friction sur le sang est :","o":["Aucun","Augmentation de l'apport sanguin local","Diminution","Coagulation"],"r":1,"e":"↑ apport sanguin local (action mécanique directe sur les vaisseaux).","s":8},{"q":"La friction transverse profonde a été popularisée par :","o":["Field","Cyriax","Mitchell","Schultz"],"r":1,"e":"Friction TRANSVERSE PROFONDE = méthode de CYRIAX (massage transverse profond).","s":8},{"q":"Combien de structures cibles principales sont mentionnées pour la friction ?","o":["1","3","5 (fibres profondes, tendons, ligaments, gaines synoviales, capsule)","10"],"r":2,"e":"5 structures cibles : fibres musculaires profondes, tendons, ligaments, gaines synoviales, fragments de capsule articulaire.","s":8},{"q":"L'effet ANALGÉSIQUE de la friction vient de :","o":["L'extension","L'augmentation de la température locale","La diminution du sang","Aucun mécanisme"],"r":1,"e":"↑ température locale = effet analgésique (vasodilatation, gating de la douleur).","s":8},{"q":"La friction s'utilise typiquement en :","o":["Phase aiguë post-traumatique","Phase chronique pour cicatrices/adhérences/tendinopathies","Lors de fractures fraîches","Aucune phase"],"r":1,"e":"Indication typique : phase chronique pour briser les adhérences cicatricielles et traiter les tendinopathies.","s":8},{"q":"La friction peut briser :","o":["Les os","Les liaisons croisées (cross-links) tissulaires","Les muscles","Les nerfs"],"r":1,"e":"Rupture des CROSS-LINKS (liaisons croisées) responsables des adhérences fibreuses.","s":8},{"q":"En termes de profondeur d'action, la friction est une technique :","o":["De surface","De profondeur","Aérienne","Aucune"],"r":1,"e":"C'est une technique de PROFONDEUR, contrairement à l'effleurage qui est superficiel.","s":8},{"q":"L'objectif fonctionnel ultime de la friction est :","o":["Détruire le tissu","Restaurer la mobilité, l'élasticité et briser les adhérences","Endurcir le tissu","Ne rien faire"],"r":1,"e":"Restauration de la MOBILITÉ tissulaire, ÉLASTICITÉ des structures contractiles, et RUPTURE des adhérences.","s":8},{"q":"La friction de Cyriax cible spécifiquement :","o":["La peau seulement","Les tendons, ligaments et capsules avec adhérences/inflammation chronique","Le muscle profond uniquement","Les os"],"r":1,"e":"Friction transversale profonde (Cyriax) = traitement de référence des tendinopathies, ligaments, capsules avec adhérences.","s":8},{"q":"La direction de la friction transversale est :","o":["Parallèle aux fibres","Perpendiculaire (transversale) aux fibres du tendon ou ligament","Aléatoire","Toujours circulaire"],"r":1,"e":"Cyriax = perpendiculaire aux fibres pour rompre les adhérences entre fibres et tissus voisins.","s":8},{"q":"La friction se fait :","o":["Avec lubrifiant","Sans lubrifiant, peau immobile sur les tissus profonds","Avec beaucoup d'huile","Sur la peau qui glisse"],"r":1,"e":"Sans lubrifiant : la peau bouge AVEC le doigt sur la zone profonde sous-jacente.","s":8},{"q":"La durée typique d'une friction Cyriax sur une lésion est :","o":["30 secondes","5-15 minutes (jusqu'à l'analgésie locale)","Plusieurs heures","2 jours"],"r":1,"e":"Friction soutenue 5-15 min jusqu'à obtention d'une analgésie locale (effet inhibiteur des nocicepteurs).","s":8},{"q":"Une contre-indication de la friction profonde est :","o":["Tendinopathie chronique","Inflammation aiguë récente, hématome, infection, calcification","Cicatrice ancienne","Fatigue"],"r":1,"e":"CI : pas de friction profonde sur tissu en phase aiguë inflammatoire (aggrave). Privilégier après 48-72h.","s":8},{"q":"La friction circulaire vise plutôt :","o":["Les adhérences linéaires","Les cicatrices, zones péri-articulaires, points trigger localisés","Le rachis entier","Les organes"],"r":1,"e":"Friction circulaire (mouvements rotatifs) = adhérences cicatricielles, zones nodulaires.","s":8},{"q":"Après une friction profonde, on conseille :","o":["De rester immobile 24h","De mobiliser activement la zone (gain d'amplitude)","De plâtrer","De compresser"],"r":1,"e":"Mobilisation active post-friction = remodelage tissulaire orienté dans l'axe fonctionnel.","s":8},{"q":"L'instrument souvent utilisé en friction est :","o":["Le coude","Le pouce ou un doigt précis","La paume","Le poing"],"r":1,"e":"Friction = précision : pouce, index ou majeur. Petit point de contact pour focaliser la pression.","s":8},{"q":"L'effet local de la friction :","o":["Vasoconstriction","Hyperhémie locale (rougeur), analgésie, mobilisation des adhérences","Refroidissement","Tachycardie"],"r":1,"e":"Friction → rougeur (hyperémie), libération de médiateurs, analgésie locale, rupture progressive des adhérences.","s":8},{"q":"La friction est typiquement réalisée en position :","o":["Du muscle raccourci","Du muscle/tendon en tension ou position fonctionnelle","Avec patient debout","Sans contact"],"r":1,"e":"Tendon/ligament en tension légère facilite l'accès aux fibres et l'effet de la friction transversale.","s":8},{"q":"Parmi les structures cibles de la friction figurent :","o":["Les gaines synoviales et les fragments de capsule articulaire","La peau","Le tissu adipeux","Les vaisseaux superficiels"],"r":0,"e":"Fibres musculaires profondes, tendons et ligaments complètent les cinq structures cibles.","s":8},{"q":"L'effet analgésique de la friction résulte :","o":["De l'augmentation de la température locale","D'une action nerveuse directe","D'un blocage de la conduction","D'une vasoconstriction"],"r":0,"e":"Elle augmente aussi l'apport sanguin par une action mécanique directe sur les tissus et vaisseaux.","s":8},{"q":"Les mouvements de la friction sont :","o":["Perpendiculaires aux fibres, pour briser les adhérences","Parallèles aux fibres","Circulaires","Longitudinaux"],"r":0,"e":"Le contact se fait par le pouce ou l'index, directement sur la structure profonde.","s":8},{"q":"La durée d'application de la friction est :","o":["Limitée, car la technique est localement intense","Prolongée","Indifférente","D'au moins 20 minutes"],"r":0,"e":"La pression doit être suffisante pour atteindre la profondeur ciblée.","s":8},{"q":"La friction est particulièrement utilisée dans :","o":["Les tendinopathies, par la friction transverse profonde de Cyriax, et les cicatrices adhérentes","Les œdèmes","Les contractures","Les troubles circulatoires"],"r":0,"e":"Elle brise les adhérences fibreuses formées après une lésion ou une immobilisation.","s":8},{"q":"La friction est décrite comme une technique :","o":["Très ciblée et locale","Étendue","Globale","Superficielle"],"r":0,"e":"Son application porte sur une zone précise, ciblée sur la lésion ou l'adhérence.","s":8},{"q":"Les cross-links, que la friction rompt, désignent :","o":["Des liaisons croisées formant des adhérences","Des fibres musculaires","Des vaisseaux","Des terminaisons nerveuses"],"r":0,"e":"C'est l'objectif propre de la friction, qu'aucune autre technique ne revendique.","s":8},{"q":"L'action mécanique directe de la friction porte sur :","o":["Les tissus et les vaisseaux","La peau seule","Les nerfs seuls","Les os"],"r":0,"e":"Elle augmente ainsi l'apport sanguin dans la zone traitée.","s":8},{"q":"La friction agit en profondeur pour :","o":["Briser les adhérences fibreuses formées après une lésion ou une immobilisation","Drainer l'œdème","Relâcher le muscle","Stimuler le fuseau"],"r":0,"e":"C'est l'une des seules techniques ayant cette capacité.","s":8},{"q":"Le contact lors de la friction se fait :","o":["Avec les doigts, pouce ou index, directement sur la structure profonde","Avec la paume","Avec le poing","Avec l'avant-bras"],"r":0,"e":"La pression doit permettre d'atteindre la profondeur visée.","s":8},{"q":"La position anatomique de référence se définit par :","o":["Allongé bras le long du corps","Debout, regard à l'horizon, paumes vers l'AVANT, pieds parallèles","Assis","Debout paumes vers l'arrière"],"r":1,"e":"Position orthostatique, regard à l'horizon, MS le long du corps avec avant-bras en SUPINATION (paumes vers l'AVANT).","s":9},{"q":"Le plan sagittal divise le corps en :","o":["Antérieur/Postérieur","Droit/Gauche","Supérieur/Inférieur","Aucun"],"r":1,"e":"Sagittal = droit/gauche. Frontal = antérieur/postérieur. Transversal = supérieur/inférieur.","s":9},{"q":"Les mouvements d'abduction/adduction se font dans le plan :","o":["Sagittal","Frontal","Transversal","Aucun"],"r":1,"e":"Plan FRONTAL (axe sagittal) = abduction/adduction.","s":9},{"q":"La rotation interne/externe se fait dans le plan :","o":["Sagittal","Frontal","Transversal (axe vertical)","Aucun"],"r":2,"e":"Plan TRANSVERSAL (horizontal), axe vertical/longitudinal = rotations.","s":9},{"q":"Une diarthrose est :","o":["Une articulation immobile","Une articulation semi-mobile","Une articulation mobile avec liquide synovial","Une fracture"],"r":2,"e":"Diarthrose = articulation MOBILE de grande amplitude avec bourses synoviales + liquide synovial (ex: épaule, genou).","s":9},{"q":"Une suture crânienne est une :","o":["Diarthrose","Synarthrose fibreuse","Amphiarthrose","Synoviale"],"r":1,"e":"Suture = synarthrose FIBREUSE, immobile.","s":9},{"q":"L'articulation gléno-humérale est :","o":["Trochlée","Énarthrose (sphérique, triaxiale)","Arthrodie","Selle"],"r":1,"e":"Gléno-humérale = ÉNARTHROSE, triaxiale, mouvements amples.","s":9},{"q":"L'articulation trapézo-métacarpienne (pouce) est :","o":["Énarthrose","Trochoïde","Épiphysiarthrose / en selle (biaxiale)","Plate"],"r":2,"e":"Trapézo-métacarpienne = articulation EN SELLE, biaxiale.","s":9},{"q":"L'articulation radio-ulnaire supérieure est :","o":["Sphérique","Trochoïde / cylindrique (pivot, monoaxiale)","Plate","Selle"],"r":1,"e":"Trochoïde = cylindre en pivot, monoaxial → rotation autour d'un seul axe.","s":9},{"q":"Combien de degrés de liberté possède une énarthrose ?","o":["1","2","3 (tri-axial)","4"],"r":2,"e":"Énarthrose = 3 degrés de liberté (tri-axial), mouvements amples dans les 3 plans.","s":9},{"q":"Les mouvements accessoires sont :","o":["Volontaires et de grande amplitude","Non volontaires, intra-articulaires, faible amplitude, essentiels au mouvement normal","Inutiles","Mesurables par goniométrie"],"r":1,"e":"Accessoires = NON volontaires, intra-articulaires, faible amplitude, NON mesurables, mais ESSENTIELS.","s":9},{"q":"La règle convexe-concave (surface CONVEXE) :","o":["Glissement dans le même sens que le mouvement","Glissement dans le sens OPPOSÉ au mouvement physiologique","Pas de glissement","Roulement seulement"],"r":1,"e":"Surface CONVEXE → glissement OPPOSÉ au mouvement. Surface concave → glissement DANS LE MÊME sens.","s":9},{"q":"Le roulement (mouvement accessoire) se fait :","o":["Dans le sens opposé au mouvement osseux","Toujours dans le MÊME sens que le mouvement osseux","Sans congruence","Sans direction"],"r":1,"e":"Le roulement se produit TOUJOURS dans le MÊME sens que le mouvement de l'os. Il produit compression articulaire.","s":9},{"q":"La mobilisation PASSIVE est définie par :","o":["Contraction du patient seule","Réalisée par une autre personne sans intervention active du patient (force externe)","Pas de mouvement","Mouvement actif libre"],"r":1,"e":"Passive = réalisée par AUTRUI, sans intervention active du patient (force externe seule).","s":9},{"q":"Une indication TYPIQUE de mobilisation articulaire (Kisner & Colby) est :","o":["Fracture aiguë","Hypomobilité articulaire réversible","Hypermobilité instable","Maladie oncologique active"],"r":1,"e":"5 indications : douleur/spasmes, HYPOMOBILITÉ réversible, défauts de positionnement, ↓ progressive ROM, immobilité fonctionnelle.","s":9},{"q":"L'immobilisation prolongée provoque :","o":["Renforcement du cartilage","Atrophie du cartilage, adhérences, contractures","Augmentation de l'amplitude","Aucun effet"],"r":1,"e":"Immobilisation = atrophie cartilage, prolifération fibro-adipeuse, adhérences, contractures, affaiblissement ligamentaire.","s":9},{"q":"Le cartilage articulaire est :","o":["Très vascularisé","AVASCULAIRE — nourri par la circulation du liquide synovial","Innervé","Constitué d'os"],"r":1,"e":"Le cartilage est AVASCULAIRE → la mobilisation est essentielle pour faire circuler le liquide synovial qui le nourrit.","s":9},{"q":"La mobilisation articulaire physiologique :","o":["Augmente la force musculaire","Ne prévient PAS l'atrophie musculaire et n'augmente PAS la force","Augmente l'endurance","Remplace l'exercice musculaire"],"r":1,"e":"LIMITES : la mobilisation NE prévient PAS l'atrophie musculaire, N'AUGMENTE PAS la force ou l'endurance.","s":9},{"q":"Une contre-indication ABSOLUE à la mobilisation articulaire est :","o":["Douleur légère","Lésions aiguës, fractures, chirurgies","Hypomobilité chronique","Douleur ancienne"],"r":1,"e":"Contre-indications : lésions aiguës, fractures, chirurgies (mais mouvements précoces contrôlés possibles avec tolérance).","s":9},{"q":"L'end-feel DUR se rencontre typiquement à :","o":["La fin de la flexion du coude","La fin de l'EXTENSION passive du coude (os contre os)","La rotation de l'épaule","La flexion de l'épaule"],"r":1,"e":"End-feel DUR (os contre os) = fin de l'extension passive du COUDE.","s":9},{"q":"L'end-feel SOUPLE correspond à :","o":["Os contre os","Rapprochement de tissus mous (ex: fin de flexion du coude)","Étirement de la capsule","Aucune sensation"],"r":1,"e":"Souple = rapprochement de TISSUS MOUS (ex: fin de flexion du coude où biceps et avant-bras se compriment).","s":9},{"q":"Le grade III dans la graduation Kaltenborn correspond à :","o":["Petite amplitude au début","Grande amplitude SANS atteindre la limite","Plus grande amplitude JUSQU'À la limite (étirement)","Thrust"],"r":2,"e":"Grade III = plus grande amplitude JUSQU'À la limite — pour étirement, forçage de la résistance des tissus.","s":9},{"q":"Le grade V (thrust) se caractérise par :","o":["Mouvement lent contrôlé","Mouvement RAPIDE, petite amplitude, à la limite, hors du contrôle du patient","Mouvement physiologique","Étirement progressif"],"r":1,"e":"Grade V = manipulation thrust : RAPIDE, petite amplitude, à la limite, HORS du contrôle du patient.","s":9},{"q":"Quelle structure protège l'articulation et contient des nerfs sensitifs ?","o":["Cartilage hyalin","Membrane fibreuse (externe) de la capsule articulaire","Os sous-chondral","Liquide synovial"],"r":1,"e":"La membrane FIBREUSE (externe) = tissu conjonctif dense, protection. Contient les mécanorécepteurs/nocicepteurs.","s":9},{"q":"La membrane SYNOVIALE :","o":["Est externe","Est interne et PRODUIT le liquide synovial","Contient des nerfs","Est constituée d'os"],"r":1,"e":"Membrane synoviale = INTERNE, produit le LIQUIDE SYNOVIAL. Peut s'étendre comme une bourse (ex: épaule).","s":9},{"q":"Le grade I de Kaltenborn (mobilisation accessoire) correspond à :","o":["Forte traction au-delà de la résistance","Traction très douce pour annuler la pression intra-articulaire","Mobilisation maximale forcée","Aucun mouvement"],"r":1,"e":"Grade I = traction antalgique très douce, neutralise la pression articulaire, sans étirement capsulaire.","s":9},{"q":"Le grade III de Kaltenborn :","o":["Sans étirement","Traction au-delà de la résistance (étirement capsulaire) = gain d'amplitude","Compression","Aucun"],"r":1,"e":"Grade III = traction maximale, étire la capsule → gain d'amplitude. À pratiquer avec précaution.","s":9},{"q":"Le end-feel \"capsulaire\" (ferme) est :","o":["Pathologique","Normal pour la rotation externe de l'épaule (capsule postérieure tendue)","Indique une fracture","Signe d'instabilité"],"r":1,"e":"End-feel ferme/capsulaire = arrêt par tension capsulaire (rotation externe normale de l'épaule).","s":9},{"q":"Un end-feel \"vide\" évoque :","o":["Une fin d'amplitude normale","Une douleur forte sans butée physique (pathologique : inflammation, tumeur)","Une rigidité","Une hyperlaxité"],"r":1,"e":"End-feel vide = douleur intense sans résistance physique → orientation pathologique (inflammation, néoplasie).","s":9},{"q":"La règle convexe-concave : si surface convexe mobile sur concave fixe, glissement et roulement vont :","o":["Dans le même sens","Dans des sens OPPOSÉS","Glissement seul","Roulement seul"],"r":1,"e":"Convexe mobile sur concave fixe → glissement et roulement OPPOSÉS (ex : tête humérale qui monte en abduction).","s":9},{"q":"Le mouvement se définit comme :","o":["Un acte ou processus de changement de position par rapport à un point de référence, autour d'un axe et dans une direction","Une contraction musculaire","Un déplacement du corps entier","Une variation de tonus"],"r":0,"e":"Sans changement de position, le corps est au repos.","s":9},{"q":"Dans la position anatomique de référence, les pieds sont :","o":["Écartés et parallèles, talons ensemble","Joints","Écartés à largeur d'épaules","En rotation externe"],"r":0,"e":"Les avant-bras sont en supination, paumes vers l'avant, et le regard à l'horizon.","s":9},{"q":"L'axe du plan transversal est :","o":["Longitudinal ou vertical","Frontal","Sagittal","Antéro-postérieur"],"r":0,"e":"Le plan sagittal a un axe frontal, le plan frontal un axe sagittal.","s":9},{"q":"La flexion latérale du tronc se produit dans le plan :","o":["Frontal","Sagittal","Transversal","Oblique"],"r":0,"e":"L'abduction-adduction et l'inversion-éversion s'y produisent également.","s":9},{"q":"L'abduction et l'adduction horizontales se produisent dans le plan :","o":["Transversal","Sagittal","Frontal","Oblique"],"r":0,"e":"La pronation-supination et les rotations interne et externe s'y produisent aussi.","s":9},{"q":"Les syndesmoses et les gomphoses appartiennent aux articulations :","o":["Fibreuses, faites de collagène de type I et sans cavité","Cartilagineuses","Synoviales","Semi-mobiles"],"r":0,"e":"Cette classification structurelle est reprise de Seeley et al. (2021).","s":9},{"q":"Les articulations synoviales contiennent un cartilage hyalin fait de :","o":["Collagène de type II","Collagène de type I","Élastine","Fibrocartilage"],"r":0,"e":"Les articulations fibreuses contiennent, elles, du collagène de type I.","s":9},{"q":"L'articulation occipito-atloïdienne est de type :","o":["Condylienne, donc biaxiale","Trochléenne","Trochoïde","Énarthrose"],"r":0,"e":"La radio-carpienne partage ce type ; la trapézo-métacarpienne est en selle.","s":9},{"q":"L'articulation fémoro-patellaire est de type :","o":["Trochléenne, monoaxiale","Arthrodie","Condylienne","Énarthrose"],"r":0,"e":"L'huméro-ulnaire partage ce type ; les apophyses articulaires des vertèbres sont des arthrodies.","s":9},{"q":"La membrane fibreuse de la capsule articulaire :","o":["Est faite de tissu conjonctif dense, assure la protection et peut contenir des ligaments","Produit le liquide synovial","Forme des bourses","Est dépourvue de nerfs"],"r":0,"e":"Elle contient les nerfs sensitifs, mécanorécepteurs et nocicepteurs.","s":9},{"q":"La membrane synoviale peut :","o":["S'étendre sous forme de bourse, comme à l'épaule","Contenir des ligaments","Être dépourvue de vaisseaux","Produire du cartilage"],"r":0,"e":"Elle produit le liquide synovial, à l'intérieur de la capsule.","s":9},{"q":"Les articulations à un degré de liberté sont :","o":["Les trochlées et les trochoïdes","Les condyliennes et les selles","Les énarthroses","Les arthrodies"],"r":0,"e":"Deux degrés correspondent aux condyliennes et aux selles, trois aux énarthroses.","s":9},{"q":"Le roulement, parmi les mouvements accessoires :","o":["Se fait toujours dans le même sens que le mouvement osseux, avec compression articulaire","Se fait en sens opposé","Nécessite une congruence parfaite","Est volontaire"],"r":0,"e":"Le glissement nécessite, lui, une congruence articulaire.","s":9},{"q":"Les mouvements accessoires sont régulés par :","o":["La tension des éléments périarticulaires, capsulo-ligamentaires ou musculaires selon l'articulation","Le seul muscle","Le seul ligament","La volonté"],"r":0,"e":"Le genou est à dominante capsulo-ligamentaire, l'épaule à dominante musculaire par la coiffe.","s":9},{"q":"Un déficit d'extensibilité ou une lésion des plans de glissement entraîne :","o":["Une modification de la mécanique, avec déficit d'amplitude et douleur","Une hypermobilité","Une amélioration du glissement","Aucune conséquence"],"r":0,"e":"C'est ce qui justifie le travail sur les mouvements accessoires.","s":9},{"q":"La règle convexe-concave citée dans ce cours provient de :","o":["Kisner & Colby (2022)","Kaltenborn seul","Maitland","Cyriax"],"r":0,"e":"Une surface concave glisse dans le même sens que le mouvement physiologique, une surface convexe en sens opposé.","s":9},{"q":"La mobilisation active-assistée associe :","o":["Une contraction musculaire du patient et une force externe","Une force externe seule","Une contraction seule","Une relaxation"],"r":0,"e":"La mobilisation passive est réalisée par une autre personne, sans intervention active du patient.","s":9},{"q":"La circumduction se définit comme :","o":["Une combinaison de mouvements dans les trois plans, vraiment possible dans les énarthroses","Une rotation pure","Une flexion-extension","Un mouvement accessoire"],"r":0,"e":"Elle figure parmi les mouvements physiologiques, mesurables et volontaires.","s":9},{"q":"Les mouvements accessoires se distinguent des physiologiques par :","o":["Leur caractère intra-articulaire, non volontaire et non mesurable","Leur grande amplitude","Leur mesurabilité","Leur contrôle volontaire"],"r":0,"e":"Ils restent essentiels pour que les mouvements physiologiques soient considérés comme normaux.","s":9},{"q":"Les symphyses du bassin et des corps vertébraux correspondent à des :","o":["Amphiarthroses, semi-mobiles","Synarthroses","Diarthroses","Articulations fibreuses"],"r":0,"e":"Les synarthroses, immobiles, comme les sutures crâniennes, et les diarthroses, très mobiles, complètent cette classification fonctionnelle.","s":9},{"q":"L'articulation gléno-humérale est de type :","o":["Arthrodie","Énarthrose (sphérique)","Trochlée","Trochoïde"],"r":1,"e":"Gléno-humérale = ÉNARTHROSE (sphérique), triaxiale, mouvements amples mais couverture de seulement 25-30%.","s":10},{"q":"L'articulation acromio-claviculaire est :","o":["Énarthrose","Arthrodie (plate)","Selle","Trochlée"],"r":1,"e":"Acromio-claviculaire = ARTHRODIE (plate).","s":10},{"q":"L'articulation sterno-claviculaire est :","o":["Énarthrose","Arthrodie","Épiphysiarthrose (en selle)","Trochlée"],"r":2,"e":"Sterno-claviculaire = en SELLE (épiphysiarthrose).","s":10},{"q":"La couverture de la cavité glénoïde par la tête humérale est d'environ :","o":["10%","25-30%","50%","80%"],"r":1,"e":"25-30% (Li et al., 2013) — d'où une grande mobilité mais une stabilité réduite. Le bourrelet l'augmente.","s":10},{"q":"Lors de l'abduction d'épaule, la phase 60°-120° implique :","o":["Gléno-humérale seule","Gléno-humérale + scapulo-thoracique","Inclinaison du tronc seule","Aucune articulation"],"r":1,"e":"Phase 60°-120° : ajout de l'articulation SCAPULO-THORACIQUE. Phase 120°-180° : inclinaison du côté opposé.","s":10},{"q":"Pourquoi la rotation externe d'épaule est-elle nécessaire en fin de flexion/abduction ?","o":["Pour le confort","Pour éviter le contact entre tubercule majeur et acromion","Pour augmenter la rotation interne","Aucune raison"],"r":1,"e":"Rotation externe = évite le CONFLIT entre le tubercule majeur de l'humérus et l'acromion.","s":10},{"q":"L'articulation huméro-ulnaire est :","o":["Énarthrose","Trochlée","Trochoïde","Plate"],"r":1,"e":"Huméro-ulnaire = TROCHLÉE, articulation monoaxiale (flexion/extension).","s":10},{"q":"La radio-ulnaire supérieure est :","o":["Trochlée","Trochoïde (cylindrique) — pour la pronation/supination","Énarthrose","Selle"],"r":1,"e":"Radio-ulnaire supérieure = TROCHOÏDE (cylindrique), permet la pronation/supination.","s":10},{"q":"Amplitude de flexion du coude :","o":["90°","120°","145°","180°"],"r":2,"e":"Flexion du coude ≈ 145°.","s":10},{"q":"Amplitudes pronation/supination de l'avant-bras :","o":["45°/45°","90°/90°","120°/120°","180°/180°"],"r":1,"e":"Pronation 90° / Supination 90°.","s":10},{"q":"L'articulation radio-carpienne (poignet) est de type :","o":["Énarthrose","Trochoïde","Condylienne (elliptique)","Trochlée"],"r":2,"e":"Radio-carpienne = CONDYLIENNE, biaxiale (flexion/extension + déviations).","s":10},{"q":"Déviation ulnaire du poignet :","o":["20°","35°","70°","80°"],"r":1,"e":"Déviation ulnaire ≈ 35° ; déviation radiale ≈ 20°.","s":10},{"q":"L'articulation trapézo-métacarpienne du pouce est :","o":["Énarthrose","En SELLE (épiphysiarthrose)","Plate","Trochlée"],"r":1,"e":"Trapézo-métacarpienne = articulation EN SELLE, permettant l'opposition du pouce.","s":10},{"q":"La hanche est de type :","o":["Arthrodie","Énarthrose (sphérique) - triaxiale","Trochlée","Selle"],"r":1,"e":"Hanche = ÉNARTHROSE sphérique triaxiale. Mais couverture acétabulaire = 70-83% (plus stable que l'épaule).","s":10},{"q":"La couverture acétabulaire (hanche) est d'environ :","o":["20-30%","50%","70-83%","100%"],"r":2,"e":"Couverture acétabulaire = 70-83% (Tannast et al., 2015). Comparée à 25-30% pour la gléno-humérale.","s":10},{"q":"Angle du col fémoral :","o":["90°","125°","180°","60°"],"r":1,"e":"Angle col fémoral = 125° (dissipation des forces).","s":10},{"q":"Flexion ACTIVE de hanche avec extension du genou :","o":["90° (interférence des ischio-jambiers)","140°","180°","30°"],"r":0,"e":"Avec EXTENSION du genou : 90° (les ischio-jambiers limitent). Avec FLEXION du genou : 125°. Passive : 140°.","s":10},{"q":"Le genou est composé de :","o":["Fémoro-patellaire (trochlée) + fémoro-tibiale (bicondylienne)","Trochoïde uniquement","Énarthrose","Arthrodie"],"r":0,"e":"Genou = fémoro-patellaire (TROCHLÉE monoaxiale) + fémoro-tibiale (BICONDYLIENNE biaxiale).","s":10},{"q":"Lors de l'EXTENSION du genou, la jambe effectue automatiquement :","o":["Rotation interne","Rotation EXTERNE","Aucune rotation","Inversion"],"r":1,"e":"Rotation axiale automatique : EXTENSION → rotation EXTERNE. FLEXION → rotation INTERNE.","s":10},{"q":"L'articulation tibio-tarsienne est :","o":["Trochlée (monoaxiale)","Énarthrose","Selle","Arthrodie"],"r":0,"e":"Tibio-tarsienne = TROCHLÉE, monoaxiale (flexion dorsale/plantaire).","s":10},{"q":"Flexion dorsale de la cheville :","o":["20°","45°","70°","90°"],"r":0,"e":"Flexion dorsale ≈ 20° ; flexion plantaire ≈ 45°.","s":10},{"q":"L'inversion et l'éversion du pied se font à :","o":["La tibio-tarsienne","La sous-talienne (astragalo-calcanéenne)","Le métatarse","Le carpe"],"r":1,"e":"Inversion (35°) / Éversion (20°) = articulation SOUS-TALIENNE (astragalo-calcanéenne).","s":10},{"q":"Le 1er orteil (gros orteil) a une extension de :","o":["20°","45°","90°","120°"],"r":2,"e":"1er orteil : flexion 45°, extension 90° (besoin pour la phase propulsive de la marche).","s":10},{"q":"Une précaution clé lors de mobilisation est :","o":["Aller vite","Tension PROGRESSIVE dans les structures, éviter la douleur","Forcer le mouvement","Ignorer la pathologie"],"r":1,"e":"Tension PROGRESSIVE + éviter la douleur + individualiser l'articulation + éviter les compensations.","s":10},{"q":"Concernant la tenue du kinésithérapeute, il faut :","o":["Bijoux et accessoires libres","Uniforme, cheveux attachés, ongles coupés, pas d'accessoires, hygiène","Vêtements amples","Aucune règle"],"r":1,"e":"Uniforme (haut/short), cheveux ATTACHÉS, ongles COUPÉS, sans accessoires, hygiène — sécurité et professionnalisme.","s":10},{"q":"L'amplitude normale de flexion du genou est ≈ :","o":["60°","90°","135°","180°"],"r":2,"e":"Flexion du genou ≈ 135° (peut atteindre 150-160° en flexion talon-fesse).","s":10},{"q":"L'amplitude d'abduction de l'épaule (gléno-humérale + scapulaire) :","o":["45°","90°","180° (élévation totale)","270°"],"r":2,"e":"Élévation totale du membre supérieur ≈ 180° (90° gléno-huméral pur + 60° scapulaire + 30° rachidien).","s":10},{"q":"La dorsiflexion (flexion dorsale) de cheville normale est ≈ :","o":["5°","20°","60°","90°"],"r":1,"e":"Flexion dorsale ≈ 20° (genou tendu) / 30° (genou fléchi). Flexion plantaire ≈ 40-50°.","s":10},{"q":"L'opposition du pouce s'effectue à l'articulation :","o":["MCP","Trapézo-métacarpienne (sellaire)","IPP","Radio-carpienne"],"r":1,"e":"Trapézo-métacarpienne = articulation sellaire (2 axes) qui permet le mouvement complexe d'opposition.","s":10},{"q":"La rotation externe de hanche (en décubitus dorsal, genou tendu) est ≈ :","o":["10°","45°","90°","180°"],"r":1,"e":"Rotation externe de hanche ≈ 45° (genou fléchi à 90° pour la mesure standard).","s":10},{"q":"Selon Li et al. (2013), la couverture gléno-humérale est de :","o":["25 à 30 %","50 %","70 %","10 %"],"r":0,"e":"D'où une grande mobilité et une moindre stabilité ; le bourrelet glénoïdien augmente la profondeur de la cavité.","s":10},{"q":"Dans les trois phases de l'abduction, la phase de 60 à 120° ajoute :","o":["L'articulation scapulo-thoracique","L'inclinaison controlatérale","La seule gléno-humérale","La sterno-claviculaire"],"r":0,"e":"De 0 à 60°, la gléno-humérale agit seule ; au-delà de 120°, s'ajoute l'inclinaison du côté opposé.","s":10},{"q":"La rotation externe dans les derniers degrés de flexion et d'abduction évite :","o":["Le contact entre le tubercule majeur et l'acromion, donc le conflit sous-acromial","Une luxation","Une tendinite du biceps","Une raideur capsulaire"],"r":0,"e":"C'est un mécanisme protecteur automatique du complexe de l'épaule.","s":10},{"q":"L'adduction horizontale de l'épaule atteint :","o":["140°, bras à 90° de flexion","30°","90°","80°"],"r":0,"e":"L'abduction horizontale atteint 30°, la rotation interne 90° et la rotation externe 80°, coude fléchi à 90°.","s":10},{"q":"L'articulation huméro-radiale est de type :","o":["Condylienne","Trochléenne","Trochoïde","Arthrodie"],"r":0,"e":"L'huméro-ulnaire est trochléenne et la radio-ulnaire supérieure trochoïde.","s":10},{"q":"La tête du radius s'articule avec :","o":["Le condyle huméral et la petite cavité sigmoïde","La trochlée humérale","La grande cavité sigmoïde","L'olécrane"],"r":0,"e":"La trochlée humérale s'articule avec la grande cavité sigmoïde de l'ulna.","s":10},{"q":"Lors de la flexion du poignet, la répartition entre radio-carpienne et carpe est de :","o":["60/40 %","40/60 %","50/50 %","80/20 %"],"r":0,"e":"En extension, la proportion s'inverse en 40/60 %.","s":10},{"q":"Les articulations intercarpiennes sont :","o":["Des arthrodies, permettant un mouvement de glissement","Des condyliennes","Des trochléennes","Des énarthroses"],"r":0,"e":"La radio-carpienne est, elle, condylienne.","s":10},{"q":"Les articulations métacarpo-phalangiennes sont :","o":["Condyliennes","Trochléennes","Planes","En selle"],"r":0,"e":"Les interphalangiennes sont trochléennes et les carpo-métacarpiennes planes.","s":10},{"q":"L'abduction du pouce atteint :","o":["40 à 50°","80°","90°","20°"],"r":0,"e":"L'adduction atteint 80° ; la trapézo-métacarpienne est une articulation en selle.","s":10},{"q":"Selon Tannast et al. (2015), la couverture acétabulaire est de :","o":["70 à 83 %","25 à 30 %","50 %","95 %"],"r":0,"e":"Le bourrelet acétabulaire augmente cette couverture d'environ 30 %.","s":10},{"q":"L'angle du col fémoral est de :","o":["125°","135°","110°","145°"],"r":0,"e":"La hanche est une énarthrose triaxiale, associant tête fémorale et acétabulum.","s":10},{"q":"La flexion active de hanche avec extension du genou atteint :","o":["90°, du fait de l'interférence des ischio-jambiers","125°","140°","45°"],"r":0,"e":"Avec flexion du genou elle atteint 125°, et 140° en passif.","s":10},{"q":"L'adduction pure de hanche :","o":["N'existe pas isolément et se combine à une flexion ou une extension","Atteint 45°","Se fait dans le plan sagittal","Est indépendante"],"r":0,"e":"L'abduction atteint 45° et l'adduction 15°.","s":10},{"q":"L'articulation fémoro-patellaire est de type :","o":["Trochléenne, monoaxiale","Condylienne","Arthrodie","Énarthrose"],"r":0,"e":"Elle complète l'articulation fémoro-tibiale dans le complexe du genou.","s":10},{"q":"La flexion des interphalangiennes proximales des doigts atteint :","o":["100°","90°","80°","120°"],"r":0,"e":"Les métacarpo-phalangiennes fléchissent à 90° et les interphalangiennes distales à 80°.","s":10},{"q":"Les mouvements physiologiques de l'épaule cités selon Kapandji (2019) comprennent :","o":["Flexion, extension, hyperextension, abduction, adduction, rotations et abduction-adduction horizontales, et circumduction","Flexion et extension seulement","Les seules rotations","Les seuls mouvements dans le plan frontal"],"r":0,"e":"Cette liste couvre les trois plans de l'espace.","s":10},{"q":"L'articulation sterno-claviculaire est de type :","o":["Épiphysiarthrose, c'est-à-dire en selle","Arthrodie","Énarthrose","Trochléenne"],"r":0,"e":"L'acromio-claviculaire est une arthrodie et la gléno-humérale une énarthrose.","s":10},{"q":"La pronation et la supination de l'avant-bras se font :","o":["Dans le plan transversal, autour d'un axe vertical, à 90° chacune","Dans le plan sagittal","Dans le plan frontal","Sans axe défini"],"r":0,"e":"La flexion du coude atteint 145°, dans le plan sagittal autour d'un axe frontal.","s":10},{"q":"Parmi les os du carpe cités dans cette fiche figurent :","o":["Le lunatum, le triquétrum, le grand os et l'unciforme","Le scaphoïde et le pisiforme seulement","Le trapèze et le trapézoïde seulement","Tous les huit os"],"r":0,"e":"Le mouvement du poignet associe la radio-carpienne et le glissement des os du carpe.","s":10},{"q":"Combien d'ECTS valent l'UC Stratégies d'évaluation et d'intervention en physiothérapie I ?","o":["4","6","8","12"],"r":2,"e":"8 ECTS pour 216 h de travail total, 120 h de contact.","s":11},{"q":"Combien de domaines thématiques composent l'UC ?","o":["3","4","5","7"],"r":2,"e":"5 domaines : Massage, Mob.Art.Physio, Anatomie palpatoire, PTAM, Corps et conscience.","s":11},{"q":"Quel module a la pondération la PLUS BASSE ?","o":["Massage (25%)","Corps et conscience (10%)","PTAM (15%)","Anatomie palpatoire (25%)"],"r":1,"e":"Corps et conscience = 10% (la plus basse). Massage, Anat. palpatoire et Mob.Art.Physio = 25% chacun.","s":11},{"q":"Quelles techniques de massage sont mentionnées ?","o":["Acupression et reiki","Effleurage, pétrissage, friction","Massage thaï uniquement","Kinésio-tape"],"r":1,"e":"Techniques de mobilisation tissulaire : EFFLEURAGE, PÉTRISSAGE, FRICTION.","s":11},{"q":"Note minimale pour valider l'UC par évaluation continue (par module) :","o":["8","10","12","14"],"r":1,"e":"Note minimale = 10/20 dans CHAQUE module pour être dispensé de l'examen final.","s":11},{"q":"Quelle méthodologie d'examen pratique est utilisée ?","o":["QCM uniquement","OSCE (Objective Structured Clinical Examination)","Dissertation","Exposé oral"],"r":1,"e":"OSCE = stations/scénarios pour tester compétences cliniques, communication, raisonnement, compétences pratiques.","s":11},{"q":"Le modèle pédagogique POGIL signifie :","o":["Practical Oriented Group Inquiry Learning","Process Oriented Guided Inquiry Learning","Patient Oriented Group Inquiry Learning","Aucune"],"r":1,"e":"POGIL = Process Oriented Guided Inquiry Learning.","s":11},{"q":"CBL signifie :","o":["Clinical Bedside Learning","Case Based Learning","Care Based Learning","Cognitive Behavioral Learning"],"r":1,"e":"CBL = Case Based Learning, pour rapprocher la théorie de la pratique clinique.","s":11},{"q":"PTAM signifie :","o":["Positionnement, Transferts, Anatomie, Massage","Positionnement, Transferts et Aides à la Marche","Pratiques Théoriques d'Aide à la Mobilité","Aucune"],"r":1,"e":"PTAM = Positionnement, Transferts et Aides à la Marche.","s":11},{"q":"Combien d'heures de pratique et laboratoire (PL) sont prévues ?","o":["30 h","60 h","90 h","120 h"],"r":2,"e":"90 h de PL + 30 h de TP = 120 h de contact total.","s":11},{"q":"L'UC se déroule à quel semestre ?","o":["1er semestre, 1ère année","2e semestre, 1ère année","1er semestre, 2e année","2e semestre, 2e année"],"r":0,"e":"1er semestre, 1ère année de Licence en physiothérapie.","s":11},{"q":"Quel module n'est évalué QUE théoriquement ?","o":["Massage","Mobilisation articulaire physiologique","Corps et conscience","PTAM"],"r":2,"e":"Corps et conscience = théorique uniquement (10% de la note finale).","s":11},{"q":"Quel module n'est évalué QUE pratiquement ?","o":["Massage","Anatomie palpatoire","Corps et conscience","PTAM"],"r":1,"e":"Anatomie palpatoire = uniquement pratique (25%).","s":11},{"q":"Quelle enseignante est la responsable de l'UC ?","o":["Enseignante B","Enseignante A","Enseignante C","Enseignante F"],"r":1,"e":"Enseignante A = enseignante responsable, professeure assistante.","s":11},{"q":"L'enseignante avec le plus grand nombre d'heures (25 h) est :","o":["Enseignante A (20 h)","Enseignante B (15 h)","Enseignante C (25 h)","Enseignante F"],"r":2,"e":"Enseignante C = 25 h (6 TP + 19 PL), maximum des trois enseignantes.","s":11},{"q":"Quel pourcentage d'heures de contact se fait en présence physique ?","o":["50%","75%","100%","0%"],"r":2,"e":"100% en présence (modalité présentielle).","s":11},{"q":"Le total d'heures de travail demandé à l'étudiant est :","o":["120 h","150 h","216 h","300 h"],"r":2,"e":"216 h totales (120 h de contact + travail personnel).","s":11},{"q":"L'effleurage est :","o":["Une mobilisation articulaire","Une technique de massage (mobilisation tissulaire)","Une aide à la marche","Un transfert"],"r":1,"e":"L'EFFLEURAGE est une technique de mobilisation tissulaire (massage), avec le pétrissage et la friction.","s":11},{"q":"Pratiquer la palpation fait partie de quel module ?","o":["Massage","Anatomie palpatoire","Corps et conscience","PTAM"],"r":1,"e":"Module ANATOMIE PALPATOIRE = identification et palpation des structures anatomiques.","s":11},{"q":"L'UC vise la maîtrise des techniques de mobilisation des :","o":["Articulations centrales uniquement","Articulations périphériques","Aucune articulation","Os longs uniquement"],"r":1,"e":"Mob.Art.Physio. = techniques de mobilisation des ARTICULATIONS PÉRIPHÉRIQUES.","s":11},{"q":"L'examen OSCE évalue :","o":["Connaissances livresques seulement","Compétences cliniques, communication, raisonnement clinique, pratique","Endurance physique","Aucun critère"],"r":1,"e":"OSCE = compétences cliniques, communication, raisonnement clinique, compétences pratiques.","s":11},{"q":"Tous les moments d'évaluation sont :","o":["Facultatifs","Obligatoires","Au choix","Annulables"],"r":1,"e":"Tous les moments d'évaluation sont OBLIGATOIRES.","s":11},{"q":"Une absence de validation d'un module entraîne :","o":["L'UC validée quand même","Inscription automatique à l'examen final couvrant tout le contenu","Une compensation auto","L'échec définitif"],"r":1,"e":"Si la note minimale n'est pas atteinte dans chaque module → examen final OBLIGATOIRE sur TOUT le contenu.","s":11},{"q":"Mobilité précoce au lit fait partie de :","o":["Massage","PTAM","Anatomie palpatoire","Corps et conscience"],"r":1,"e":"PTAM = Positionnement, Transferts et Aides à la Marche — inclut la mobilité précoce au lit.","s":11},{"q":"Le concept du toucher comme facilitateur de la relation thérapeutique est étudié dans :","o":["Massage","Corps et conscience","Mob.Art.Physio.","PTAM"],"r":1,"e":"Module CORPS ET CONSCIENCE = concept du toucher, interprétation, toucher comme facilitateur de la relation thérapeutique.","s":11},{"q":"Un OSCE évalue principalement :","o":["Les connaissances théoriques seules","Les compétences pratiques observables sur stations standardisées","Le QI","La culture générale"],"r":1,"e":"OSCE (Objective Structured Clinical Examination) = circuit de stations courtes évaluant un geste/compétence précis.","s":11},{"q":"L'EAIF I correspond à quelle année de formation ?","o":["3ème année","Licence 1 (L1)","Master","Doctorat"],"r":1,"e":"EAIF I = unité curriculaire du 1er cycle (L1) en kinésithérapie.","s":11},{"q":"La répartition de la note du module mobilisation articulaire est :","o":["50 %","25 % de la note finale","100 %","5 %"],"r":1,"e":"Mobilisation articulaire = 25 % de la note finale de l'UC EAIF I.","s":11},{"q":"Le module Corps et Conscience pèse :","o":["1 % de la note","10 % de la note","50 %","100 %"],"r":1,"e":"Corps et Conscience = 10 % de la note finale.","s":11},{"q":"Le crédit ECTS de l'UC EAIF I est :","o":["1 ECTS","8 ECTS","30 ECTS","60 ECTS"],"r":1,"e":"EAIF I = 8 ECTS (charge de travail étudiant ≈ 200-240 h, équivalent semestre dense).","s":11},{"q":"L'UC EAIF I comporte au total :","o":["216 heures de travail, dont 120 heures de contact","120 heures de travail","216 heures de contact","90 heures"],"r":0,"e":"La présence aux heures de contact est de 100 %.","s":11},{"q":"Les heures de contact se répartissent en :","o":["30 h théorique-pratique et 90 h pratique et laboratoire","90 h théorique et 30 h pratique","60 h de chaque","120 h de pratique"],"r":0,"e":"La part pratique et laboratoire représente donc les trois quarts des heures de contact.","s":11},{"q":"La responsable de l'UC est :","o":["Enseignante A","Enseignante B","Enseignante C","Enseignante G"],"r":0,"e":"Elle assure 20 heures, réparties en 6 h TP et 14 h PL.","s":11},{"q":"L'enseignante assurant le plus grand nombre d'heures est :","o":["Enseignante C, avec 25 heures","Enseignante A, avec 20 heures","Enseignante B, avec 15 heures","Enseignante G"],"r":0,"e":"Ses 25 heures se répartissent en 6 h TP et 19 h PL.","s":11},{"q":"L'objectif général de l'UC est d'acquérir des compétences :","o":["Dans le domaine des sciences du mouvement, partie intégrante du modèle identitaire de la physiothérapie","En anatomie","En physiologie","En pathologie"],"r":0,"e":"Cette formulation situe l'UC au cœur de l'identité professionnelle.","s":11},{"q":"Parmi les compétences ciblées, le cours cite :","o":["Identifier les changements d'alignement postural chez l'utilisateur alité","La rédaction scientifique","Le diagnostic médical","La prescription"],"r":0,"e":"S'y ajoutent massage, mobilisation articulaire, palpation, mobilité précoce, positionnement, transferts, aides à la marche et toucher thérapeutique.","s":11},{"q":"Les cinq domaines thématiques de l'UC sont :","o":["Mobilisation tissulaire, mobilisation articulaire physiologique, anatomie palpatoire, PTAM et corps et conscience","Massage, anatomie, physiologie, pathologie et pratique","Théorie, pratique, laboratoire, stage et évaluation","Évaluation, intervention, prévention, éducation et recherche"],"r":0,"e":"Ils structurent à la fois le contenu et l'évaluation.","s":11},{"q":"Parmi les concepts fondamentaux du contenu programmatique figure :","o":["Les bases neurophysiologiques de la thérapie manuelle, selon le modèle physiologique","La biomécanique articulaire","L'anatomie descriptive","La physiologie de l'effort"],"r":0,"e":"La main comme moyen thérapeutique et l'importance du toucher en font également partie.","s":11},{"q":"L'objectif des modèles pédagogiques employés est :","o":["De rapprocher la théorie de la pratique clinique","D'accélérer l'apprentissage","De réduire les heures de cours","D'individualiser le parcours"],"r":0,"e":"Les cours pratiques reposent sur la dynamique de groupe, la démonstration et les simulations entre étudiants.","s":11},{"q":"Les pratiques réflexives des cours théoriques comprennent :","o":["L'analyse de documentation, les fiches de travail, la résolution de problèmes et les activités de recherche","Les seuls exposés","Les seuls travaux dirigés","Les seuls examens"],"r":0,"e":"Elles s'accompagnent de discussions étudiants-enseignant avec exemples pratiques.","s":11},{"q":"Le module évalué uniquement en pratique est :","o":["L'anatomie palpatoire","Le massage","La mobilisation articulaire","Le PTAM"],"r":0,"e":"Il pèse 25 %, comme le massage et la mobilisation articulaire, évalués en théorique et pratique.","s":11},{"q":"La pondération du module PTAM est de :","o":["15 %","25 %","10 %","30 %"],"r":0,"e":"Massage, anatomie palpatoire et mobilisation articulaire pèsent chacun 25 %.","s":11},{"q":"Parmi les contenus du module PTAM figurent :","o":["Positionnements dans le lit, mobilité précoce, transferts, aides à la marche, types de marche et transport en fauteuil roulant","Le seul positionnement","Les seuls transferts","Les seules aides à la marche"],"r":0,"e":"C'est le module le plus large en contenu, malgré une pondération de 15 %.","s":11},{"q":"Les techniques de massage citées au programme sont :","o":["Effleurage, pétrissage et friction","Effleurage et tapotement","Pétrissage et tapotement","Friction et vibration"],"r":0,"e":"L'examen du patient avant application en fait également partie.","s":11},{"q":"Le module Corps et conscience porte sur :","o":["Le concept du toucher, l'interprétation des différents types de toucher et le toucher comme facilitateur de la relation thérapeutique","La palpation","La mobilisation","Le positionnement"],"r":0,"e":"C'est le cinquième domaine thématique de l'UC.","s":11},{"q":"Le module d'anatomie palpatoire porte sur :","o":["L'anatomie topographique, l'apprentissage de la palpation et l'identification des structures anatomiques","La mobilisation articulaire","Le massage","Les transferts"],"r":0,"e":"Il est évalué uniquement en pratique.","s":11},{"q":"L'UC EAIF I se déroule :","o":["En 1ʳᵉ année, 1ᵉʳ semestre, en régime obligatoire et semestriel","En 1ʳᵉ année, 2ᵉ semestre","En 2ᵉ année","En option"],"r":0,"e":"Elle vaut 8 ECTS dans le cycle de licence en physiothérapie.","s":11},{"q":"Enseignante B assure :","o":["15 heures, réparties en 8 h TP et 7 h PL","20 heures","25 heures","10 heures"],"r":0,"e":"Elle est professeure coordinatrice, docteure et spécialiste au titre du DL 206/2009.","s":11},{"q":"Le contenu sur la mobilisation articulaire physiologique porte sur :","o":["Les techniques de mobilisation des articulations périphériques","Les mobilisations vertébrales","Les manipulations","Les tractions"],"r":0,"e":"Effets physiologiques, indications, précautions et contre-indications sont traités dans les concepts fondamentaux.","s":11},{"q":"Les cours pratiques de l'UC reposent notamment sur :","o":["Des simulations entre étudiants, mettant en œuvre les techniques","Des exposés magistraux","Des stages cliniques","Des travaux écrits"],"r":0,"e":"La dynamique de groupe et les moments de démonstration les complètent.","s":11},{"q":"Quel est l'objectif PRINCIPAL des positionnements en kinésithérapie ?","o":["Renforcer la musculature","Prévenir les altérations cutanées, articulaires, circulatoires et respiratoires","Stimuler la croissance osseuse","Améliorer la digestion"],"r":1,"e":"Les positionnements visent essentiellement la PRÉVENTION des altérations musculo-squelettiques, circulatoires, respiratoires et cutanées.","s":12},{"q":"À quelle fréquence faut-il changer la position d'un patient alité pour prévenir les escarres ?","o":["Toutes les heures","Toutes les 2 heures","Toutes les 4 heures","Toutes les 6 heures"],"r":1,"e":"La règle est un changement de position TOUTES LES 2 HEURES, ce qui correspond à la durée de pression prolongée (2-3h) qui provoque les lésions.","s":12},{"q":"Une escarre de stade III se caractérise par :","o":["Un érythème non blanchissable sur peau intacte","Une destruction partielle de la peau (épiderme/derme)","Une destruction totale de la peau avec nécrose du tissu sous-cutané, formation d'un cratère","Une atteinte musculaire et osseuse"],"r":2,"e":"Stade III = destruction TOTALE de la peau avec nécrose sous-cutanée et formation de cratère. Le stade IV ajoute l'atteinte musculaire/osseuse.","s":12},{"q":"Quelle zone N'EST PAS typiquement à risque d'escarre en décubitus dorsal ?","o":["Sacrum","Calcanéum","Tubérosité ischiatique","Olécrane"],"r":2,"e":"La tubérosité ischiatique est une zone à risque en position ASSISE, pas en décubitus dorsal.","s":12},{"q":"En décubitus latéral, les membres inférieurs doivent être :","o":["En extension complète","Fléchis, avec un coussin entre les genoux","Croisés","Suspendus"],"r":1,"e":"Les MI sont en flexion, avec un coussin entre les genoux pour créer un plan horizontal et éviter les frottements.","s":12},{"q":"Le décubitus ventral est :","o":["La position de référence pour tous les patients alités","Généralement bien toléré","Une position d'exception, généralement mal tolérée","Utilisée pour les transferts"],"r":2,"e":"Le décubitus ventral est une position d'EXCEPTION utilisée dans des situations spécifiques (chirurgie, insuffisance respiratoire grave) et généralement mal tolérée.","s":12},{"q":"En décubitus dorsal, le membre supérieur du patient totalement dépendant doit être placé :","o":["Le long du corps en rotation interne","En légère abduction et rotation externe","Au-dessus de la tête","Croisé sur la poitrine"],"r":1,"e":"Le MS est placé en LÉGÈRE ABDUCTION et ROTATION EXTERNE pour respecter l'alignement physiologique.","s":12},{"q":"Combien de temps de pression continue suffit pour provoquer une escarre ?","o":["30 minutes","1 heure","2 à 3 heures","12 heures"],"r":2,"e":"Une pression prolongée de 2 à 3 HEURES suffit à créer une lésion par défaut d'irrigation.","s":12},{"q":"Quel principe FONDAMENTAL régit la mobilité précoce ?","o":["Aller le plus vite possible","Ne pas traîner le patient et ne pas tirer sur les articulations","Toujours utiliser la force maximale","Ignorer les capacités du patient"],"r":1,"e":"Principes-clés : NE PAS TRAÎNER, NE PAS TIRER sur les articulations, éviter les amplitudes extrêmes, favoriser l'alignement.","s":12},{"q":"Lors du roulement avec assistance, où sont placées les mains du kinésithérapeute ?","o":["Aux pieds et à la tête","Sur la ceinture scapulaire et la ceinture pelvienne","Sur les genoux","Aux poignets"],"r":1,"e":"Une main soutient la CEINTURE SCAPULAIRE, l'autre la CEINTURE PELVIENNE pour effectuer le roulement EN BLOC.","s":12},{"q":"Quelle est une cause typique d'escarre ?","o":["Exercice physique intense","Stress mécanique sur les zones osseuses saillantes","Bonne hydratation","Massage régulier"],"r":1,"e":"Les escarres résultent du stress mécanique sur les zones osseuses saillantes lors d'une pression prolongée.","s":12},{"q":"Le stade I d'une escarre se caractérise par :","o":["Une nécrose musculaire","Un cratère profond","Un érythème non blanchissable sur peau intacte","Une perte totale de la peau"],"r":2,"e":"Stade I = érythème NON BLANCHISSABLE sur peau encore INTACTE, premier signe d'alerte.","s":12},{"q":"En décubitus latéral du patient totalement dépendant, la main du côté inférieur doit être :","o":["Suspendue dans le vide","Sous la fesse","Appuyée sur l'oreiller de la tête","Croisée sur la poitrine"],"r":2,"e":"La main inférieure latérale est appuyée sur l'oreiller de la tête, l'épaule étant légèrement avancée.","s":12},{"q":"Parmi ces facteurs de risque d'escarre, lequel est CHRONIQUE ?","o":["Mouvement excessif","Diabète","Activité sportive","Bonne nutrition"],"r":1,"e":"Le diabète est une affection chronique compromettant l'irrigation vasculaire ET la sensibilité, double facteur de risque.","s":12},{"q":"L'option 1 du décubitus latéral côté affecté place le coude en :","o":["Extension","Flexion","Rotation interne","Pronation"],"r":1,"e":"Option 1 = coude en FLEXION. Option 2 = coude en EXTENSION.","s":12},{"q":"Quel matériel est utilisé en prévention des escarres ?","o":["Lit articulé et matériel anti-escarres","Bandage compressif","Attelle plâtrée","Ceinture lombaire"],"r":0,"e":"Les lits articulés et le matériel anti-escarres (matelas, coussins spéciaux) font partie des mesures préventives.","s":12},{"q":"La mobilité précoce vise à promouvoir :","o":["La dépendance complète","L'image corporelle et l'autonomie","L'immobilisation prolongée","L'utilisation exclusive de machines"],"r":1,"e":"Mobilité précoce = développement de l'image corporelle, schémas moteurs normaux, autonomie et indépendance.","s":12},{"q":"En décubitus ventral, quelle zone est typiquement à risque de pression ?","o":["Sacrum","Tubérosité ischiatique","Rotule","Olécrane"],"r":2,"e":"Zones à risque en décubitus ventral : visage/oreille/front, épaule, épine iliaque, ROTULE.","s":12},{"q":"Pourquoi éviter le poids des vêtements au niveau tibio-tarsien en décubitus dorsal ?","o":["Pour la mode","Pour éviter une flexion plantaire forcée et préserver la position neutre","Pour faciliter le transfert","Pour le laver"],"r":1,"e":"Le poids des draps/vêtements peut forcer une flexion plantaire (pied tombant). Il faut préserver une position neutre, talons non appuyés.","s":12},{"q":"Un patient en fauteuil roulant prolongé est principalement à risque d'escarre :","o":["Au front","À l'épaule","À la tubérosité ischiatique et région sacrée","Aux orteils"],"r":2,"e":"Position assise prolongée = zones à risque : tubérosité ischiatique, région sacrée, région poplitée, métatarses.","s":12},{"q":"L'autocontrôle au miroir est utile pour :","o":["Se coiffer","Inspecter visuellement les zones de pression difficiles à voir","Vérifier sa posture","Se maquiller"],"r":1,"e":"Le miroir permet à un patient autonome (paraplégique p.ex.) d'INSPECTER les zones de pression non visibles directement.","s":12},{"q":"Lors d'un transfert ou d'une mobilité précoce, il faut TOUJOURS :","o":["Forcer le mouvement","Attendre la réponse motrice du patient","Le faire seul","Aller vite"],"r":1,"e":"L'aide dépend des capacités du patient — il faut TOUJOURS attendre sa réponse motrice avant d'agir.","s":12},{"q":"Quelle structure cutanée est principalement touchée au stade II d'une escarre ?","o":["Le muscle","L'os","L'épiderme et/ou le derme","Le périoste"],"r":2,"e":"Stade II = destruction partielle, atteinte de l'ÉPIDERME et/ou du DERME (plaie, peau rouge œdémateuse douloureuse).","s":12},{"q":"Combien d'options de positionnement existe-t-il pour le décubitus latéral du côté affecté ?","o":["1","2","3","4"],"r":2,"e":"Il existe 3 OPTIONS (variantes) pour le décubitus latéral du côté affecté selon la position du coude et des MS.","s":12},{"q":"L'incontinence urinaire/fécale est un facteur de risque d'escarre parce que :","o":["Elle augmente la mobilité","Le contact avec l'urine et les selles irrite et macère la peau","Elle améliore la circulation","Elle réduit la friction"],"r":1,"e":"L'urine et les selles macèrent la peau et l'irritent, fragilisant la barrière cutanée et favorisant les escarres.","s":12},{"q":"Le stade 1 d'escarre se caractérise par :","o":["Une plaie profonde","Un érythème qui ne blanchit pas à la pression","Une nécrose","Un os exposé"],"r":1,"e":"Stade 1 : érythème non blanchissant à la pression, peau intacte. Premier signal d'alerte.","s":12},{"q":"Les zones les plus à risque d'escarre en décubitus dorsal sont :","o":["Coudes seulement","Talons, sacrum, occiput, omoplates","Genoux","Mains"],"r":1,"e":"DD : talons (++), sacrum, occiput, omoplates, coudes — zones de pression osseuses.","s":12},{"q":"En semi-Fowler, l'inclinaison du tronc est généralement :","o":["10°","45° à 60°","90° (assis)","-30°"],"r":1,"e":"Semi-Fowler ≈ 45-60° → travail respiratoire, alimentation, observation, mais ↑ pression sacrée.","s":12},{"q":"La fréquence recommandée de changement de position au lit est :","o":["1 fois/jour","Toutes les 2 à 3 heures","Toutes les 30 min","Jamais"],"r":1,"e":"Changement toutes les 2-3 h → prévention escarres (réduit la pression continue sur les mêmes zones).","s":12},{"q":"Pour prévenir l'équin chez un patient alité, on installe :","o":["Un poids sur les pieds","Une cale-pieds maintenant la cheville à 90°","Les pieds en flexion plantaire libre","Rien"],"r":1,"e":"Cale-pieds ou attelle pour maintenir la cheville à 90° → évite la rétraction du triceps sural (pied tombant).","s":12},{"q":"Parmi les objectifs fonctionnels des positionnements, le cours cite :","o":["Donner une notion du corps dans son ensemble","Prévenir les altérations cutanées","Prévenir les modifications circulatoires","Prévenir les altérations respiratoires"],"r":0,"e":"Les objectifs préventifs concernent l'amplitude articulaire, la circulation, la respiration et la peau.","s":12},{"q":"Les positionnements de base :","o":["Peuvent subir des modifications et adaptations selon les besoins individuels","Sont figés","Sont universels","Ne dépendent pas du patient"],"r":0,"e":"Ils doivent s'adapter à la progression du patient.","s":12},{"q":"Parmi les facteurs de risque d'escarre liés à une mauvaise irrigation, le cours cite :","o":["Le diabète et les maladies vasculaires","L'incontinence","Les affections mentales","L'âge seul"],"r":0,"e":"Les troubles sensitifs du diabète, de l'AVC et des neuropathies périphériques constituent un autre facteur.","s":12},{"q":"L'incontinence urinaire et fécale est un facteur de risque d'escarre car :","o":["Elle expose la peau au contact de fluides irritants","Elle réduit la mobilité","Elle altère la nutrition","Elle diminue la sensibilité"],"r":0,"e":"Le contact avec sueur, sang, urine et selles figure parmi les causes d'escarre.","s":12},{"q":"Le mécanisme de l'escarre associe :","o":["Contact, pression et frottement, par manque d'irrigation sanguine ou irritation cutanée","La seule pression","Le seul frottement","La seule irritation"],"r":0,"e":"Une pression prolongée de 2 à 3 heures sur les zones osseuses saillantes suffit.","s":12},{"q":"Le frottement à l'origine des escarres provient notamment :","o":["Des plis dans les vêtements et les draps","Des coussins","Du matelas","Des mobilisations"],"r":0,"e":"C'est pourquoi les soins vestimentaires font partie des mesures de prévention.","s":12},{"q":"Le stade II d'escarre se caractérise par :","o":["Une destruction partielle de l'épiderme et/ou du derme, avec plaie, peau rouge, œdémateuse et douloureuse","Un érythème non blanchissable","Un cratère avec nécrose sous-cutanée","Une lésion musculaire ou osseuse"],"r":0,"e":"Le stade III forme un cratère susceptible d'infection et le stade IV atteint muscles, os ou structures de soutien.","s":12},{"q":"Parmi les affections chroniques favorisant les escarres par troubles sensitifs, le cours cite :","o":["Le diabète, l'AVC et la neuropathie périphérique","L'arthrose","L'insuffisance cardiaque","L'asthme"],"r":0,"e":"L'incapacité à mobiliser ses segments, comme dans la paraplégie ou la sclérose en plaques, constitue un autre facteur.","s":12},{"q":"Parmi les objectifs des positionnements, le cours cite la stimulation :","o":["Sensorielle et proprioceptive","Motrice","Cognitive","Circulatoire seule"],"r":0,"e":"S'y ajoutent le confort, la fonction et la notion du corps dans son ensemble.","s":12},{"q":"L'autocontrôle dans la prévention des escarres se fait :","o":["À l'aide d'un miroir","Par palpation","Par photographie","Par un soignant"],"r":0,"e":"Il figure parmi les huit mesures de prévention, avec les changements toutes les 2 heures.","s":12},{"q":"En décubitus dorsal, les membres supérieurs sont placés :","o":["Sur coussin, en légère abduction et rotation externe","En adduction","En rotation interne","Sans coussin"],"r":0,"e":"Les membres inférieurs sont légèrement abductés et le tibio-tarsien en position neutre, talons non appuyés.","s":12},{"q":"Chez un patient partiellement dépendant en décubitus dorsal, les procédures sont :","o":["Similaires, avec une attention particulière à la symétrie et à l'alignement","Radicalement différentes","Sans coussin","Limitées au tronc"],"r":0,"e":"L'alignement tête-tronc-membres et la protection des protubérances osseuses restent la base.","s":12},{"q":"Parmi les signes d'escarre, le cours cite :","o":["Une rougeur qui s'aggrave, puis la formation d'ulcères, de plaies et de cratères","Un prurit","Une desquamation","Une pâleur"],"r":0,"e":"Les endroits les plus courants sont le sacrum, le calcanéum, le coude et le grand trochanter.","s":12},{"q":"L'éducation dans les objectifs fonctionnels concerne :","o":["Les patients et les soignants","Les seuls patients","Les seuls soignants","La seule famille"],"r":0,"e":"Elle s'inscrit dans la mission de prévention du kinésithérapeute face aux effets de l'alitement.","s":12},{"q":"L'escarre se définit comme :","o":["Une zone localisée de mort cellulaire cutanée et tissulaire, le tissu étant comprimé entre une protubérance osseuse et une surface dure","Une infection cutanée","Une brûlure","Une dermatose"],"r":0,"e":"La durée de compression est un élément constitutif de la définition.","s":12},{"q":"Parmi le matériel de prévention des escarres, le cours cite :","o":["Les lits articulés et le matériel anti-escarres","Les seuls coussins","Les seuls matelas","Les orthèses"],"r":0,"e":"Alimentation et hygiène adéquates complètent le dispositif.","s":12},{"q":"Les objectifs préventifs du positionnement concernent le système musculo-squelettique par :","o":["La prévention des modifications de l'amplitude articulaire","Le renforcement","L'étirement","La stabilisation"],"r":0,"e":"Trois autres systèmes sont visés : circulatoire, respiratoire et cutané.","s":12},{"q":"Parmi les objectifs fonctionnels, le cours cite :","o":["Permettre une mobilisation adéquate dans différentes positions","La seule verticalisation","Le seul confort","La seule éducation"],"r":0,"e":"Faciliter le lever précoce, l'indépendance fonctionnelle et le mouvement normal complètent ces objectifs.","s":12},{"q":"La mission générale du kinésithérapeute dans ce cours est :","o":["Une mission de prévention des altérations liées à l'alitement","Une mission curative","Une mission d'évaluation","Une mission d'éducation seule"],"r":0,"e":"Elle se décline en objectifs préventifs et fonctionnels.","s":12},{"q":"Les zones de pression en décubitus dorsal comprennent :","o":["Nuque, apophyses épineuses, épine de l'omoplate, olécrane, sacrum, zone fessière et calcanéum","Oreille et trochanter","Front et rotule","Ischions et métatarses"],"r":0,"e":"Chaque position a ses zones propres, à connaître pour adapter la protection.","s":12},{"q":"Quelle région de la colonne vertébrale est la plus exposée aux lésions lors des transferts ?","o":["Cervicale","Dorsale","Lombaire","Sacrée"],"r":2,"e":"Colonne lombaire = +++ (très élevé). Cervicale = ++, épaules = +.","s":13},{"q":"Le noyau pulpeux du disque intervertébral contient :","o":["50% d'eau","70% d'eau","88% d'eau","100% d'eau"],"r":2,"e":"Le noyau pulpeux est une substance GÉLATINEUSE contenant 88% d'H2O.","s":13},{"q":"Quelle charge maximale un disque intervertébral peut-il supporter ?","o":["200 kg","400 kg","600 kg","1000 kg"],"r":2,"e":"Le disque peut supporter une force allant jusqu'à 600 kg.","s":13},{"q":"La charge sur L3/L4 en position neutre est d'environ :","o":["50 kg","86 kg","150 kg","300 kg"],"r":1,"e":"Position neutre : 86 kg sur L3/L4 (par le seul poids du corps).","s":13},{"q":"Soulever 20 kg avec le TRONC FLÉCHI et JAMBES TENDUES génère sur L3/L4 une charge de :","o":["86 kg","140 kg","210 kg","327 kg"],"r":3,"e":"327 kg — c'est la pire technique. Avec les jambes FLÉCHIES, on tombe à 210 kg.","s":13},{"q":"Quel est le bon principe biomécanique pour soulever une charge ?","o":["Tronc en flexion, jambes tendues","Tronc droit, jambes fléchies","Bras tendus à la verticale","Position assise"],"r":1,"e":"Garder le TRONC DROIT et fléchir les JAMBES (utiliser la force des MI) réduit considérablement la charge lombaire.","s":13},{"q":"Quelle commande verbale est recommandée lors d'un transfert en équipe ?","o":["Plusieurs commandes simultanées","Une seule commande : '1, 2, 3...'","Chaque transporteur compte pour lui","Aucune commande"],"r":1,"e":"Une SEULE commande, claire, par le chef d'équipe : '1, 2, 3...' pour synchroniser le mouvement.","s":13},{"q":"Concernant les contacts manuels, lequel est CORRECT ?","o":["Soutenir par le dessus","Exercer une pression avec les doigts","Main en forme de coupe épousant le segment","Mains moites"],"r":2,"e":"Main en COUPE pour épouser le segment ; jamais par le dessus, pas de pression des doigts, éviter les mains moites.","s":13},{"q":"Le transfert australienne se fait avec :","o":["1 transporteur","2 transporteurs face au trajet","3 transporteurs","4 transporteurs"],"r":1,"e":"Australienne = 2 transporteurs FACE AU TRAJET, sensiblement de même taille.","s":13},{"q":"Combien de transporteurs sont nécessaires pour un patient en GRANDE dépendance ?","o":["1","2","3 ou 4","Aucun"],"r":2,"e":"3/4 transporteurs sont utilisés pour les patients en grande dépendance (ex: lésion vertébro-médullaire).","s":13},{"q":"Quel facilitateur peut être utilisé lors d'un transfert à 1 transporteur ?","o":["Ceinture ou planche de transfert","Marteau","Béquilles","Aucun"],"r":0,"e":"Ceinture de transfert et planche de transfert (slide board) facilitent les transferts à 1 transporteur.","s":13},{"q":"Avant un transfert, il faut TOUJOURS :","o":["Démarrer sans prévenir","Vérifier les freins du fauteuil et les fixations","Forcer le patient","Faire vite"],"r":1,"e":"Vérifier stabilité ET fixations : FREINS, pieds, roues. Sécurité avant tout.","s":13},{"q":"L'objectif d'informer le patient avant le transfert est :","o":["Lui faire peur","Réduire l'anxiété et améliorer la coordination","Le distraire","Rien"],"r":1,"e":"Informer = améliore la COORDINATION, RÉDUIT L'ANXIÉTÉ/peur, augmente la synchronisation.","s":13},{"q":"Qui dirige la manœuvre lors d'un transfert d'équipe ?","o":["Le patient","Le chef d'équipe","Le médecin","Personne en particulier"],"r":1,"e":"Le CHEF D'ÉQUIPE dirige la manœuvre — tous doivent connaître la stratégie.","s":13},{"q":"Concernant la POSITION du transporteur, quel élément est crucial ?","o":["Être loin de la charge","Être proche, base d'appui large, leviers courts","Bras tendus","Pieds joints"],"r":1,"e":"Être proche de la charge (leviers courts), base d'appui large, MI semi-fléchis pour utiliser leur force.","s":13},{"q":"Un transfert australienne PEUT être utilisé pour :","o":["Uniquement les courtes distances","Patients comateux","Longues distances, escaliers, ajustement dans le lit","Patients en coma"],"r":2,"e":"Australienne : longues distances, escaliers, ajustement dans le lit, passage au sol.","s":13},{"q":"Quel est l'ordre correct des phases d'un transfert ?","o":["Action → Évaluation","Évaluation → Stratégie → Minimisation des risques → Exécution","Exécution directe","Information → Action"],"r":1,"e":"Évaluation du patient → choix du transfert → préparation/minimisation des risques → exécution avec communication.","s":13},{"q":"Le rôle PRINCIPAL du kinésithérapeute lors d'un transfert est :","o":["Exécuter seul","Évaluer, choisir, informer, exécuter et former l'entourage","Donner les médicaments","Conduire le fauteuil"],"r":1,"e":"Évaluer le degré fonctionnel, choisir le transfert, informer, exécuter correctement et FORMER les professionnels/proches.","s":13},{"q":"Le patient est-il capable de saisir, tirer ou pousser avec ses mains ? Cette question relève :","o":["Des erreurs","Des facteurs à prendre en compte","Du matériel","De l'épidémiologie"],"r":1,"e":"Évaluer les capacités MOTRICES du patient (saisir, tirer, pousser) fait partie des facteurs à analyser.","s":13},{"q":"Une mauvaise évaluation du POIDS du patient est :","o":["Sans conséquence","Une erreur classique qui compromet le transfert","Une stratégie","Un facilitateur"],"r":1,"e":"C'est une des erreurs les plus communes ; mène à un nombre insuffisant de transporteurs et risque de blessure.","s":13},{"q":"Le transfert avec PLANCHE de transfert s'utilise pour :","o":["Patient totalement dépendant","Patient partiellement dépendant pouvant participer","Patient comateux","Tous les patients"],"r":1,"e":"La planche aide à glisser le patient partiellement dépendant entre 2 surfaces de même niveau (lit-FR).","s":13},{"q":"Pour un transfert lit-fauteuil avec 1 transporteur, le fauteuil doit être :","o":["Loin du lit","À 45° du lit, freiné, accoudoir et pédale retirés du côté transfert","Devant le lit","Sur les roues libres"],"r":1,"e":"Fauteuil à ~45° du lit, FREINÉ, accoudoir et pédale du côté transfert retirés/relevés.","s":13},{"q":"Combien d'aides faut-il pour monter un escalier avec un fauteuil roulant ?","o":["1 aide seulement","Toujours 4","2 ou 3 aides","Aucune"],"r":2,"e":"2 ou 3 aides : la 1ère contrôle aux poignées (DOS aux escaliers), les autres tirent les grandes roues marche par marche.","s":13},{"q":"Lors d'un transfert, le poids doit être :","o":["Réparti équitablement entre les transporteurs","Porté par une seule personne","Maintenu très longtemps","Loin du corps"],"r":0,"e":"Répartition ÉQUITABLE du poids entre tous les éléments impliqués (transporteurs ET patient si possible).","s":13},{"q":"Quel élément du fauteuil roulant doit TOUJOURS être bloqué avant transfert ?","o":["Les poignées","Les freins","Le dossier","Les jantes"],"r":1,"e":"Vérifier les FREINS = priorité de sécurité ; aussi pieds et roues stables.","s":13},{"q":"Lors d'un transfert, la règle ergonomique principale est :","o":["Pencher le dos en avant","Garder le dos droit, fléchir les genoux, rapprocher la charge","Soulever d'une main","Tourner le tronc en torsion"],"r":1,"e":"Dos neutre, genoux fléchis (force des MI), charge près du corps, pas de rotation rachis sous charge.","s":13},{"q":"Avant un transfert, on doit toujours :","o":["Tirer brutalement","Évaluer le patient (équilibre, force, douleur, compréhension) + sécuriser l'environnement","Pousser","Le faire sans le prévenir"],"r":1,"e":"Sécurité = bilan rapide + briefing du patient + dégagement des obstacles + frein FR + sol sec.","s":13},{"q":"Le transfert australien est utilisé pour :","o":["Un patient autonome","Transférer un patient couché entre 2 lits/brancards à plat","Un patient debout","La marche"],"r":1,"e":"Transfert australien (drap glissé) = patient couché entre 2 surfaces de même hauteur, plusieurs aidants.","s":13},{"q":"Le \"transfert siège\" (chaise) implique :","o":["Patient marchant seul","Patient assis qu'on déplace en bloc d'un siège à un autre","Patient debout","Patient pendu"],"r":1,"e":"Patient assis + 2 aidants (devant/derrière) = bloc soulevé puis transféré.","s":13},{"q":"Le verbe \"Prêt? Un, deux, trois...\" est essentiel car :","o":["C'est pour le moral","La synchronisation entre aidants évite les blessures et garantit la sécurité du patient","Aucune raison","C'est obligatoire légalement"],"r":1,"e":"Synchronisation = sécurité : tous les aidants soulèvent en même temps, évite déséquilibre et lésions dorsales.","s":13},{"q":"Le transfert se définit comme la mobilisation d'un patient d'un point A à un point B, qui doit :","o":["Être effectuée en sécurité, en permettant un bon alignement du corps du patient et des transporteurs","Être rapide avant tout","Être réalisée par une seule personne","Éviter tout contact"],"r":0,"e":"Le poids doit être équitablement réparti entre tous les éléments impliqués.","s":13},{"q":"L'information préalable lors d'un transfert doit être donnée :","o":["Au patient ET à l'équipe, tous devant être conscients du processus","Au seul patient","À la seule équipe","Au seul chef d'équipe"],"r":0,"e":"Elle améliore la coordination, réduit l'anxiété et augmente la synchronisation.","s":13},{"q":"Le risque de lésion lors des transferts est le plus élevé :","o":["À la colonne lombaire","À la colonne cervicale","Aux épaules","Aux genoux"],"r":0,"e":"La cervicale présente un risque élevé et les épaules un risque modéré.","s":13},{"q":"Le noyau pulpeux contient :","o":["88 % d'eau, sous forme d'une substance gélatineuse","50 % d'eau","65 % d'eau","30 % d'eau"],"r":0,"e":"Sa forme est approximativement sphérique, comme une petite bille intercalée entre deux plans.","s":13},{"q":"La capacité de charge d'un disque intervertébral atteint :","o":["600 kg","300 kg","150 kg","1 000 kg"],"r":0,"e":"Chaque disque n'a qu'une petite amplitude, mais la somme des micro-mouvements permet une grande amplitude globale.","s":13},{"q":"En position neutre, la charge sur L3/L4 est de :","o":["86 kg","114 kg","140 kg","210 kg"],"r":0,"e":"Elle atteint 114 kg en flexion de 20° comme en rotation de 45°.","s":13},{"q":"Porter 20 kg en flexion du tronc avec les jambes tendues induit une charge sur L3/L4 de :","o":["327 kg","210 kg","140 kg","122 kg"],"r":0,"e":"Avec les jambes fléchies, la charge tombe à 210 kg : fléchir les jambes divise la charge par environ 1,5.","s":13},{"q":"Porter 20 kg répartis plutôt qu'en charge unique fait passer la charge lombaire de :","o":["140 kg à 122 kg","210 kg à 140 kg","327 kg à 210 kg","114 kg à 86 kg"],"r":0,"e":"La répartition de la charge est donc un levier de prévention à part entière.","s":13},{"q":"L'évaluation du patient avant transfert porte notamment sur :","o":["Le caractère spastique ou flasque de la pathologie","Le seul poids","La seule taille","Le seul âge"],"r":0,"e":"S'y ajoutent le degré de dépendance et les conditions actuelles, alité ou positionné.","s":13},{"q":"La position du transporteur prend en compte :","o":["Le centre de gravité, la base d'appui, des leviers les plus courts possibles, la position des membres et des pieds, et la force","La seule force","La seule taille","Le seul équilibre"],"r":0,"e":"C'est le point E des procédures de transfert.","s":13},{"q":"Concernant les contacts manuels, les doigts :","o":["Ne doivent pas exercer de pression sur le segment","Doivent serrer fermement","Doivent s'enfoncer","Doivent rester écartés"],"r":0,"e":"La main se place en coupe pour épouser le segment, et les mains ne soutiennent jamais par le dessus.","s":13},{"q":"Les commandes lors d'un transfert doivent être :","o":["Uniques et explicites, avec un décompte du type « 1, 2, 3 »","Multiples","Implicites","Silencieuses"],"r":0,"e":"Le chef d'équipe dirige la manœuvre et tous connaissent la stratégie.","s":13},{"q":"Parmi les facteurs à prendre en compte avant un transfert, le cours cite :","o":["Les limitations cognitives, linguistiques, auditives et visuelles","Le seul état de conscience","La seule douleur","Le seul matériel"],"r":0,"e":"S'y ajoutent la capacité à coopérer, le matériel sensible, les modifications du tonus, la capacité à saisir, l'absence de douleur et l'intégrité cutanée.","s":13},{"q":"La vérification de l'équipement avant transfert porte sur :","o":["La stabilité et les fixations : freins, pieds et roues","Le seul freinage","La seule hauteur","Le seul emplacement"],"r":0,"e":"Il faut aussi préparer l'espace et vérifier la hauteur des surfaces.","s":13},{"q":"L'attitude du transporteur doit transmettre :","o":["Sécurité et confiance","Neutralité","Distance","Autorité"],"r":0,"e":"L'historique des transferts précédents aide à adapter cette communication.","s":13},{"q":"Les courbures physiologiques de la colonne observées en vue latérale sont :","o":["Lordose cervicale, cyphose dorsale, lordose lombaire et cyphose sacrée","Deux lordoses seulement","Deux cyphoses seulement","Une seule courbure"],"r":0,"e":"La colonne s'observe en vue postérieure et en vue latérale.","s":13},{"q":"La leçon-clé de la biomécanique des transferts est :","o":["Toujours utiliser la force des membres inférieurs, en fléchissant les jambes plutôt que le tronc","D'utiliser la force du dos","De porter au plus près","De travailler seul"],"r":0,"e":"Cela divise la charge lombaire par environ 1,5.","s":13},{"q":"La sélection du transfert porte sur :","o":["Le type de transfert, le nombre de transporteurs, l'évaluation du site et l'itinéraire","Le seul nombre de transporteurs","Le seul itinéraire","Le seul matériel"],"r":0,"e":"Elle suit l'évaluation du patient dans les procédures de transfert.","s":13},{"q":"Il faut éviter les mains moites lors des contacts manuels car :","o":["Elles compromettent la qualité du contact et le confort","Elles sont sales","Elles glissent sur les vêtements","Elles refroidissent le patient"],"r":0,"e":"Le tronc doit par ailleurs être bien soutenu et stabilisé.","s":13},{"q":"L'emplacement de l'équipement doit assurer un trajet :","o":["Court, facile, sûr et fonctionnel","Le plus court possible uniquement","Le plus direct","Sans obstacle uniquement"],"r":0,"e":"Cela concerne la position du matelas, de la chaise et du fauteuil roulant.","s":13},{"q":"Quelle aide à la marche offre la plus grande base d'appui ?","o":["Canne","Béquille canadienne","Déambulateur","Béquille axillaire"],"r":2,"e":"Le DÉAMBULATEUR offre la plus grande base d'appui quadrangulaire.","s":14},{"q":"Pour régler une aide à la marche, la poignée doit être au niveau de :","o":["L'épaule","Le coude en extension","Le grand trochanter","Le genou"],"r":2,"e":"Poignée AU NIVEAU DU GRAND TROCHANTER pour permettre ~25° de flexion du coude.","s":14},{"q":"L'angle correct de flexion du coude avec une aide à la marche est :","o":["0° (coude tendu)","Environ 25°","45°","90°"],"r":1,"e":"Légère flexion d'environ 25° pour absorber les chocs et propulser efficacement.","s":14},{"q":"Une canne unilatérale doit être placée du côté :","o":["Du membre blessé","Du membre sain (opposé à la dysfonction)","Indifférent","Toujours à droite"],"r":1,"e":"TOUJOURS du côté CONTROLATÉRAL à la dysfonction → réduit ~60% la charge sur la hanche atteinte.","s":14},{"q":"La sangle d'avant-bras d'une béquille canadienne se place à :","o":["Au poignet","5 cm sous le coude","À l'épaule","Au milieu de l'avant-bras"],"r":1,"e":"Sangle à 5 cm SOUS le coude pour bonne maîtrise sans gêne.","s":14},{"q":"Pour une béquille axillaire, le support thoracique doit :","o":["Toucher l'aisselle pour bien tenir","Être 10 cm SOUS l'aisselle, contre la cage thoracique","Être contre l'épaule","Être au coude"],"r":1,"e":"Le support doit être ~10 cm sous l'aisselle pour ÉVITER la compression des structures axillaires (nerf, vaisseaux).","s":14},{"q":"L'embout d'une béquille doit être placé :","o":["Sous le pied","Derrière le pied","10/15 cm devant et à l'extérieur des pointes des pieds","Loin du corps"],"r":2,"e":"Embout 10/15 cm DEVANT et à L'EXTÉRIEUR des pointes des pieds = base d'appui optimale.","s":14},{"q":"Quel type de marche s'utilise quand l'appui sur le MI blessé est INTERDIT ?","o":["4 points","3 points","3 points modifiée","2 points"],"r":1,"e":"Marche à 3 POINTS : le MI blessé ne touche PAS le sol (charge nulle).","s":14},{"q":"La marche à 3 points modifiée diffère de la marche à 3 points par :","o":["Le nombre d'aides","Une charge PARTIELLE est autorisée sur le MI blessé","L'utilisation d'un fauteuil","La présence d'un assistant"],"r":1,"e":"3 points modifiée = appui PARTIEL autorisé sur le MI blessé (avance simultanée aides + MI blessé).","s":14},{"q":"Pour monter des escaliers avec béquilles, on commence par :","o":["Le MI blessé en premier","Le MI sain en premier","Les béquilles en premier","Sauter"],"r":1,"e":"MONTÉE : le MI SAIN monte en premier (le bon monte au paradis), puis aides + MI blessé.","s":14},{"q":"Pour descendre des escaliers avec béquilles :","o":["Le MI sain descend en premier","Les aides + MI BLESSÉ descendent en premier","On saute","Aucune règle"],"r":1,"e":"DESCENTE : aides + MI BLESSÉ descendent en premier (le mauvais descend en enfer), puis MI sain.","s":14},{"q":"La marche pendulaire s'effectue avec :","o":["1 canne","1 déambulateur","2 béquilles canadiennes + orthèses MI","Aucune aide"],"r":2,"e":"Marche pendulaire : 2 béquilles canadiennes + orthèses MI, MS forts requis (population LMS).","s":14},{"q":"Différence entre marche semi-pendulaire et pendulaire :","o":["Aucune","Semi-pendulaire = MI atteignent la ligne des aides ; Pendulaire = MI dépassent la ligne des aides","Vitesse uniquement","Nombre de béquilles"],"r":1,"e":"Semi-pendulaire (swing-to) : MI jusqu'à la ligne. Pendulaire (swing-through) : MI AU-DELÀ de la ligne.","s":14},{"q":"Le standing-frame a pour bénéfice :","o":["Aucun effet osseux","Augmente la spasticité","Limite la perte de densité osseuse, diminue la spasticité","Empêche la verticalisation"],"r":2,"e":"Standing-frame : limite la diminution de densité osseuse, diminue la spasticité, évite les altérations articulaires.","s":14},{"q":"Une orthèse genou-tibia-pied stabilise :","o":["La hanche en flexion","Le genou en extension + cheville en légère flexion dorsale 5-10°","Le tronc","L'épaule"],"r":1,"e":"KAFO : genou EN EXTENSION + cheville en légère flexion dorsale (5-10°).","s":14},{"q":"Diamètre des grandes roues du fauteuil roulant :","o":["20 cm","40 cm","61 cm","100 cm"],"r":2,"e":"Grandes roues : 61 cm de diamètre. Roues libres (avant) : ~20 cm.","s":14},{"q":"Un patient TÉTRAPLÉGIQUE a besoin d'un dossier :","o":["Bas pour liberté de mouvement","Haut pour meilleur soutien du tronc","Indifférent","Inexistant"],"r":1,"e":"Tétraplégique = contrôle du tronc compromis → dossier HAUT. Paraplégique avec contrôle du tronc → dossier BAS.","s":14},{"q":"L'assise d'un fauteuil roulant doit permettre un angle de :","o":["45° hanche/genou","60° hanche/genou","90° hanche/genou","120° hanche/genou"],"r":2,"e":"Angle de 90° aux hanches ET aux genoux, profondeur à 5-7 cm de la région poplitée.","s":14},{"q":"Le dispositif anti-chute d'un fauteuil roulant sert à :","o":["Décorer","Prévenir les chutes vers l'arrière et faciliter le soulèvement de l'avant","Freiner","Propulser"],"r":1,"e":"Prévient les chutes arrière (FR en wheelie) ET facilite le soulèvement avant pour les trottoirs.","s":14},{"q":"Pour MONTER des escaliers en fauteuil roulant avec 2/3 aides, le 1er transporteur est :","o":["Face aux escaliers","Dos aux escaliers, aux poignées","À côté","Devant le patient"],"r":1,"e":"MONTÉE : 1er transporteur DOS AUX ESCALIERS aux poignées, fait les commandes. Les autres tirent les grandes roues.","s":14},{"q":"Pour DESCENDRE en fauteuil roulant avec 2/3 aides, le 1er transporteur est :","o":["Dos aux escaliers","Face à l'escalier aux poignées","Sur les côtés","Derrière les autres"],"r":1,"e":"DESCENTE : 1er transporteur FACE à l'escalier aux poignées ; les autres aux jantes propulsives.","s":14},{"q":"Une marche à 4 points est caractérisée par :","o":["Avance simultanée d'une aide et du MI opposé","Mouvements alternés (aide droite, MI gauche, aide gauche, MI droit)","Pas de transfert de poids","Pas de séquence"],"r":1,"e":"Marche à 4 points : mouvements alternés successifs, très stable, contact constant avec le sol.","s":14},{"q":"Pour la marche à 2 points, l'avance se fait :","o":["1 élément à la fois","Aide gauche + MI droit SIMULTANÉMENT, puis aide droite + MI gauche","Aides ensemble puis MI ensemble","Aucune coordination"],"r":1,"e":"Marche à 2 points : avance SIMULTANÉE croisée (aide gauche + MI droit), reproduit le pas physiologique.","s":14},{"q":"Quelle aide est INTERDITE en unilatéral le plus souvent ?","o":["Canne","Trépied","Béquille axillaire","Béquille canadienne"],"r":2,"e":"L'usage UNILATÉRAL des béquilles axillaires n'est PAS courant (rare).","s":14},{"q":"Le standing-frame est destiné aux patients :","o":["Autonomes à la marche","Dépendants pour le positionnement orthostatique","Sportifs","Sans pathologie"],"r":1,"e":"Patients DÉPENDANTS pour l'orthostatisme (LMS, neuro) — maintien vertical sans aide tierce.","s":14},{"q":"La canne anglaise (béquille axillaire) doit prendre appui :","o":["Sous l'aisselle","Sur la poignée latérale, avant-bras dans l'appui-bras","Sur l'épaule","Sur la nuque"],"r":1,"e":"Aucun appui axillaire prolongé (risque de paralysie du n. radial) ! La force passe par la poignée et l'avant-bras.","s":14},{"q":"La canne simple se tient :","o":["Du côté lésé","Du côté SAIN (opposé à la lésion)","Au choix","Devant"],"r":1,"e":"Côté sain : la canne et le MI atteint avancent ensemble → décharge du côté lésé.","s":14},{"q":"La marche en 3 points convient à :","o":["Une boiterie minime","Un patient avec un MI non-appui (post-fracture) + 2 béquilles","Un patient autonome","Aucun patient"],"r":1,"e":"3 points : les 2 béquilles + le MI sain avancent, MI atteint reste en suspension (sans appui).","s":14},{"q":"La marche pendulaire est utilisée par :","o":["Tous les patients","Patients sans appui des deux MI (paraplégie) avec 2 béquilles","Patients autonomes","Enfants"],"r":1,"e":"Pendulaire : 2 béquilles en avant puis les 2 MI passent en bloc devant les béquilles (paraplégie incomplète).","s":14},{"q":"Hauteur correcte du déambulateur :","o":["Sous l'aisselle","Au niveau du grand trochanter ; coude légèrement fléchi (20-30°)","Au sol","Au niveau de l'épaule"],"r":1,"e":"Hauteur = grand trochanter ; coude fléchi 20-30° en appui pour ne pas voûter le dos.","s":14},{"q":"Le fauteuil roulant est présenté comme :","o":["Un instrument d'autonomie et d'intégration, et non une aide à la marche","Une aide à la marche","Un dispositif temporaire","Un équipement médical passif"],"r":0,"e":"Cette distinction conceptuelle est explicite dans le cours.","s":14},{"q":"Le déambulateur peut être articulé afin :","o":["De faciliter la dissociation des ceintures","D'alléger le poids","D'améliorer le freinage","De se ranger"],"r":0,"e":"Sa base quadrangulaire reste la plus grande de toutes les aides.","s":14},{"q":"Pour les trépieds et pyramides, la concavité de la poignée est tournée :","o":["Vers le patient","Vers l'extérieur","Vers l'avant","Vers le sol"],"r":0,"e":"Ils s'utilisent en bilatéral ou en unilatéral, du côté opposé à la dysfonction.","s":14},{"q":"Selon Laufer (2003), les trépieds :","o":["Réduisent le balancement postural chez les hémiplégiques","Augmentent la vitesse","Diminuent la douleur","Améliorent l'endurance"],"r":0,"e":"Buurke (2005) montre que la canne active les extenseurs du tronc et le tibial antérieur.","s":14},{"q":"Le danger de l'appui axillaire sur une béquille est :","o":["La compression des structures nerveuses et vasculaires axillaires","Une luxation d'épaule","Une fracture costale","Une douleur cervicale"],"r":0,"e":"Le support thoracique se place environ 10 cm en dessous de l'aisselle.","s":14},{"q":"Les barres parallèles permettent également :","o":["L'entraînement aux transferts assis vers debout","La marche en extérieur","L'entraînement à la propulsion","Le travail de la force"],"r":0,"e":"Elles offrent une excellente sécurité pour démarrer l'entraînement à la marche.","s":14},{"q":"Parmi les bénéfices du standing frame, le cours cite :","o":["La limitation de la diminution de la densité osseuse et la réduction de la spasticité","L'augmentation de la force","L'amélioration de l'endurance","La réduction de la douleur"],"r":0,"e":"Il augmente aussi l'indépendance, la fonctionnalité et l'estime de soi, et évite les modifications de mobilité articulaire.","s":14},{"q":"Les orthèses permettent :","o":["De contrôler et stabiliser les articulations des membres inférieurs que le patient ne peut pas contrôler volontairement","D'augmenter la force","De réduire la douleur","De remplacer la marche"],"r":0,"e":"Elles rendent la marche possible en cas de lésion médullaire.","s":14},{"q":"La marche à 4 points est indiquée pour :","o":["Une marche très stable, chez des patients faibles ou en équilibre fragile","Un appui interdit","Un appui partiel","Un patient autonome"],"r":0,"e":"Les aides se placent à environ 15 cm devant chaque pied, au même niveau.","s":14},{"q":"La marche à 3 points est indiquée quand :","o":["L'appui est interdit sur le membre inférieur blessé, par exemple après une opération récente","L'appui est partiel","L'appui est complet","L'équilibre est fragile"],"r":0,"e":"Le membre blessé effectue un pas sans toucher le sol.","s":14},{"q":"La marche à 3 points modifiée se distingue par :","o":["Un appui partiel sur le membre blessé, le poids étant réparti entre aides, membre sain et membre blessé","Un appui nul","Un appui complet","L'absence d'aides"],"r":0,"e":"C'est la transition entre l'appui interdit et la reprise d'appui complet.","s":14},{"q":"L'assise du fauteuil roulant se règle à une profondeur de :","o":["5 à 7 cm de la région poplitée","Au contact du creux poplité","10 cm","15 cm"],"r":0,"e":"Elle doit permettre un angle de 90° aux hanches et aux genoux.","s":14},{"q":"Le dossier du fauteuil roulant se règle à :","o":["10 cm de l'aisselle","Au niveau des épaules","Au niveau du bassin","Sans repère"],"r":0,"e":"Un dossier haut convient à la tétraplégie et un dossier bas à la paraplégie.","s":14},{"q":"Les jantes propulsives se situent :","o":["À l'extérieur des grandes roues, pour la propulsion par le patient","À l'intérieur","Sur les roues libres","Sur le châssis"],"r":0,"e":"Les grandes roues mesurent 61 cm et les roues libres environ 20 cm.","s":14},{"q":"Les accoudoirs du fauteuil roulant sont :","o":["Amovibles, permettant le repos des membres supérieurs coude à 90° et les push-ups","Fixes","Sans réglage","Purement décoratifs"],"r":0,"e":"Leur amovibilité est essentielle lors des transferts latéraux.","s":14},{"q":"Le réglage commun à toutes les aides à la marche est :","o":["La poignée au niveau du grand trochanter, coudes en légère flexion d'environ 25°","La poignée au niveau du coude","La poignée au niveau de la hanche, coude tendu","Une hauteur libre"],"r":0,"e":"L'embout se place 10 à 15 cm devant et à l'extérieur des pointes des pieds.","s":14},{"q":"La sangle d'avant-bras de la béquille canadienne se place :","o":["5 cm sous le coude","10 cm sous le coude","Au niveau du poignet","Au pli du coude"],"r":0,"e":"La béquille se compose d'une poignée, d'une sangle d'avant-bras et d'un embout caoutchouc.","s":14},{"q":"Selon Bateni & Maki (2005), l'aide controlatérale réduit la charge coxo-fémorale d'environ :","o":["60 %","30 %","80 %","40 %"],"r":0,"e":"C'est pourquoi la canne se place du côté opposé à la dysfonction.","s":14},{"q":"Le châssis du fauteuil roulant peut être :","o":["Articulé en X et pliable, ou rigide","Uniquement rigide","Uniquement pliable","Télescopique"],"r":0,"e":"Les freins assurent l'immobilisation et la stabilisation du fauteuil.","s":14},{"q":"L'orthèse KAFO stabilise la cheville en :","o":["Flexion dorsale de 5 à 10°","Flexion plantaire","Position neutre stricte","Inversion"],"r":0,"e":"Elle stabilise le genou en extension ; l'HKAFO y ajoute la stabilisation latérale du bassin.","s":14},{"q":"Les principes directeurs du positionnement incluent :","o":["Être inconfortables","Donner une notion du corps dans son ensemble","Limiter la mobilité","Éviter la stimulation"],"r":1,"e":"Le positionnement doit être confortable, fonctionnel, donner une notion du corps dans son ensemble, et offrir une stimulation sensorielle/proprioceptive.","s":15},{"q":"Lors d'un ajustement dans le lit à 2 personnes, le lit doit être à hauteur :","o":["Du genou","Du grand trochanter des soignants","Du nombril","Du coude"],"r":1,"e":"Lit à hauteur du grand trochanter du kiné/assistant pour utiliser leur biomécanique.","s":15},{"q":"Pour rouler un patient avec assistance, les mains du kiné sont sur :","o":["La tête et les pieds","Les ceintures scapulaire et pelvienne","Les genoux","Les poignets"],"r":1,"e":"Ceinture scapulaire + ceinture pelvienne pour un roulement EN BLOC.","s":15},{"q":"Au transfert australienne, l'épaule du transporteur s'appuie :","o":["Dans l'aisselle du patient","Contre la cage thoracique SOUS l'aisselle, jamais dans l'aisselle","Sur la tête","Sur le bassin"],"r":1,"e":"Épaule contre la cage thoracique SOUS l'aisselle. Ne jamais exercer de pression dans l'aisselle (compression nerveuse/vasculaire).","s":15},{"q":"Combien d'options de positionnement existent pour le décubitus latéral côté affecté ?","o":["1","2","3","4"],"r":2,"e":"3 options : coude en flexion, coude en extension, MS libres.","s":15},{"q":"Quel transfert s'utilise pour la GRANDE dépendance (lit↔lit) ?","o":["1 transporteur","Siège à 2","3 ou 4 transporteurs","Aucun"],"r":2,"e":"Grande dépendance = 3/4 transporteurs (ex: lésion vertébro-médullaire).","s":15},{"q":"Lors d'un transfert à 4 transporteurs, le 4e a pour rôle :","o":["Tenir les pieds","Soutenir le bassin","Tirer EXCLUSIVEMENT la tête, en suivant le mouvement","Donner les commandes"],"r":2,"e":"Le 4e transporteur tire EXCLUSIVEMENT la tête, suivant le mouvement.","s":15},{"q":"Le transfert australienne convient pour :","o":["Uniquement les courtes distances","Longues distances, escaliers, ajustement dans le lit","Patients comateux","Aucun cas"],"r":1,"e":"Australienne : longues distances, escaliers, ajustement dans le lit, passage au sol.","s":15},{"q":"Pour le transfert à 2 transporteurs (classique lit↔chaise), le 1er transporteur :","o":["Tient les jambes","Se place derrière le patient et fait une prise croisée des avant-bras","Est devant le patient","Tient la tête"],"r":1,"e":"1er transporteur DERRIÈRE le patient, prise CROISÉE au niveau des avant-bras. Le 2e soutient les MI.","s":15},{"q":"L'angle entre les 2 surfaces lors d'un transfert à 1 transporteur est :","o":["0° (parallèles)","45°","90°","180°"],"r":1,"e":"Surfaces à 45° pour le transfert à 1 transporteur (destination plus basse si possible).","s":15},{"q":"La planche de transfert est utilisée pour :","o":["Patient totalement dépendant","Patient pouvant utiliser ses MS pour glisser","Patient en coma","Personne"],"r":1,"e":"Planche de transfert : patient qui peut utiliser ses MS pour glisser d'une surface à l'autre.","s":15},{"q":"Sur le côté affecté en décubitus latéral, dans l'OPTION 2, le coude est :","o":["En flexion","En extension","En rotation","Libre"],"r":1,"e":"Option 1 = flexion ; Option 2 = EXTENSION ; Option 3 = MS libres.","s":15},{"q":"Quelle est la zone la plus à risque d'escarre en décubitus dorsal ?","o":["L'oreille","Le sacrum, le calcanéum, l'occiput","Le pubis","Le coude"],"r":1,"e":"Zones-clés en décubitus dorsal : sacrum, calcanéum, occiput, olécrane, épine omoplate.","s":15},{"q":"Le décubitus ventral est utilisé en cas de :","o":["Repos normal","Insuffisance respiratoire grave / escarres postérieures / postopératoire","Préférence du patient","Soins quotidiens"],"r":1,"e":"Position d'exception : insuffisance respiratoire grave, escarres postérieures, postopératoire, raccourcissement des fléchisseurs de hanche.","s":15},{"q":"Pour ajuster le lit à 1 personne, le patient fait :","o":["Rien","Un PONT (genoux fléchis, pieds appuyés) avec poussée vers les pieds","Une rotation","Un saut"],"r":1,"e":"Le patient fléchit les MI (pieds appuyés) et fait un PONT pendant que le kiné applique une pression vers les pieds.","s":15},{"q":"Lors du transfert, les commandes doivent être :","o":["Multiples et complexes","Claires, explicites, UNE SEULE commande","Silencieuses","Inutiles"],"r":1,"e":"Commandes claires et explicites, UNE seule commande (ex: 1,2,3) pour synchroniser.","s":15},{"q":"Avant un transfert avec FR, il faut :","o":["Laisser les freins libres","Bloquer les freins, retirer l'accoudoir et relever la pédale côté transfert","Laisser l'accoudoir en place","Ne rien faire"],"r":1,"e":"FR FREINÉ, accoudoir retiré et pédale relevée côté transfert pour libérer l'accès.","s":15},{"q":"Le rôle du chef d'équipe lors d'un transfert à 3/4 personnes est de :","o":["Soutenir les pieds","Soutenir la tête et la nuque (occiput + C1-C2)","Pousser le lit","Observer"],"r":1,"e":"Le chef d'équipe soutient la TÊTE-COU (occiput + 2 premières vertèbres cervicales) et donne les commandes.","s":15},{"q":"Pour s'asseoir avec assistance, le patient doit d'abord :","o":["Sauter","Rouler sur le côté en restant au bord du lit","S'allonger","Tirer sur les bras"],"r":1,"e":"Rouler sur le côté et rester au bord du lit, puis croiser les MS sous la poitrine.","s":15},{"q":"Concernant les contacts manuels, ils ne doivent jamais :","o":["Être en coupe","Soutenir par le dessus","Épouser le segment","Transmettre confort"],"r":1,"e":"Les mains ne soutiennent JAMAIS par le dessus, ni avec pression des doigts.","s":15},{"q":"Au transfert siège (2 transporteurs), les transporteurs sont :","o":["Côte à côte","Face à face, de profil par rapport au chemin","L'un derrière l'autre","Dos à dos"],"r":1,"e":"Face à face, de PROFIL au chemin. Saisie sous les cuisses (avant-bras/poignet).","s":15},{"q":"La prévention des escarres est :","o":["Du ressort exclusif du médecin","Une intervention multidisciplinaire intégrée","Réservée aux infirmiers","Inutile"],"r":1,"e":"Équipe MULTIDISCIPLINAIRE intégrée avec objectifs communs.","s":15},{"q":"Pour rouler SANS assistance, le patient :","o":["MS en adduction","Met les MS en abduction, MI fléchis, et joint les paumes des mains","Garde les bras le long du corps","Saute"],"r":1,"e":"MS en abduction + MI fléchis + paumes jointes = roulement autonome.","s":15},{"q":"Pour la position debout avec assistance, le kiné :","o":["Tire sur les bras du patient","Soutient le MS et les genoux (face latérale externe), transfère le poids vers l'avant","Soulève par les aisselles","Reste passif"],"r":1,"e":"Kiné soutient MS (selon dysfonction), genoux (face latérale externe), et transfère le poids VERS L'AVANT pour le redressement.","s":15},{"q":"Le transfert à 3 transporteurs Lit↔Lit débute par :","o":["Soulever directement","Amener le patient au BORD du lit, MS des transporteurs aux endroits indiqués","Tourner le patient","Mettre une planche"],"r":1,"e":"On amène d'abord le patient AU BORD du lit. MS des transporteurs aux 3 niveaux (cou, pelvis, MI), avant-bras fléchis et proches du tronc.","s":15},{"q":"Pour faire passer un patient du décubitus dorsal au latéral, on :","o":["Tire le bras seul","Croise jambe + bras opposé et fait pivoter le tronc en bloc","Pousse les pieds","Lève la tête uniquement"],"r":1,"e":"Mobilité au lit DD→DL = bras opposé en travers, MI opposé fléchi, rotation en bloc tronc/bassin.","s":15},{"q":"Le drap de glissement (slide sheet) sert à :","o":["Couvrir le lit","Réduire les frictions lors des déplacements du patient au lit","Décorer","Chauffer"],"r":1,"e":"Slide sheet → ↓ friction → patient déplacé plus facilement → ↓ effort soignant et ↓ risque escarre/cisaillement.","s":15},{"q":"Le rehaussement au lit s'effectue idéalement à :","o":["1 aidant","2 aidants synchronisés","Aucun aidant","5 aidants"],"r":1,"e":"2 aidants synchronisés + slide sheet = méthode sûre pour rehausser un patient sans force excessive.","s":15},{"q":"Le coussin de positionnement :","o":["Sert à décorer","Prévient les zones d'appui, maintient l'alignement, évite les rétractions","Provoque les escarres","Limite les mouvements"],"r":1,"e":"Coussins = répartir les pressions + maintenir alignement neutre + prévenir rétractions (équin, rotation hanche).","s":15},{"q":"En décubitus latéral, on stabilise par :","o":["Rien","Un coussin contre le dos, un entre les genoux","Une charge sur la tête","Les pieds en extension max"],"r":1,"e":"DL : coussin dorsal (anti-bascule) + coussin entre genoux (alignement hanche, ↓ pression interne).","s":15},{"q":"Les techniques de positionnement et de mobilité visent à préserver :","o":["Le schéma corporel, la mobilité articulaire, la conscience du mouvement et l'intégrité cutanée","La seule intégrité cutanée","La seule mobilité","Le seul schéma corporel"],"r":0,"e":"Elles préviennent aussi les complications cardiorespiratoires et circulatoires.","s":15},{"q":"Parmi les objectifs du positionnement figure :","o":["Former le patient et ses proches ou soignants","La seule prévention cutanée","Le seul confort","La seule mobilisation"],"r":0,"e":"S'y ajoutent la prévention des altérations, la facilitation du schéma de mouvement et du lever précoce.","s":15},{"q":"Les principes directeurs du positionnement imposent une norme :","o":["Adaptable selon l'état du patient","Rigide","Universelle","Fixée par protocole"],"r":0,"e":"Les positionnements doivent être confortables, fonctionnels, offrir une stimulation sensorielle et proprioceptive et donner une notion du corps dans son ensemble.","s":15},{"q":"En position assise, les zones à risque d'escarre sont :","o":["Épine de l'omoplate, tubérosité ischiatique, région sacrée, poplitée et métatarses","Occiput et sacrum","Trochanter et malléole","Rotule et épine iliaque"],"r":0,"e":"Chaque décubitus a ses zones propres, à connaître pour la prévention.","s":15},{"q":"La prévention des escarres relève :","o":["D'une équipe multidisciplinaire","Du seul kinésithérapeute","Du seul infirmier","Du seul patient"],"r":0,"e":"Elle associe autocontrôle, changements toutes les 2 heures, positionnements, mobilisations, matériel, alimentation, hygiène et soins vestimentaires.","s":15},{"q":"En décubitus dorsal chez un patient totalement dépendant, il faut éviter :","o":["Le poids des vêtements sur le tibio-tarsien, qui doit rester en position neutre, talons non appuyés","Les coussins","L'abduction des membres","La rotation externe"],"r":0,"e":"Les membres supérieurs sont en légère abduction et rotation externe sur coussin.","s":15},{"q":"Chez le patient partiellement dépendant en décubitus dorsal, l'attention porte sur :","o":["La symétrie et l'alignement entre segments","Le seul confort","Les seuls appuis","La seule respiration"],"r":0,"e":"Les procédures restent par ailleurs similaires à celles du patient totalement dépendant.","s":15},{"q":"En décubitus latéral, l'épaule inférieure doit être :","o":["Avancée, avec la main posée sur l'oreiller","Reculée","Sous le tronc","En rotation interne"],"r":0,"e":"Le membre supérieur supérieur repose à l'horizontale sur un coussin, main fonctionnelle.","s":15},{"q":"Sur le côté non affecté en décubitus latéral :","o":["Le membre inférieur supéro-latéral est en flexion sur coussin, tibio-tarsien neutre sur coussin","Les membres restent tendus","Aucun coussin n'est utilisé","Le tibio-tarsien est en équin"],"r":0,"e":"Trois options existent pour le positionnement du côté affecté, selon la position du coude et des membres supérieurs.","s":15},{"q":"Parmi les principes de sécurité de la mobilité précoce figure :","o":["Optimiser sa biomécanique par le positionnement et le poids du corps","Utiliser sa force","Travailler seul","Accélérer le mouvement"],"r":0,"e":"Il faut aussi ne pas traîner, ne pas forcer sur les articulations, éviter les amplitudes extrêmes, favoriser l'alignement, permettre la participation et demander de l'aide.","s":15},{"q":"Pour ajuster le lit à deux personnes, il ne faut pas :","o":["Tirer par la ceinture scapulaire ni traîner le drap","Utiliser le drap","Régler la hauteur","Mettre les segments à niveau"],"r":0,"e":"Le lit se règle à hauteur du grand trochanter des soignants, segments au même niveau.","s":15},{"q":"Pour ajuster le lit à une personne, le patient :","o":["Fléchit les genoux, appuie les pieds et fait le pont pendant que le kiné exerce une pression vers les pieds","Est tiré par les épaules","Reste passif","Se retourne"],"r":0,"e":"Il se déplace ainsi progressivement vers la tête de lit.","s":15},{"q":"Pour s'asseoir avec assistance, le membre supérieur distal du kiné :","o":["Place les membres inférieurs hors du lit, créant le mouvement pendulaire","Soutient la tête","Contrôle la ceinture scapulaire","Reste libre"],"r":0,"e":"Le membre supérieur proximal soutient la tête et contrôle la ceinture scapulaire.","s":15},{"q":"Pour la position debout avec assistance, le kiné soutient les genoux :","o":["Par leur face latérale externe","En poplité","En antérieur","Par la rotule"],"r":0,"e":"Il soutient aussi le membre supérieur selon le dysfonctionnement, avant le transfert de poids vers l'avant et le redressement.","s":15},{"q":"Parmi les points de minimisation des risques lors d'un transfert figure :","o":["Vérifier la stabilité et les fixations : freins, pieds, roues vers l'avant","Le seul contrôle des freins","La seule hauteur","Le seul itinéraire"],"r":0,"e":"S'y ajoutent la préparation de l'espace, l'analyse du levage, la hauteur des surfaces, la localisation des aides et l'historique des transferts.","s":15},{"q":"La stratégie d'un transfert définit :","o":["Le nombre de transporteurs, le lieu, le type et l'itinéraire","La seule pathologie","Le seul matériel","Le seul horaire"],"r":0,"e":"Elle suit l'évaluation du type de pathologie, du degré de dépendance et des conditions d'alitement.","s":15},{"q":"Le décubitus ventral est réservé à des situations spécifiques telles que :","o":["Le postopératoire, l'insuffisance respiratoire grave, les escarres postérieures et le raccourcissement des fléchisseurs de hanche","Toute immobilisation prolongée","La prévention systématique","Le confort"],"r":0,"e":"Il est généralement mal toléré par le patient.","s":15},{"q":"Pour rouler avec assistance, le roulement doit se faire :","o":["En bloc, une main sur la ceinture scapulaire et l'autre sur la ceinture pelvienne","Segment par segment","Par traction du bras","Par poussée du bassin"],"r":0,"e":"Le patient a les membres inférieurs fléchis et les pieds appuyés.","s":15},{"q":"Pour se lever sans assistance depuis la position assise, le patient :","o":["Place les mains au bord du lit, se penche en avant nez vers les pieds, puis étire colonne et genoux","Tire sur la barrière","Pousse sur les bras seuls","Se penche en arrière"],"r":0,"e":"Le mouvement vers l'avant amène le centre de gravité au-dessus des appuis.","s":15},{"q":"En décubitus latéral, le coussin entre les genoux sert à :","o":["Maintenir les membres inférieurs fléchis dans un alignement correct","Surélever le bassin","Protéger le trochanter","Faciliter le roulement"],"r":0,"e":"Un coussin dos-lit peut s'y ajouter si nécessaire, et le tibio-tarsien supérieur reste en position neutre.","s":15},{"q":"Le déambulateur offre une base d'appui :","o":["Triangulaire","Quadrangulaire (la plus grande)","Linéaire","Aucune"],"r":1,"e":"Base d'appui QUADRANGULAIRE, la plus grande de toutes les aides à la marche.","s":16},{"q":"Le réglage standard de toutes les aides à la marche place la poignée :","o":["À l'épaule","Au grand trochanter, avec flexion coude ~25°","Au coude","Au genou"],"r":1,"e":"Poignée au GRAND TROCHANTER avec FLEXION COUDE ~25°. Règle commune à toutes les aides.","s":16},{"q":"Quelle différence existe entre un trépied et une pyramide ?","o":["Aucune","Trépied = 3 points d'appui, Pyramide = 4 points d'appui","Pyramide est plus petite","Trépied est en bois"],"r":1,"e":"Trépied = 3 points d'appui en caoutchouc ; Pyramide = 4 points d'appui.","s":16},{"q":"Pour un trépied/pyramide, la concavité de la poignée doit être :","o":["Tournée vers l'extérieur","Tournée vers le patient","Vers le haut","Indifférent"],"r":1,"e":"Concavité de la poignée TOURNÉE VERS LE PATIENT, points d'appui vers l'extérieur.","s":16},{"q":"La sangle d'avant-bras d'une béquille canadienne se place :","o":["Au poignet","5 cm sous le coude","À l'épaule","Sur la main"],"r":1,"e":"Sangle d'avant-bras à 5 cm sous le coude pour bon contrôle sans gêne.","s":16},{"q":"L'embout d'une aide à la marche se positionne :","o":["Sous le pied","Derrière le pied","10/15 cm devant et à l'extérieur des pointes des pieds","À côté du genou"],"r":2,"e":"10/15 cm DEVANT et à L'EXTÉRIEUR des pointes des pieds pour une base optimale.","s":16},{"q":"L'utilisation controlatérale d'une aide à la marche réduit la charge coxo-fémorale d'environ :","o":["10%","30%","60%","90%"],"r":2,"e":"Bateni & Maki (2005) : environ −60% de charge sur l'articulation coxo-fémorale du côté dysfonction.","s":16},{"q":"Le support thoracique de la béquille axillaire doit se trouver :","o":["Dans l'aisselle","10 cm SOUS l'aisselle, contre la cage thoracique","À l'épaule","Au coude"],"r":1,"e":"~10 cm SOUS l'aisselle, sur la cage thoracique latérale, pour éviter la compression axillaire.","s":16},{"q":"La canne s'utilise du côté :","o":["Du membre blessé","Opposé à la dysfonction","Indifférent","Toujours à droite"],"r":1,"e":"Côté OPPOSÉ à la dysfonction pour répartir la charge.","s":16},{"q":"Diamètre des grandes roues du fauteuil roulant :","o":["20 cm","40 cm","61 cm","100 cm"],"r":2,"e":"Grandes roues : 61 cm. Roues libres (avant) : ~20 cm.","s":16},{"q":"L'assise d'un FR doit permettre un angle hanche/genou de :","o":["45°","60°","90°","120°"],"r":2,"e":"Angle de 90° aux hanches ET aux genoux, profondeur 5-7 cm de la région poplitée.","s":16},{"q":"Un patient TÉTRAPLÉGIQUE a besoin d'un dossier :","o":["Bas","Haut (meilleur soutien du tronc)","Sans dossier","Inclinable seulement"],"r":1,"e":"Tétra = contrôle tronc compromis → dossier HAUT. Para avec contrôle tronc → dossier BAS.","s":16},{"q":"Le dispositif anti-chute du FR sert à :","o":["Freiner","Prévenir chutes arrière et faciliter le soulèvement avant (trottoirs)","Décorer","Propulser"],"r":1,"e":"Prévient les chutes vers l'arrière (FR en wheelie) ET facilite le soulèvement de l'avant pour monter un trottoir.","s":16},{"q":"Une orthèse KAFO stabilise le genou en :","o":["Flexion 90°","Extension + cheville en flexion dorsale 5-10°","Rotation interne","Aucune position"],"r":1,"e":"KAFO = genou EN EXTENSION + cheville en légère flexion dorsale (5-10°).","s":16},{"q":"Bénéfices du standing-frame :","o":["Augmente la spasticité","Limite la perte de densité osseuse, diminue la spasticité, augmente l'estime de soi","Réduit l'estime de soi","Aucun"],"r":1,"e":"Standing-frame : ↓ perte densité osseuse, ↓ spasticité, ↑ indépendance/fonctionnalité/estime de soi.","s":16},{"q":"Marche à 3 points : la charge sur le MI blessé est :","o":["Totale","Partielle","Nulle (le MI ne touche pas le sol)","Variable"],"r":2,"e":"Marche à 3 points = charge NULLE sur le MI blessé (ne touche PAS le sol).","s":16},{"q":"Marche à 3 points MODIFIÉS : la charge sur le MI blessé est :","o":["Nulle","Partielle (autorisée)","Totale","Variable selon le moment"],"r":1,"e":"3 points modifiés = charge PARTIELLE autorisée sur le MI blessé.","s":16},{"q":"Le pourcentage de patients avec lésion médullaire capables de marcher est d'environ :","o":["10%","25%","50%","90%"],"r":2,"e":"Harvey (2008) : environ 50% des personnes avec lésion médullaire sont capables de marcher.","s":16},{"q":"La marche pendulaire (swing-through) se distingue de la semi-pendulaire (swing-to) par :","o":["Pas de différence","Les MI dépassent la ligne des aides","Une seule béquille","Pas d'orthèses"],"r":1,"e":"Pendulaire (swing-THROUGH) : les MI DÉPASSENT la ligne des aides. Semi (swing-TO) : MI s'arrêtent à la ligne.","s":16},{"q":"Pour monter un trottoir avec déambulateur, on commence par :","o":["Le MI blessé","Le MI sain, après avoir placé le déambulateur sur le trottoir","Sauter","Le déambulateur en dernier"],"r":1,"e":"Déambulateur sur trottoir → MI SAIN monte → puis MI blessé.","s":16},{"q":"Pour MONTER un escalier en FR avec 2/3 aides, le 1er transporteur est :","o":["Face aux escaliers","DOS aux escaliers, aux poignées + commandes","À côté","Devant le patient"],"r":1,"e":"MONTÉE : 1er DOS aux escaliers aux poignées + commandes ; les autres aux mains courantes.","s":16},{"q":"Pour DESCENDRE un escalier en FR avec 2/3 aides :","o":["Dos aux escaliers","FACE à l'escalier, 1er aux poignées + commandes ; autres aux jantes","Sur le côté","Aucune règle"],"r":1,"e":"DESCENTE : 1er FACE à l'escalier aux poignées ; 2e/3e aux jantes propulsives.","s":16},{"q":"Marche à 2 points : avance simultanée de :","o":["2 aides puis 2 pieds","Aide gauche + MI droit, puis aide droite + MI gauche","Tout en même temps","Une seule aide"],"r":1,"e":"Marche à 2 points : avance simultanée CROISÉE (aide gauche + MI droit), proche du pas physiologique.","s":16},{"q":"L'utilisation d'une canne chez l'hémiparésique :","o":["Augmente le travail musculaire du MI","Réduit le travail musculaire du MI et active les extenseurs du tronc et le tibial antérieur","Aucun effet","Bloque la marche"],"r":1,"e":"Buurke et al. (2005) : la canne réduit le travail musculaire du MI et active les extenseurs du tronc + tibial antérieur.","s":16},{"q":"La règle générale pour escaliers avec une aide unilatérale :","o":["Aide côté MI blessé","Aide côté MI sain, rampe main opposée","Aide au milieu","Pas d'aide"],"r":1,"e":"Aide TOUJOURS du côté du MI SAIN, rampe (si disponible) avec la main opposée.","s":16},{"q":"Un fauteuil roulant manuel adapté doit avoir :","o":["Un siège quelconque","Un siège à la bonne largeur (≈ largeur des hanches + 2-3 cm) et profondeur","Des roues plates","Un dossier rigide haut quelle que soit la pathologie"],"r":1,"e":"Largeur trop grande = bascule latérale ; trop étroite = points de pression. Profondeur = 2-3 doigts derrière le creux poplité.","s":16},{"q":"L'angle du repose-pied du FR :","o":["Doit être à 0°","Doit permettre une position confortable du genou (≈ 90° hanche et genou)","Très en arrière","Pendant"],"r":1,"e":"Pieds reposés → hanche et genou ≈ 90°, alignement neutre, prévention œdème et ↓ pression ischiatique.","s":16},{"q":"Sur un terrain accidenté (graviers), le déambulateur :","o":["Convient parfaitement","Peut être instable, préférer des aides plus stables (cadre lesté ou aide humaine)","Roule mieux","Est inutile"],"r":1,"e":"Roulettes/embouts peuvent glisser/coincer → préférer des aides plus stables ou un accompagnement physique.","s":16},{"q":"L'orthèse anti-équin sert à :","o":["Renforcer le mollet","Maintenir la cheville à 90° pour permettre la marche (pied tombant)","Bloquer le genou","Allonger le tibia"],"r":1,"e":"Releveur (AFO) → empêche la chute du pied à la phase oscillante (atteinte du fibulaire commun, hémiplégie).","s":16},{"q":"En descente d'escalier avec béquilles, on commence par :","o":["Le MI sain","Les béquilles + le MI atteint","La tête en bas","Sauter"],"r":1,"e":"Descente : les béquilles + le MI atteint vont en premier (le sain reste en haut). Montée : MI sain en premier.","s":16},{"q":"Selon Bateni & Maki (2005), l'augmentation de la base d'appui :","o":["Maintient le centre de gravité dans les limites de la base pendant une plus grande partie du cycle de marche","Accélère la marche","Réduit la dépense énergétique","Augmente la longueur du pas"],"r":0,"e":"C'est ce qui justifie la hiérarchie des aides, du déambulateur à la canne.","s":16},{"q":"Le déambulateur articulé présente l'intérêt :","o":["De faciliter la dissociation des ceintures","D'être plus léger","D'être plus stable","De se plier"],"r":0,"e":"Sa base d'appui quadrangulaire reste la plus grande de toutes les aides.","s":16},{"q":"Le trépied et la pyramide permettent une utilisation unilatérale :","o":["En tournant simplement la poignée","En changeant les embouts","En les raccourcissant","Ce n'est pas possible"],"r":0,"e":"La concavité de la poignée se tourne vers le patient et les points d'appui vers l'extérieur.","s":16},{"q":"Les béquilles canadiennes existent en variantes pour :","o":["Les arthritiques, chez qui la charge est impossible sur le poignet, la main ou les doigts","Les enfants","Les sportifs","Les personnes âgées"],"r":0,"e":"Leurs sangles peuvent être fixes ou articulées, fermées ou ouvertes.","s":16},{"q":"Le support thoracique de la béquille axillaire ne doit pas toucher l'aisselle afin :","o":["D'éviter la compression des structures axillaires, nerfs et vaisseaux","De réduire la douleur","D'améliorer l'équilibre","De faciliter la propulsion"],"r":0,"e":"Il se place environ 10 cm en dessous, contre la cage thoracique en latéral.","s":16},{"q":"Selon Buurke et al. (2005), la canne chez l'hémiparésique :","o":["Réduit le travail musculaire du membre inférieur et active les extenseurs du tronc et le tibial antérieur","Augmente le travail musculaire","N'a aucun effet","Diminue l'équilibre"],"r":0,"e":"Laufer (2003) montre de son côté que le trépied réduit le balancement postural chez l'hémiplégique.","s":16},{"q":"Les barres parallèles sont idéales pour :","o":["Démarrer l'entraînement à la marche, avec une sécurité maximale","Les longs déplacements","L'usage à domicile","La marche en extérieur"],"r":0,"e":"Elles permettent aussi l'entraînement aux transferts assis-debout.","s":16},{"q":"Le dossier du fauteuil roulant se règle :","o":["À 10 cm sous l'aisselle et 2,5 à 5 cm de l'angle inférieur de l'omoplate","Au niveau des épaules","Au niveau des crêtes iliaques","Sans repère précis"],"r":0,"e":"Sa hauteur dépend du contrôle du tronc : haut pour la tétraplégie, bas pour la paraplégie.","s":16},{"q":"Les roues libres du fauteuil roulant :","o":["Mesurent environ 20 cm et assurent le braquage","Mesurent 61 cm","Assurent la propulsion","Portent les jantes propulsives"],"r":0,"e":"Les grandes roues, de 61 cm, portent les jantes propulsives utilisées par le patient.","s":16},{"q":"L'orthèse KAFO stabilise :","o":["Le genou en extension et la cheville en flexion dorsale de 5 à 10°","Le genou en flexion","La hanche","Le bassin"],"r":0,"e":"Elle comporte souvent deux barres longitudinales et des supports de cuisse, jambe et pied, parfois articulés pour permettre la flexion assise.","s":16},{"q":"L'orthèse HKAFO ajoute :","o":["La stabilisation latérale du bassin, essentielle en phase d'appui","La stabilisation du pied","Une articulation de genou","Un appui thoracique"],"r":0,"e":"Les orthèses permettent la marche aux patients vertébro-médullaires.","s":16},{"q":"Selon Holland & Holland (2006), le standing-frame :","o":["Augmente l'indépendance, la fonctionnalité et l'estime de soi","Diminue la spasticité","Limite la perte osseuse","Améliore la circulation"],"r":0,"e":"Goktepe et al. (2008) documentent la limitation de la perte de densité minérale osseuse et Harvey (2008) la diminution de spasticité.","s":16},{"q":"Dans la marche à quatre points, les aides se placent :","o":["Au même niveau, à environ 15 cm devant et à l'extérieur de chaque pied","Au contact des pieds","30 cm devant","Derrière les pieds"],"r":0,"e":"La séquence alterne aide droite, membre gauche, aide gauche, membre droit.","s":16},{"q":"Dans la marche à trois points, le poids est réparti :","o":["Entre les aides et le membre inférieur sain","Entre les deux membres","Sur le membre lésé","Sur les seules aides"],"r":0,"e":"Les aides avancent simultanément, le membre lésé ne prenant aucun appui.","s":16},{"q":"La profondeur de l'assise d'un fauteuil roulant se règle :","o":["À 5 à 7 cm de la région poplitée","Au contact du creux poplité","À 15 cm","Sans repère"],"r":0,"e":"L'assise doit permettre un angle de 90° aux hanches et aux genoux.","s":16},{"q":"La protection latérale du fauteuil roulant se place :","o":["À environ 2 à 3 cm des hanches","Au contact","À 10 cm","Sans réglage"],"r":0,"e":"Les accoudoirs permettent, eux, le repos des membres supérieurs coude à 90° et les push-ups.","s":16},{"q":"Le châssis du fauteuil roulant peut être :","o":["Articulé en X, donc pliable, ou rigide","Uniquement pliable","Uniquement rigide","Télescopique"],"r":0,"e":"Les dispositifs anti-chute préviennent les chutes arrière et facilitent le soulèvement avant aux trottoirs.","s":16},{"q":"Selon Youdas (2005), les béquilles axillaires sont :","o":["Plus efficaces pour contrôler le transfert partiel du poids","Moins efficaces","Équivalentes aux cannes","Contre-indiquées"],"r":0,"e":"Leur usage unilatéral est par ailleurs peu fréquent.","s":16},{"q":"Selon Bateni & Maki (2005), l'aide controlatérale réduit la charge coxo-fémorale de :","o":["60 %","30 %","80 %","20 %"],"r":0,"e":"C'est ce qui justifie l'usage du côté opposé à la dysfonction.","s":16},{"q":"Les repose-pieds du fauteuil roulant se règlent :","o":["Tibio-tarsienne en position neutre, à environ 5 cm du sol","Au contact du sol","À 15 cm du sol","En flexion plantaire"],"r":0,"e":"Ils peuvent être fixes ou amovibles, ce qui conditionne les transferts.","s":16}]};
